window.EXAMS = [{"title":"Exam 1","questions":[{"category":"Business & Tax","stem":"In a buy-sell arrangement, what can life insurance fund?","options":["Purchase of a deceased owner's business interest according to the agreement","Payment of the employee's disability income only","A guaranteed public share price","An unrelated property casualty deductible"],"answer":0,"explanation":"Life insurance can provide funds for ownership transition on a business owner's death.","conceptId":"C158","variant":1,"id":"E01Q01"},{"category":"Term & Whole Life","stem":"Which is the best example of decreasing term life?","options":["A variable annuity","A policy with an increasing guaranteed face amount","Coverage that declines as a mortgage balance is expected to decrease","A whole-life policy with rising cash value"],"answer":2,"explanation":"Decreasing term is often designed to match a falling debt balance.","conceptId":"C030","variant":1,"id":"E01Q02"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"The state insurance regulator.\" Which of the following would be the most accurate response?","options":["The state insurance regulator","Always the employee's children","The business, subject to consent and applicable rules","Every employee equally"],"answer":2,"explanation":"The business often applies for, owns, and benefits from key-person protection.","conceptId":"C159","variant":3,"id":"E01Q03"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"Increase the face amount every year.\" Select the statement that should replace this inaccurate advice.","options":["Guarantee a policy never carries interest","Use available cash value as a loan to pay overdue premiums when elected","Increase the face amount every year","Pay dividends to the producer"],"answer":1,"explanation":"Automatic premium loans can prevent lapse but create policy debt and interest.","conceptId":"C067","variant":4,"id":"E01Q04"},{"category":"Term & Whole Life","stem":"What is survivorship or second-to-die life insurance?","options":["Life insurance that covers only children","Two policies that each pay on first death","Coverage on two lives that generally pays upon the second insured's death","A rider that pays premiums after retirement"],"answer":2,"explanation":"Survivorship coverage is often considered in estate or legacy planning.","conceptId":"C048","variant":1,"id":"E01Q05"},{"category":"Business & Tax","stem":"A family estimates $480,000 in survivor income needs and $155,000 in debt; $210,000 in accessible assets can offset those needs. What is the unmet amount?","options":["$635,000","$845,000","$425,000","$270,000"],"answer":2,"explanation":"Coverage gap = 480,000 + 155,000 - 210,000 = 425,000.","conceptId":"X002","variant":1,"id":"E01Q06"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"One-year term option.\" Select the statement that should replace this inaccurate advice.","options":["Cash dividend option","Accumulation at interest","Premium reduction option","One-year term option"],"answer":2,"explanation":"The premium-reduction option applies declared dividends toward scheduled premium.","conceptId":"C045","variant":4,"id":"E01Q07"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Replace any contract with free insurance.\" Which of the following would be the most accurate response?","options":["Guarantee profit on a policy","Authorize an unlicensed agent","Replace any contract with free insurance","Allow regulators to investigate potentially unfair or unlawful insurer or agent conduct"],"answer":3,"explanation":"CDI receives consumer complaints and oversees compliance with insurance rules.","conceptId":"C153","variant":3,"id":"E01Q08"},{"category":"Business & Tax","stem":"What is the usual federal tax treatment of dividends received on a participating life insurance policy up to basis?","options":["Always capital gains","Generally treated as a return of premium rather than taxable income","Always subject to payroll tax","Always taxed as ordinary income from the first dollar"],"answer":1,"explanation":"Life policy dividends commonly reduce the owner's cost basis; interest earned on retained dividends is typically taxable.","conceptId":"C161","variant":1,"id":"E01Q09"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"Exchange traded fund.\" Select the statement that should replace this inaccurate advice.","options":["Exchange traded fund","Fixed annuity","Variable annuity","Equity mutual fund"],"answer":1,"explanation":"Fixed annuities generally credit contractually specified or declared interest with applicable guarantees.","conceptId":"C086","variant":4,"id":"E01Q10"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"To appoint the policyholder's attorney.\" Which of the following would be the most accurate response?","options":["To assess compliance and financial or market conduct condition","To appoint the policyholder's attorney","To set a consumer's beneficiary selection","To guarantee its stock appreciates"],"answer":0,"explanation":"Insurance departments supervise insurer solvency and market conduct.","conceptId":"C143","variant":3,"id":"E01Q11"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"Federal tax refunds.\" Select the statement that should replace this inaccurate advice.","options":["Mandatory annual cash withdrawals","Guaranteed stock dividends","Federal tax refunds","Non-guaranteed policy dividends"],"answer":3,"explanation":"Mutual or participating policy dividends depend on the insurer's divisible surplus and are not guaranteed.","conceptId":"C042","variant":4,"id":"E01Q12"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"Alter answers after the applicant signs.\" Select the statement that should replace this inaccurate advice.","options":["Alter answers after the applicant signs","Record answers accurately and submit complete information to the insurer","Suggest concealing relevant medical history","Guarantee approval without underwriting"],"answer":1,"explanation":"Agents must transmit accurate application information and should not misrepresent material facts.","conceptId":"C108","variant":4,"id":"E01Q13"},{"category":"Fundamentals","stem":"What describes a conditional insurance contract?","options":["Every claim is automatically disputed","The insurer's obligation depends on contractual conditions being satisfied","The applicant sets premium after a claim","Claims are paid whether or not coverage exists"],"answer":1,"explanation":"Payment of benefits depends on conditions such as policy being in force and proof of covered death.","conceptId":"C006","variant":1,"id":"E01Q14"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"An employee's car against theft.\" Which answer most accurately corrects the misunderstanding?","options":["The company's group health deductible","An employee's car against theft","A business from financial loss caused by death of an important employee or owner","Every shareholder from stock-price declines"],"answer":2,"explanation":"Key-person insurance can provide liquidity while the company recruits or replaces key talent.","conceptId":"C157","variant":2,"id":"E01Q15"},{"category":"Business & Tax","stem":"What is contributory group life insurance?","options":["Coverage in which members pay some or all of the premium cost","Coverage paid entirely by an employer only","A policy without an insured","A policy owned by the federal government"],"answer":0,"explanation":"Contributory plans require employee contributions, unlike noncontributory plans funded by the sponsor.","conceptId":"C181","variant":1,"id":"E01Q16"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"Guarantee investment gains.\" Which answer most accurately corrects the misunderstanding?","options":["Avoid insurer solvency requirements","Guarantee investment gains","Restrict a beneficiary's ability to assign or prematurely spend certain proceeds under the arrangement","Make every beneficiary irrevocable"],"answer":2,"explanation":"Spendthrift arrangements can control access to proceeds and may provide creditor protections subject to law.","conceptId":"C077","variant":2,"id":"E01Q17"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"To substitute for the applicant's signature.\" Select the statement that should replace this inaccurate advice.","options":["To demonstrate the basis for a suitable recommendation and preserve accurate records","To substitute for the applicant's signature","To avoid providing disclosures","To guarantee investment performance"],"answer":0,"explanation":"Documenting needs, costs, and decisions helps support compliant recommendations.","conceptId":"C146","variant":4,"id":"E01Q18"},{"category":"Ethics & CA Law","stem":"What is the best practice when a policy replacement is proposed?","options":["Compare the existing and proposed contracts, including surrender charges and lost guarantees","Focus only on the new policy's first-year premium","Assume the new contract is always better","Ignore existing beneficiaries"],"answer":0,"explanation":"Replacement analysis should consider costs, timing, exclusions, taxes and lost rights.","conceptId":"C141","variant":1,"id":"E01Q19"},{"category":"Fundamentals","stem":"When does insurable interest generally need to exist for an individually purchased life policy?","options":["Only when the beneficiary files a claim","When the contract is made","Only when the insured dies","At every annual renewal"],"answer":1,"explanation":"Insurable interest is generally required at policy inception, not continuously throughout the policy.","conceptId":"C021","variant":1,"id":"E01Q20"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"An automatic full refund of all employer premiums.\" Which answer most accurately corrects the misunderstanding?","options":["Conversion from life to car insurance","Unlimited free coverage forever","An automatic full refund of all employer premiums","Eligible departing members to change group life coverage to an individual policy within specified rules"],"answer":3,"explanation":"Group conversion may preserve some protection without medical underwriting if exercised promptly.","conceptId":"C180","variant":2,"id":"E01Q21"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"Stock market loss.\" Select the statement that should replace this inaccurate advice.","options":["Premium payment if the person paying premiums dies or becomes disabled as defined","Death benefits for the agent","Stock market loss","Property loss at the child's school"],"answer":0,"explanation":"Payor riders protect juvenile policies when the paying adult suffers a covered event.","conceptId":"C074","variant":4,"id":"E01Q22"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"The policy converts to disability insurance.\" Select the statement that should replace this inaccurate advice.","options":["The policy converts to disability insurance","The producer pays the difference personally","Benefits or premiums are adjusted to reflect the correct age","The policy is automatically void for every age error"],"answer":2,"explanation":"A wrong age typically leads to an actuarial adjustment rather than automatically voiding the contract.","conceptId":"C056","variant":4,"id":"E01Q23"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"Surrendering a life policy for a check.\" Which answer most accurately corrects the misunderstanding?","options":["Converting annuity value into a series of income payments under a payout option","Adding an accidental death rider","Naming a beneficiary","Surrendering a life policy for a check"],"answer":0,"explanation":"Annuitization starts a payout structure often based on life expectancy, rate, and options.","conceptId":"C088","variant":2,"id":"E01Q24"},{"category":"Term & Whole Life","stem":"What can happen to universal life when cash value is insufficient to cover ongoing charges?","options":["The insurer must waive all charges forever","The death benefit doubles automatically","The policy can lapse unless additional funding or a guarantee prevents it","The beneficiary must pay premiums after death"],"answer":2,"explanation":"Flexible premiums do not eliminate the requirement to fund mortality and expenses.","conceptId":"C036","variant":1,"id":"E01Q25"},{"category":"Provisions & Riders","stem":"When is a contingent beneficiary ordinarily paid?","options":["When the insured turns 65","When a premium is late","Before the primary beneficiary in all cases","When the primary beneficiary is not eligible or does not survive under policy terms"],"answer":3,"explanation":"Contingent beneficiaries are backups to the primary designation.","conceptId":"C060","variant":1,"id":"E01Q26"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"A casino wager.\" Which of the following would be the most accurate response?","options":["Pure risk involving possible loss but no opportunity for gain","A casino wager","A business venture seeking profit","A speculative bet on stock prices"],"answer":0,"explanation":"Pure risks involve loss or no loss, while speculative risks include a possibility of gain.","conceptId":"C007","variant":3,"id":"E01Q27"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"The annual producer commission.\" Select the statement that should replace this inaccurate advice.","options":["The sum of all premiums already paid","The policy's guaranteed loan rate","The annual producer commission","The stated death benefit before adjustments under policy terms"],"answer":3,"explanation":"Face amount is the amount of coverage shown on the policy; loans or riders may adjust proceeds.","conceptId":"C017","variant":4,"id":"E01Q28"},{"category":"Fundamentals","stem":"What is the primary purpose of life insurance?","options":["To guarantee investment profits","To provide financial protection against premature death","To eliminate every financial risk","To insure a home against fire"],"answer":1,"explanation":"Life insurance transfers the financial risk of an insured person's death to the insurer.","conceptId":"C001","variant":1,"id":"E01Q29"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"The death benefit always doubles.\" Which answer most accurately corrects the misunderstanding?","options":["The death benefit always doubles","The insured's heirs automatically owe the full face amount","The balance and accrued interest generally reduce benefits paid","The loan is paid by the state"],"answer":2,"explanation":"Policy loan debt generally offsets death proceeds and may create lapse or tax risks.","conceptId":"C068","variant":2,"id":"E01Q30"},{"category":"Business & Tax","stem":"What is an estate liquidity need?","options":["The insurer's investment expense","Cash required by an estate to pay obligations without forced asset sales","The insured's monthly disability benefit","A guarantee all estates owe federal estate tax"],"answer":1,"explanation":"Life insurance can provide liquidity for taxes, debts and settlement costs if structured appropriately.","conceptId":"C170","variant":1,"id":"E01Q31"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"Traditional endowment.\" Select the statement that should replace this inaccurate advice.","options":["Variable whole life","Traditional endowment","Level term life","Whole life"],"answer":2,"explanation":"Term insurance generally provides a death benefit during its term without savings value.","conceptId":"C025","variant":4,"id":"E01Q32"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"To pay the agent's commissions.\" Which of the following would be the most accurate response?","options":["To inspect roof shingles for life claims","To replace all medical evidence","To gather permitted background information relevant to underwriting","To pay the agent's commissions"],"answer":2,"explanation":"Inspection reports may assess finances, activities, and reputation consistent with law and consent.","conceptId":"C115","variant":3,"id":"E01Q33"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"The amount of commission paid.\" Which answer most accurately corrects the misunderstanding?","options":["The amount of commission paid","The number of applications rejected","The rate of death in a defined group","The interest on policy loans"],"answer":2,"explanation":"Mortality assumptions help insurers estimate expected death claims.","conceptId":"C009","variant":2,"id":"E01Q34"},{"category":"Annuities & Retirement","stem":"What is the main purpose of a beneficiary designation on an annuity?","options":["To eliminate income tax in all cases","To choose the insurer's chief executive","To direct any payable death benefit or remaining contract value under contract terms","To guarantee annual returns"],"answer":2,"explanation":"A designation determines who receives amounts payable at death subject to the contract and law.","conceptId":"C099","variant":1,"id":"E01Q35"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"The Insurance Commissioner.\" Which of the following would be the most accurate response?","options":["The contingent beneficiary by law","The insurer's reinsurer","The Insurance Commissioner","The policyowner"],"answer":3,"explanation":"The owner is responsible for funding the policy unless another payer is arranged.","conceptId":"C169","variant":3,"id":"E01Q36"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"A beneficiary who is always paid first during the insured's life.\" Select the statement that should replace this inaccurate advice.","options":["A beneficiary who cannot receive money","A beneficiary who owns the insurer","A beneficiary who is always paid first during the insured's life","A beneficiary the owner generally can change without that beneficiary's permission"],"answer":3,"explanation":"Revocable beneficiary designations can normally be changed by the policyowner.","conceptId":"C058","variant":4,"id":"E01Q37"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Automatic payment of a death benefit.\" Which answer most accurately corrects the misunderstanding?","options":["A current health statement or further underwriting as the insurer requires","A beneficiary affidavit for all applications","Automatic payment of a death benefit","A reduction of the insurer's license fee"],"answer":0,"explanation":"A material health change before effective coverage may affect eligibility and the insurer's requirements.","conceptId":"C120","variant":2,"id":"E01Q38"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"A guaranteed dividend rate.\" Which of the following would be the most accurate response?","options":["An automatic waiver of premiums","A statement made to the best of the applicant's knowledge and belief","A guaranteed dividend rate","A promise that every future event will occur"],"answer":1,"explanation":"Application answers are generally representations, and material misrepresentations may affect coverage.","conceptId":"C019","variant":3,"id":"E01Q39"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Omit it because the client requested it.\" Which answer most accurately corrects the misunderstanding?","options":["Alter the physician's records","Omit it because the client requested it","Explain that answers must be truthful and submit complete information","Promise the condition cannot be discovered"],"answer":2,"explanation":"Concealing material facts can be fraud and threaten coverage.","conceptId":"C140","variant":2,"id":"E01Q40"},{"category":"Ethics & CA Law","stem":"What is twisting in the sale of life insurance?","options":["Notifying an insurer of an address change","Explaining legitimate policy differences accurately","Giving a client a copy of the policy","Using misleading comparisons or representations to induce an improper policy replacement"],"answer":3,"explanation":"Twisting involves misrepresentation to persuade a customer to replace coverage.","conceptId":"C131","variant":1,"id":"E01Q41"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Promise that all policies have no taxes of any kind.\" Which answer most accurately corrects the misunderstanding?","options":["Promise that all policies have no taxes of any kind","Ignore policy ownership","Say only beneficiaries ever owe income tax","Explain that tax treatment varies by policy, ownership, and circumstances and avoid absolute claims"],"answer":3,"explanation":"Death benefits are generally income-tax-free to beneficiaries but estate, transfer, and other rules can apply.","conceptId":"C150","variant":2,"id":"E01Q42"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"To be the policy's insured automatically.\" Select the statement that should replace this inaccurate advice.","options":["To receive the death benefit first when eligible under the designation","To be the policy's insured automatically","To pay insurance premiums as a legal requirement","To approve every policy loan"],"answer":0,"explanation":"A primary beneficiary has first priority to receive proceeds subject to designation and applicable law.","conceptId":"C076","variant":4,"id":"E01Q43"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"Guaranteeing every rider is free.\" Which of the following would be the most accurate response?","options":["Guaranteeing every rider is free","Returning the application to the insured without issuing a policy","Forgoing any premium due","Providing the issued contract and explaining relevant terms and changes"],"answer":3,"explanation":"Delivery is when the policyowner receives and can review the contract.","conceptId":"C119","variant":3,"id":"E01Q44"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Paying an approved policy dividend.\" Which answer most accurately corrects the misunderstanding?","options":["Giving a standard premium quote","Offering an inducement not specified in the policy, where prohibited by applicable law","Explaining a free-look right","Paying an approved policy dividend"],"answer":1,"explanation":"Rebating rules restrict improper inducements to buy insurance; assess conduct under current California law.","conceptId":"C132","variant":2,"id":"E01Q45"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"To protect a lender's property against fire.\" Which answer most accurately corrects the misunderstanding?","options":["To pay a covered outstanding debt if the insured borrower dies","To protect a lender's property against fire","To replace disability income","To insure a company's stock price"],"answer":0,"explanation":"Credit life is tied to a debt obligation and commonly has a decreasing benefit.","conceptId":"C050","variant":2,"id":"E01Q46"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"The price of the producer's license.\" Which of the following would be the most accurate response?","options":["Economic value of the insured's future earnings available to dependents","The insurer's stock market capitalization","The replacement cost of the insured's house only","The price of the producer's license"],"answer":0,"explanation":"Human life value estimates the present value of expected future income contributions.","conceptId":"C166","variant":3,"id":"E01Q47"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"A guaranteed policy dividend.\" Select the statement that should replace this inaccurate advice.","options":["An automatic retirement annuity","A guaranteed policy dividend","An additional benefit when death meets the rider's definition of accident","A refund whenever the insured gets sick"],"answer":2,"explanation":"Accidental death riders pay only under defined accidental-death conditions and exclusions.","conceptId":"C071","variant":4,"id":"E01Q48"},{"category":"Underwriting & Claims","stem":"What is an exclusion in an insurance policy?","options":["A policy dividend distribution","A specified circumstance or risk the contract does not cover","A premium due date","An additional guaranteed benefit"],"answer":1,"explanation":"Exclusions describe limits on the insurer's coverage obligation.","conceptId":"C121","variant":1,"id":"E01Q49"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"The state insurance department.\" Which answer most accurately corrects the misunderstanding?","options":["The contractowner","The named beneficiary only","The state insurance department","The insurance producer personally"],"answer":0,"explanation":"Variable annuity separate-account performance affects contract value, subject to any specific guarantees.","conceptId":"C105","variant":2,"id":"E01Q50"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"Direct ownership of individual index stocks by the owner.\" Which answer most accurately corrects the misunderstanding?","options":["A contractual formula referencing an external index rather than direct stock ownership","A federally insured bank deposit rate","A guaranteed equal share of index dividends","Direct ownership of individual index stocks by the owner"],"answer":0,"explanation":"Index crediting uses a formula, often with caps, spreads, or participation rates.","conceptId":"C100","variant":2,"id":"E01Q51"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"Settlement option.\" Which of the following would be the most accurate response?","options":["Insuring clause","Assignment","Settlement option","Renewability"],"answer":3,"explanation":"A renewable term feature permits renewal for another term without a new medical examination, usually at higher age-based rates.","conceptId":"C027","variant":3,"id":"E01Q52"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"Fixed-period option.\" Select the statement that should replace this inaccurate advice.","options":["Lump-sum option","Fixed-period option","Interest-only option","Life income option"],"answer":3,"explanation":"Life income bases periodic payments on a payee's lifetime, often with optional guarantees.","conceptId":"C078","variant":4,"id":"E01Q53"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Only the insurer's commission.\" Which of the following would be the most accurate response?","options":["A fixed share of the insured's salary","Interest on proceeds retained by the insurer","Only the insurer's commission","The entire principal each month"],"answer":1,"explanation":"The insurer retains principal and pays interest as stipulated; principal is handled under the agreement.","conceptId":"C079","variant":3,"id":"E01Q54"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"Traditional fixed annuity.\" Which answer most accurately corrects the misunderstanding?","options":["Variable annuity","Fixed immediate annuity without investment choice","Straight term insurance","Traditional fixed annuity"],"answer":0,"explanation":"Variable annuities expose account values to underlying investment performance.","conceptId":"C087","variant":2,"id":"E01Q55"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"Only beneficiaries' jobs matter.\" Which of the following would be the most accurate response?","options":["Occupation never matters","Some occupations carry greater mortality hazards","Only beneficiaries' jobs matter","A job title determines the insurer's solvency"],"answer":1,"explanation":"Occupational hazards may influence risk assessment and rates.","conceptId":"C117","variant":3,"id":"E01Q56"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"A beneficiary purchases a policy loan.\" Which answer most accurately corrects the misunderstanding?","options":["An insurer transfers part of its insurance risk to another insurer","The applicant changes insurers after death","A beneficiary purchases a policy loan","An agent renews their license"],"answer":0,"explanation":"Reinsurance lets a ceding company share risk with a reinsurer.","conceptId":"C018","variant":2,"id":"E01Q57"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"To cancel all premium charges.\" Which of the following would be the most accurate response?","options":["To insure a charity's building against fire","To force a policy to become an annuity","To cancel all premium charges","To direct eligible policy proceeds to a named charitable organization"],"answer":3,"explanation":"A policy can name a charity as beneficiary subject to policy and tax considerations.","conceptId":"C168","variant":3,"id":"E01Q58"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"The contingent beneficiary.\" Which of the following would be the most accurate response?","options":["The contingent beneficiary","The insured's physician","The reinsurer","The policyowner"],"answer":3,"explanation":"The policyowner controls contractual rights such as beneficiary changes when permitted.","conceptId":"C016","variant":3,"id":"E01Q59"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"Predict the exact death date of each insured.\" Which answer most accurately corrects the misunderstanding?","options":["Predict aggregate losses more reliably for a large group","Predict the exact death date of each insured","Eliminate underwriting","Guarantee no claims occur"],"answer":0,"explanation":"A large population makes actual mortality experience more predictable in aggregate.","conceptId":"C008","variant":2,"id":"E01Q60"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"50 hours of auto insurance repair.\" Select the statement that should replace this inaccurate advice.","options":["100 hours of federal tax law","50 hours of auto insurance repair","12 hours of study on ethics and the California Insurance Code","No ethics study at all"],"answer":2,"explanation":"CDI requires the specified 12 hours of ethics and Insurance Code study for affected applicants.","conceptId":"C156","variant":4,"id":"E01Q61"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"The state insurance commissioner.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer's claims manager","The state insurance commissioner","Always the beneficiary and never the owner","The person whose life is used to determine annuity payments under life-contingent options"],"answer":3,"explanation":"The annuitant's life may measure how long payments continue.","conceptId":"C089","variant":2,"id":"E01Q62"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"To determine who inherits the insured's estate.\" Which answer most accurately corrects the misunderstanding?","options":["To determine who inherits the insured's estate","To guarantee every application is accepted","To handle only property claims","To evaluate applicants and decide whether and on what terms coverage will be offered"],"answer":3,"explanation":"Underwriting evaluates risk characteristics and assigns a classification or decision.","conceptId":"C107","variant":2,"id":"E01Q63"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"It is automatically passed by completing this practice app.\" Select the statement that should replace this inaccurate advice.","options":["It contains 25 questions with unlimited time","It is automatically passed by completing this practice app","It contains 150 questions and must be completed in 30 minutes","It contains 75 questions, with 105 minutes allowed"],"answer":3,"explanation":"The October 2026 PSI candidate bulletin lists 75 questions and 105 minutes for the Life license exam.","conceptId":"C154","variant":4,"id":"E01Q64"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"To transfer ownership automatically.\" Which of the following would be the most accurate response?","options":["To guarantee a stock price","To transfer ownership automatically","To determine the agent's tax return","To support financial underwriting and justify a large coverage amount"],"answer":3,"explanation":"Financial underwriting evaluates coverage need and potential overinsurance or anti-selection.","conceptId":"C118","variant":3,"id":"E01Q65"},{"category":"Ethics & CA Law","stem":"When an agent learns of a mistake on a submitted application, what is appropriate?","options":["Wait until after a claim","Ask a beneficiary to sign for the insured","Promptly notify the insurer and correct it through approved procedures","Quietly change a signed form without consent"],"answer":2,"explanation":"Application corrections must be accurate and properly authorized.","conceptId":"C148","variant":1,"id":"E01Q66"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"To guarantee any claim at any time without exception.\" Which answer most accurately corrects the misunderstanding?","options":["To set the owner's dividend rate","To specify how claims are handled if suicide occurs during the initial exclusion period","To guarantee any claim at any time without exception","To prohibit any death benefit payment forever"],"answer":1,"explanation":"Suicide clauses typically limit early suicide claims, often returning premiums, with rules varying by jurisdiction.","conceptId":"C125","variant":2,"id":"E01Q67"},{"category":"Term & Whole Life","stem":"What is a graded death benefit in a life policy?","options":["A beneficiary's medical deductible","A death benefit that may be restricted during an initial period under policy terms","Coverage that doubles every month","A guaranteed annual premium refund"],"answer":1,"explanation":"Some simplified-issue products limit early nonaccidental death benefits; review policy details.","conceptId":"C047","variant":1,"id":"E01Q68"},{"category":"Business & Tax","stem":"What is typically the federal income-tax consequence of a life insurance policy loan on a non-MEC policy that stays in force?","options":["Usually no current income tax on the loan, but lapse or surrender can trigger taxable gain","Automatically a tax-free gift to the producer","Always deductible interest","Always an immediate tax on the entire death benefit"],"answer":0,"explanation":"Policy loans can be tax-efficient but create interest and potential taxable lapse risk.","conceptId":"C162","variant":1,"id":"E01Q69"},{"category":"Annuities & Retirement","stem":"What does an annuity's accumulation phase describe?","options":["The time required to file a death certificate","The period during an insurer's bankruptcy","The period after all payments are finished","The period in which money is contributed and grows before systematic payout"],"answer":3,"explanation":"Accumulation precedes payout or annuitization in a deferred contract.","conceptId":"C101","variant":1,"id":"E01Q70"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"An owner to avoid all taxes forever.\" Which of the following would be the most accurate response?","options":["The policyowner to review the delivered policy and return it within the allowed period under applicable terms","The insurer to ignore the application","An owner to avoid all taxes forever","A beneficiary to set the premium"],"answer":0,"explanation":"Free look permits cancellation within a specified review window, with refund terms governed by law and policy.","conceptId":"C075","variant":3,"id":"E01Q71"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"A federal insurer of life benefits.\" Which answer most accurately corrects the misunderstanding?","options":["A federal insurer of life benefits","An information exchange used by member insurers in underwriting, subject to privacy rules","A company that guarantees claim payment","A regulator that issues agents' licenses"],"answer":1,"explanation":"MIB information can flag relevant application data; insurers must verify information as appropriate.","conceptId":"C110","variant":2,"id":"E01Q72"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"A beneficiary who receives no rights.\" Which of the following would be the most accurate response?","options":["A beneficiary who receives no rights","A beneficiary named only for one day","A beneficiary always selected by the insurer","A beneficiary whose consent is generally required for changes affecting their protected interest"],"answer":3,"explanation":"An irrevocable designation limits the owner's ability to change the beneficiary or impair their interest.","conceptId":"C059","variant":3,"id":"E01Q73"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"Credit life only.\" Select the statement that should replace this inaccurate advice.","options":["Credit life only","Traditional whole life only","Fixed term life","Variable universal life"],"answer":3,"explanation":"Variable universal life combines UL flexibility and market-linked separate-account investments.","conceptId":"C038","variant":4,"id":"E01Q74"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"A mandatory investment advisory account.\" Which of the following would be the most accurate response?","options":["An optional contractual feature that changes benefits or guarantees, often for a fee","A guaranteed public tax deduction","The same as a death certificate","A mandatory investment advisory account"],"answer":0,"explanation":"Riders can add features such as living income benefits; their costs and limitations matter.","conceptId":"C106","variant":3,"id":"E01Q75"}]},{"title":"Exam 2","questions":[{"category":"Ethics & CA Law","stem":"What is rebating in an insurance sales context?","options":["Giving a standard premium quote","Offering an inducement not specified in the policy, where prohibited by applicable law","Explaining a free-look right","Paying an approved policy dividend"],"answer":1,"explanation":"Rebating rules restrict improper inducements to buy insurance; assess conduct under current California law.","conceptId":"C132","variant":1,"id":"E02Q01"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"The insurer is a mutual fund.\" Which of the following would be the most accurate response?","options":["The death benefit becomes taxable annually","Index-linked crediting and policy values are not guaranteed at that illustrated rate","The insurer is a mutual fund","All index crediting is guaranteed at 15%"],"answer":1,"explanation":"Illustrated non-guaranteed values must not be described as guaranteed results.","conceptId":"C147","variant":3,"id":"E02Q02"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"A beneficiary always selected by the insurer.\" Select the statement that should replace this inaccurate advice.","options":["A beneficiary always selected by the insurer","A beneficiary named only for one day","A beneficiary whose consent is generally required for changes affecting their protected interest","A beneficiary who receives no rights"],"answer":2,"explanation":"An irrevocable designation limits the owner's ability to change the beneficiary or impair their interest.","conceptId":"C059","variant":4,"id":"E02Q03"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"$5,400.\" Which of the following would be the most accurate response?","options":["$495","$450","$540","$5,400"],"answer":2,"explanation":"Annual premium at $45 monthly is 12 × $45 = $540.","conceptId":"C174","variant":3,"id":"E02Q04"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"To replace disability income.\" Which of the following would be the most accurate response?","options":["To insure a company's stock price","To pay a covered outstanding debt if the insured borrower dies","To protect a lender's property against fire","To replace disability income"],"answer":1,"explanation":"Credit life is tied to a debt obligation and commonly has a decreasing benefit.","conceptId":"C050","variant":3,"id":"E02Q05"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"They are taxable every year before death.\" Select the statement that should replace this inaccurate advice.","options":["They are always capital gains","They are taxable every year before death","They are always taxed as ordinary wages","They are generally excluded from gross income, with important exceptions"],"answer":3,"explanation":"IRC Section 101(a) generally excludes death proceeds from income, subject to exceptions such as transfer-for-value.","conceptId":"C160","variant":4,"id":"E02Q06"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"Credit life insurance.\" Select the statement that should replace this inaccurate advice.","options":["Mortgage decreasing term","A one-year level term policy","Credit life insurance","A lifetime income annuity"],"answer":3,"explanation":"Lifetime annuity income can mitigate the risk of outliving retirement resources.","conceptId":"C104","variant":4,"id":"E02Q07"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"A beneficiary who cannot receive money.\" Which of the following would be the most accurate response?","options":["A beneficiary the owner generally can change without that beneficiary's permission","A beneficiary who is always paid first during the insured's life","A beneficiary who cannot receive money","A beneficiary who owns the insurer"],"answer":0,"explanation":"Revocable beneficiary designations can normally be changed by the policyowner.","conceptId":"C058","variant":3,"id":"E02Q08"},{"category":"Ethics & CA Law","stem":"What is defamation in unfair insurance trade practices?","options":["Making false malicious statements intended to injure an insurer's reputation or business","Comparing policy guarantees factually","Disclosing a policy's exclusions","Explaining an insurer's financial rating with attribution"],"answer":0,"explanation":"Unfair trade practices can prohibit knowingly false or malicious statements about competitors.","conceptId":"C139","variant":1,"id":"E02Q09"},{"category":"Term & Whole Life","stem":"In a traditional whole life policy, premiums are generally what?","options":["Always recalculated monthly based on stock returns","Paid only when death occurs","Fixed and payable under the chosen premium schedule","Required only in the first month"],"answer":2,"explanation":"Ordinary whole life generally uses scheduled level premiums.","conceptId":"C032","variant":1,"id":"E02Q10"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"Coverage can never terminate when employment ends.\" Select the statement that should replace this inaccurate advice.","options":["Coverage may be accessible with simplified enrollment at group rates","Coverage can never terminate when employment ends","Cash value is always guaranteed","Employees always own lifelong portable coverage"],"answer":0,"explanation":"Group term may be convenient but has portability and coverage-limit considerations.","conceptId":"C178","variant":4,"id":"E02Q11"},{"category":"Annuities & Retirement","stem":"What is the annuitant?","options":["The state insurance commissioner","The person whose life is used to determine annuity payments under life-contingent options","Always the beneficiary and never the owner","The insurer's claims manager"],"answer":1,"explanation":"The annuitant's life may measure how long payments continue.","conceptId":"C089","variant":1,"id":"E02Q12"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"The insurer to ignore the application.\" Select the statement that should replace this inaccurate advice.","options":["The insurer to ignore the application","The policyowner to review the delivered policy and return it within the allowed period under applicable terms","A beneficiary to set the premium","An owner to avoid all taxes forever"],"answer":1,"explanation":"Free look permits cancellation within a specified review window, with refund terms governed by law and policy.","conceptId":"C075","variant":4,"id":"E02Q13"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Say only beneficiaries ever owe income tax.\" Which of the following would be the most accurate response?","options":["Say only beneficiaries ever owe income tax","Promise that all policies have no taxes of any kind","Explain that tax treatment varies by policy, ownership, and circumstances and avoid absolute claims","Ignore policy ownership"],"answer":2,"explanation":"Death benefits are generally income-tax-free to beneficiaries but estate, transfer, and other rules can apply.","conceptId":"C150","variant":3,"id":"E02Q14"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"Contribution.\" Select the statement that should replace this inaccurate advice.","options":["Indemnity","Contribution","Subrogation","Insurable interest"],"answer":3,"explanation":"Insurable interest discourages wagering on human life; it generally must exist when a life policy is purchased.","conceptId":"C002","variant":4,"id":"E02Q15"},{"category":"Term & Whole Life","stem":"Which type of life policy generally places investment risk on the policyowner through separate-account subaccounts?","options":["Traditional fixed whole life","Variable life insurance","Decreasing term","Annually renewable term"],"answer":1,"explanation":"Variable life values can rise or fall with selected investments; securities regulation applies.","conceptId":"C037","variant":1,"id":"E02Q16"},{"category":"Underwriting & Claims","stem":"What evidence is typically required to process a death claim?","options":["Proof of the beneficiary's salary only","Proof of death plus the insurer's claim forms and supporting records as needed","A new application for the deceased","A property inspection only"],"answer":1,"explanation":"A death certificate and claimant information are common components of a death claim.","conceptId":"C122","variant":1,"id":"E02Q17"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"Automatic change of insured person.\" Select the statement that should replace this inaccurate advice.","options":["Automatic change of insured person","Immediate payment of death proceeds to the living insured","Exchange into eligible permanent coverage without new evidence of insurability within the permitted period","Cancellation of premiums forever"],"answer":2,"explanation":"Conversion preserves a path to permanent life coverage subject to contract restrictions.","conceptId":"C028","variant":4,"id":"E02Q18"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"To replace state insurance regulation.\" Select the statement that should replace this inaccurate advice.","options":["To eliminate the need for a trustee","To manage policy ownership, beneficiary distributions, and possible estate planning objectives","To replace state insurance regulation","To guarantee unlimited tax exemption in all cases"],"answer":1,"explanation":"Trust structures can control ownership and distribution, but require legal and tax advice.","conceptId":"C176","variant":4,"id":"E02Q19"},{"category":"Term & Whole Life","stem":"What distinguishes whole life from term life?","options":["Term always has investment subaccounts","Whole life always has lower initial premiums","Whole life never has a surrender charge","Whole life generally provides lifelong protection and guaranteed cash value if required premiums are paid"],"answer":3,"explanation":"Traditional whole life includes permanent protection and a cash value schedule.","conceptId":"C031","variant":1,"id":"E02Q20"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"The insured's physician.\" Which answer most accurately corrects the misunderstanding?","options":["The contingent beneficiary","The policyowner","The reinsurer","The insured's physician"],"answer":1,"explanation":"The policyowner controls contractual rights such as beneficiary changes when permitted.","conceptId":"C016","variant":2,"id":"E02Q21"},{"category":"Business & Tax","stem":"What is noncontributory group life insurance?","options":["Coverage with premiums split evenly by law","Coverage that cannot have beneficiaries","Group coverage for which the sponsor pays the full premium","Individual coverage purchased through an agent"],"answer":2,"explanation":"Noncontributory coverage is financed by the employer or group sponsor.","conceptId":"C182","variant":1,"id":"E02Q22"},{"category":"Provisions & Riders","stem":"A life policy has a $200,000 face amount and an eligible accidental death rider doubling the payout when its conditions are met. What is the total payout for a covered accidental death, assuming no loans?","options":["$400,000","$600,000","$100,000","$200,000"],"answer":0,"explanation":"A qualifying double-indemnity rider adds another face amount: 200,000 + 200,000 = 400,000.","conceptId":"X006","variant":1,"id":"E02Q23"},{"category":"Provisions & Riders","stem":"What is the purpose of an accelerated death benefit rider?","options":["To allow an eligible insured to receive part of the death benefit while alive under qualifying conditions","To pay double benefits after every accidental injury","To eliminate all underwriting","To pay a benefit only after policy surrender"],"answer":0,"explanation":"Accelerated benefits advance proceeds for defined qualifying illness or other triggers and can reduce the later death benefit.","conceptId":"C072","variant":1,"id":"E02Q24"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"Credit card reward statement.\" Select the statement that should replace this inaccurate advice.","options":["Vehicle title report","Attending physician statement (APS)","Credit card reward statement","Property deed"],"answer":1,"explanation":"An APS may help an insurer understand medical conditions and treatment history.","conceptId":"C109","variant":4,"id":"E02Q25"},{"category":"Provisions & Riders","stem":"What does a payor benefit rider on juvenile life coverage generally address?","options":["Property loss at the child's school","Stock market loss","Death benefits for the agent","Premium payment if the person paying premiums dies or becomes disabled as defined"],"answer":3,"explanation":"Payor riders protect juvenile policies when the paying adult suffers a covered event.","conceptId":"C074","variant":1,"id":"E02Q26"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"An insurer's annual income statement.\" Select the statement that should replace this inaccurate advice.","options":["Evidence and summary of a member's coverage under the group master contract","An insurer's annual income statement","Proof the employee owns the master contract","A securities prospectus"],"answer":0,"explanation":"Certificates describe individual group coverage, while the master contract controls.","conceptId":"C179","variant":4,"id":"E02Q27"},{"category":"Business & Tax","stem":"A $500,000 policy has a $40,000 outstanding loan plus $2,000 accrued interest at death. Ignoring other adjustments, what proceeds remain?","options":["$542,000","$40,000","$458,000","$500,000"],"answer":2,"explanation":"Net death proceeds equal $500,000 minus $40,000 principal and $2,000 interest = $458,000.","conceptId":"C171","variant":1,"id":"E02Q28"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"Cash dividend option.\" Which of the following would be the most accurate response?","options":["Premium reduction option","Accumulation at interest","Cash dividend option","One-year term option"],"answer":0,"explanation":"The premium-reduction option applies declared dividends toward scheduled premium.","conceptId":"C045","variant":3,"id":"E02Q29"},{"category":"Provisions & Riders","stem":"What is the primary beneficiary's role?","options":["To approve every policy loan","To receive the death benefit first when eligible under the designation","To pay insurance premiums as a legal requirement","To be the policy's insured automatically"],"answer":1,"explanation":"A primary beneficiary has first priority to receive proceeds subject to designation and applicable law.","conceptId":"C076","variant":1,"id":"E02Q30"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"To eliminate income tax in all cases.\" Which of the following would be the most accurate response?","options":["To direct any payable death benefit or remaining contract value under contract terms","To choose the insurer's chief executive","To eliminate income tax in all cases","To guarantee annual returns"],"answer":0,"explanation":"A designation determines who receives amounts payable at death subject to the contract and law.","conceptId":"C099","variant":3,"id":"E02Q31"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"A rider that pays premiums after retirement.\" Select the statement that should replace this inaccurate advice.","options":["Coverage on two lives that generally pays upon the second insured's death","A rider that pays premiums after retirement","Two policies that each pay on first death","Life insurance that covers only children"],"answer":0,"explanation":"Survivorship coverage is often considered in estate or legacy planning.","conceptId":"C048","variant":4,"id":"E02Q32"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"An additional guaranteed benefit.\" Which answer most accurately corrects the misunderstanding?","options":["A premium due date","An additional guaranteed benefit","A specified circumstance or risk the contract does not cover","A policy dividend distribution"],"answer":2,"explanation":"Exclusions describe limits on the insurer's coverage obligation.","conceptId":"C121","variant":2,"id":"E02Q33"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"The policy reaches a stated cash value.\" Select the statement that should replace this inaccurate advice.","options":["The policyowner retires","The first insured in the covered pair dies","Both insureds have died","The policy reaches a stated cash value"],"answer":1,"explanation":"First-to-die coverage protects against the first death among insureds.","conceptId":"C049","variant":4,"id":"E02Q34"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"An account with unlimited liquidity.\" Which of the following would be the most accurate response?","options":["Every premium is refundable at any time","An account with unlimited liquidity","Income for life, with payments for at least a stated minimum period","Income only for a fixed period and never for life"],"answer":2,"explanation":"If death occurs during the period certain, remaining payments generally continue to the beneficiary.","conceptId":"C091","variant":3,"id":"E02Q35"},{"category":"Business & Tax","stem":"What does the conversion privilege under many group life plans allow?","options":["Conversion from life to car insurance","Unlimited free coverage forever","An automatic full refund of all employer premiums","Eligible departing members to change group life coverage to an individual policy within specified rules"],"answer":3,"explanation":"Group conversion may preserve some protection without medical underwriting if exercised promptly.","conceptId":"C180","variant":1,"id":"E02Q36"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"A fixed government pension payment.\" Select the statement that should replace this inaccurate advice.","options":["An index-crediting formula subject to caps, participation rates, floors, and contract charges","A guaranteed stock-market rate of return","Direct ownership of every stock in an index","A fixed government pension payment"],"answer":0,"explanation":"Indexed UL uses a contractual crediting method, not direct ownership of index shares.","conceptId":"C039","variant":4,"id":"E02Q37"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"A fixed share of the insured's salary.\" Select the statement that should replace this inaccurate advice.","options":["A fixed share of the insured's salary","The entire principal each month","Only the insurer's commission","Interest on proceeds retained by the insurer"],"answer":3,"explanation":"The insurer retains principal and pays interest as stipulated; principal is handled under the agreement.","conceptId":"C079","variant":4,"id":"E02Q38"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"To obtain auto insurance.\" Select the statement that should replace this inaccurate advice.","options":["To reduce the risk that all income stops immediately after an early death","To guarantee unlimited market growth","To avoid any income taxation","To obtain auto insurance"],"answer":0,"explanation":"Period-certain payments can continue to a beneficiary if death occurs during the guarantee period.","conceptId":"C102","variant":4,"id":"E02Q39"},{"category":"Fundamentals","stem":"Which is an example of a direct financial insurable interest?","options":["A stranger insuring a celebrity without consent","A gambler betting on a neighbor's death","A casual online follower insuring an influencer","A business insuring a key employee whose death would cause a financial loss"],"answer":3,"explanation":"Employers may have an insurable interest in key employees subject to applicable rules.","conceptId":"C022","variant":1,"id":"E02Q40"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"An automatic annual inflation increase.\" Which answer most accurately corrects the misunderstanding?","options":["Payments only after the beneficiary dies","A lifelong guaranteed payment irrespective of amount","A selected payment amount until proceeds and interest are exhausted","An automatic annual inflation increase"],"answer":2,"explanation":"Fixed amount fixes payment size rather than a guaranteed number of payments.","conceptId":"C081","variant":2,"id":"E02Q41"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"A policy without an insured.\" Select the statement that should replace this inaccurate advice.","options":["Coverage paid entirely by an employer only","A policy without an insured","A policy owned by the federal government","Coverage in which members pay some or all of the premium cost"],"answer":3,"explanation":"Contributory plans require employee contributions, unlike noncontributory plans funded by the sponsor.","conceptId":"C181","variant":4,"id":"E02Q42"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"It contains 25 questions with unlimited time.\" Which answer most accurately corrects the misunderstanding?","options":["It contains 150 questions and must be completed in 30 minutes","It contains 75 questions, with 105 minutes allowed","It is automatically passed by completing this practice app","It contains 25 questions with unlimited time"],"answer":1,"explanation":"The October 2026 PSI candidate bulletin lists 75 questions and 105 minutes for the Life license exam.","conceptId":"C154","variant":2,"id":"E02Q43"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"An agent renews their license.\" Select the statement that should replace this inaccurate advice.","options":["An insurer transfers part of its insurance risk to another insurer","A beneficiary purchases a policy loan","The applicant changes insurers after death","An agent renews their license"],"answer":0,"explanation":"Reinsurance lets a ceding company share risk with a reinsurer.","conceptId":"C018","variant":4,"id":"E02Q44"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"Guarantee approval without underwriting.\" Which of the following would be the most accurate response?","options":["Record answers accurately and submit complete information to the insurer","Alter answers after the applicant signs","Guarantee approval without underwriting","Suggest concealing relevant medical history"],"answer":0,"explanation":"Agents must transmit accurate application information and should not misrepresent material facts.","conceptId":"C108","variant":3,"id":"E02Q45"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"The producer's commission.\" Which of the following would be the most accurate response?","options":["The guaranteed annual death benefit","The amount payable to the owner upon surrender after applicable charges and loans","The producer's commission","The amount owed to the contingent beneficiary"],"answer":1,"explanation":"Net surrender value reflects contract cash values less surrender charges and outstanding debt.","conceptId":"C040","variant":3,"id":"E02Q46"},{"category":"Underwriting & Claims","stem":"What may be required if health changes between application and policy delivery?","options":["A reduction of the insurer's license fee","A current health statement or further underwriting as the insurer requires","Automatic payment of a death benefit","A beneficiary affidavit for all applications"],"answer":1,"explanation":"A material health change before effective coverage may affect eligibility and the insurer's requirements.","conceptId":"C120","variant":1,"id":"E02Q47"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"A medical plan for children.\" Which of the following would be the most accurate response?","options":["Term life coverage on eligible children attached to an adult policy","A medical plan for children","An increase in the adult's retirement income","A cash account only for college tuition"],"answer":0,"explanation":"Child riders provide limited death coverage on eligible children under the rider terms.","conceptId":"C073","variant":3,"id":"E02Q48"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Quietly change a signed form without consent.\" Which answer most accurately corrects the misunderstanding?","options":["Wait until after a claim","Quietly change a signed form without consent","Promptly notify the insurer and correct it through approved procedures","Ask a beneficiary to sign for the insured"],"answer":2,"explanation":"Application corrections must be accurate and properly authorized.","conceptId":"C148","variant":2,"id":"E02Q49"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"To insure a home against fire.\" Select the statement that should replace this inaccurate advice.","options":["To guarantee investment profits","To provide financial protection against premature death","To insure a home against fire","To eliminate every financial risk"],"answer":1,"explanation":"Life insurance transfers the financial risk of an insured person's death to the insurer.","conceptId":"C001","variant":4,"id":"E02Q50"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"The insurer's claim expenses.\" Which of the following would be the most accurate response?","options":["The insured's attained age","The scheduled premium","The insurer's claim expenses","The investment return"],"answer":1,"explanation":"Level-premium term has stable premiums for a stated guaranteed period.","conceptId":"C029","variant":3,"id":"E02Q51"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"The insurer's reinsurer.\" Select the statement that should replace this inaccurate advice.","options":["The contingent beneficiary by law","The Insurance Commissioner","The insurer's reinsurer","The policyowner"],"answer":3,"explanation":"The owner is responsible for funding the policy unless another payer is arranged.","conceptId":"C169","variant":4,"id":"E02Q52"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"A guaranteed equal share of index dividends.\" Which of the following would be the most accurate response?","options":["Direct ownership of individual index stocks by the owner","A federally insured bank deposit rate","A guaranteed equal share of index dividends","A contractual formula referencing an external index rather than direct stock ownership"],"answer":3,"explanation":"Index crediting uses a formula, often with caps, spreads, or participation rates.","conceptId":"C100","variant":3,"id":"E02Q53"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"Every surviving beneficiary receives an equal share regardless of branch.\" Which answer most accurately corrects the misunderstanding?","options":["Every surviving beneficiary receives an equal share regardless of branch","A deceased beneficiary's share passes down their family branch","Proceeds must be donated to charity","Only the oldest child receives proceeds"],"answer":1,"explanation":"Per stirpes allocation follows family branches; per capita generally divides among surviving members of the stated class.","conceptId":"C061","variant":2,"id":"E02Q54"},{"category":"Annuities & Retirement","stem":"Why is an annuity generally not a substitute for an emergency savings account?","options":["It always permits free instant withdrawals without charges","Withdrawals may face surrender charges, taxes, or limited liquidity","It is protected by FDIC deposit insurance as a bank checking account","It cannot earn any interest"],"answer":1,"explanation":"Annuity liquidity is contractual and can carry costs or taxes, making emergency access uncertain.","conceptId":"C103","variant":1,"id":"E02Q55"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"To guarantee everyone a job as an agent.\" Which answer most accurately corrects the misunderstanding?","options":["To ensure only qualified and authorized persons transact regulated insurance","To guarantee everyone a job as an agent","To replace insurance contracts with bank loans","To eliminate all private insurers"],"answer":0,"explanation":"Licensing protects consumers through qualification and regulatory oversight.","conceptId":"C145","variant":2,"id":"E02Q56"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"Only insurer dividends.\" Select the statement that should replace this inaccurate advice.","options":["Money in a tax-favored retirement plan or IRA","Only insurer dividends","Only life insurance death claims","Only after-tax funds that can never be deducted"],"answer":0,"explanation":"Qualified annuities are held within qualified retirement arrangements and follow their tax rules.","conceptId":"C098","variant":4,"id":"E02Q57"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"The applicant sets premium after a claim.\" Which of the following would be the most accurate response?","options":["The insurer's obligation depends on contractual conditions being satisfied","The applicant sets premium after a claim","Claims are paid whether or not coverage exists","Every claim is automatically disputed"],"answer":0,"explanation":"Payment of benefits depends on conditions such as policy being in force and proof of covered death.","conceptId":"C006","variant":3,"id":"E02Q58"},{"category":"Ethics & CA Law","stem":"If a client indicates they do not understand a policy replacement, what should the agent do?","options":["Explain the changes and material risks in understandable terms before proceeding","Tell the client reading is unnecessary","Hide the old policy values","Obtain a signature without explanation"],"answer":0,"explanation":"Informed consent requires understandable, accurate discussion of material changes.","conceptId":"C151","variant":1,"id":"E02Q59"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"A regulator that issues agents' licenses.\" Which of the following would be the most accurate response?","options":["A company that guarantees claim payment","A federal insurer of life benefits","An information exchange used by member insurers in underwriting, subject to privacy rules","A regulator that issues agents' licenses"],"answer":2,"explanation":"MIB information can flag relevant application data; insurers must verify information as appropriate.","conceptId":"C110","variant":3,"id":"E02Q60"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"A promise that every future event will occur.\" Which answer most accurately corrects the misunderstanding?","options":["A promise that every future event will occur","A guaranteed dividend rate","An automatic waiver of premiums","A statement made to the best of the applicant's knowledge and belief"],"answer":3,"explanation":"Application answers are generally representations, and material misrepresentations may affect coverage.","conceptId":"C019","variant":2,"id":"E02Q61"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"To determine a medical deductible.\" Select the statement that should replace this inaccurate advice.","options":["To set the beneficiary's age","To calculate the agent's commission","To determine the portion of each qualifying payment treated as return of investment versus taxable income","To determine a medical deductible"],"answer":2,"explanation":"The exclusion ratio allocates annuity payments between basis recovery and taxable income, when applicable.","conceptId":"C097","variant":4,"id":"E02Q62"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"To prohibit any death benefit payment forever.\" Select the statement that should replace this inaccurate advice.","options":["To specify how claims are handled if suicide occurs during the initial exclusion period","To set the owner's dividend rate","To prohibit any death benefit payment forever","To guarantee any claim at any time without exception"],"answer":0,"explanation":"Suicide clauses typically limit early suicide claims, often returning premiums, with rules varying by jurisdiction.","conceptId":"C125","variant":4,"id":"E02Q63"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"The state requires the applicant to own a car.\" Which answer most accurately corrects the misunderstanding?","options":["It verifies the beneficiary's occupation","The state requires the applicant to own a car","Driving history can indicate mortality-related risk","It replaces all application signatures"],"answer":2,"explanation":"Serious violations or risky driving can be relevant to life underwriting.","conceptId":"C124","variant":2,"id":"E02Q64"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"Avoid insurer solvency requirements.\" Which of the following would be the most accurate response?","options":["Avoid insurer solvency requirements","Restrict a beneficiary's ability to assign or prematurely spend certain proceeds under the arrangement","Make every beneficiary irrevocable","Guarantee investment gains"],"answer":1,"explanation":"Spendthrift arrangements can control access to proceeds and may provide creditor protections subject to law.","conceptId":"C077","variant":3,"id":"E02Q65"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"The insured's monthly disability benefit.\" Which of the following would be the most accurate response?","options":["The insured's monthly disability benefit","Cash required by an estate to pay obligations without forced asset sales","A guarantee all estates owe federal estate tax","The insurer's investment expense"],"answer":1,"explanation":"Life insurance can provide liquidity for taxes, debts and settlement costs if structured appropriately.","conceptId":"C170","variant":3,"id":"E02Q66"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"A beneficiary's new mailing address.\" Which of the following would be the most accurate response?","options":["A beneficiary's new mailing address","A producer's phone number change","An incorrect statement important to an insurer's underwriting decision","Any minor spelling error"],"answer":2,"explanation":"Materiality relates to whether accurate facts would have influenced acceptance, risk, or premium.","conceptId":"C020","variant":3,"id":"E02Q67"},{"category":"Ethics & CA Law","stem":"What is a producer's best response to questions about insurer financial strength?","options":["Promise the insurer can never fail","Use current credible financial information and avoid guarantees beyond policy terms","Quote an invented credit rating","Claim CDI guarantees all benefits in full"],"answer":1,"explanation":"Financial ratings are opinions, and policy guarantees depend on insurer claims-paying ability.","conceptId":"C152","variant":1,"id":"E02Q68"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"The insurer guarantees a low rate.\" Which of the following would be the most accurate response?","options":["The policy is automatically approved","The insurer will not issue coverage under the proposed terms","The applicant is the primary beneficiary","The insurer guarantees a low rate"],"answer":1,"explanation":"A decline means the application was not accepted under the insurer's underwriting criteria.","conceptId":"C126","variant":3,"id":"E02Q69"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"An insurer invests too conservatively.\" Which answer most accurately corrects the misunderstanding?","options":["The beneficiary changes an address","The producer earns a low commission","People with higher-than-average risk are more inclined to seek or keep coverage","An insurer invests too conservatively"],"answer":2,"explanation":"Underwriting helps control the tendency of high-risk applicants to disproportionately seek coverage.","conceptId":"C011","variant":2,"id":"E02Q70"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"It has no beneficiaries.\" Which of the following would be the most accurate response?","options":["Policyowners are not entitled to participate in insurer surplus through policy dividends","All death benefits are excluded","It must be term insurance","It has no beneficiaries"],"answer":0,"explanation":"Nonparticipating policies do not pay participating policy dividends.","conceptId":"C043","variant":3,"id":"E02Q71"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Explaining legitimate policy differences accurately.\" Which answer most accurately corrects the misunderstanding?","options":["Using misleading comparisons or representations to induce an improper policy replacement","Notifying an insurer of an address change","Giving a client a copy of the policy","Explaining legitimate policy differences accurately"],"answer":0,"explanation":"Twisting involves misrepresentation to persuade a customer to replace coverage.","conceptId":"C131","variant":2,"id":"E02Q72"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"A job title determines the insurer's solvency.\" Select the statement that should replace this inaccurate advice.","options":["Only beneficiaries' jobs matter","Some occupations carry greater mortality hazards","Occupation never matters","A job title determines the insurer's solvency"],"answer":1,"explanation":"Occupational hazards may influence risk assessment and rates.","conceptId":"C117","variant":4,"id":"E02Q73"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"The loan is paid by the state.\" Which of the following would be the most accurate response?","options":["The death benefit always doubles","The balance and accrued interest generally reduce benefits paid","The loan is paid by the state","The insured's heirs automatically owe the full face amount"],"answer":1,"explanation":"Policy loan debt generally offsets death proceeds and may create lapse or tax risks.","conceptId":"C068","variant":3,"id":"E02Q74"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"Predict the exact day of death.\" Which of the following would be the most accurate response?","options":["Predict the exact day of death","Guarantee future interest rates","Select the insurer with the highest commission","Estimate the survivor's financial obligations and resources to choose an appropriate coverage amount"],"answer":3,"explanation":"Needs analysis considers debts, income replacement, dependents, education, and existing assets.","conceptId":"C165","variant":3,"id":"E02Q75"}]},{"title":"Exam 3","questions":[{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"The number of applications rejected.\" Select the statement that should replace this inaccurate advice.","options":["The number of applications rejected","The amount of commission paid","The rate of death in a defined group","The interest on policy loans"],"answer":2,"explanation":"Mortality assumptions help insurers estimate expected death claims.","conceptId":"C009","variant":4,"id":"E03Q01"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"A beneficiary's right to make a claim.\" Which of the following would be the most accurate response?","options":["The right of the owner to change premium mode","The insurer's ability to contest the policy after the specified contestable period, subject to exceptions","A beneficiary's right to make a claim","The insurer's right to pay claims promptly"],"answer":1,"explanation":"After the contractual/statutory period, an insurer's grounds to contest validity are limited, with exceptions such as nonpayment.","conceptId":"C055","variant":3,"id":"E03Q02"},{"category":"Provisions & Riders","stem":"Which policy provision identifies the insurer's promise to pay for a covered death?","options":["Assignment clause","Misstatement of age clause","Grace period","Insuring clause"],"answer":3,"explanation":"The insuring clause states the principal coverage promise.","conceptId":"C052","variant":1,"id":"E03Q03"},{"category":"Business & Tax","stem":"Two primary beneficiaries are allocated 70% and 30% of a $400,000 policy. How much should the 30% beneficiary receive before other adjustments?","options":["$280,000","$400,000","$120,000","$200,000"],"answer":2,"explanation":"30% of 400,000 equals 120,000.","conceptId":"X003","variant":1,"id":"E03Q04"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"All medical questions can be omitted.\" Which of the following would be the most accurate response?","options":["The beneficiary automatically owns the policy","The insurer guarantees policy issuance","All medical questions can be omitted","The applicant attests to the statements and authorizations provided"],"answer":3,"explanation":"Signing confirms information and consents, not a promise that underwriting will approve coverage.","conceptId":"C024","variant":3,"id":"E03Q05"},{"category":"Business & Tax","stem":"What is a modified endowment contract (MEC)?","options":["A guaranteed pension from Social Security","A life insurance contract that fails the federal seven-pay test and receives less favorable distribution tax treatment","A contract with no life insurance death benefit","A policy cancelled during its free look"],"answer":1,"explanation":"MEC distributions and loans commonly have earnings-first taxation and may face early-distribution penalties.","conceptId":"C163","variant":1,"id":"E03Q06"},{"category":"Provisions & Riders","stem":"Which provision can allow a lapsed policy to return to force if policy requirements are satisfied?","options":["Free look only","Assignment","Entire contract","Reinstatement"],"answer":3,"explanation":"Reinstatement generally requires overdue payments and evidence of insurability as specified.","conceptId":"C054","variant":1,"id":"E03Q07"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"Ask a beneficiary to sign for the insured.\" Select the statement that should replace this inaccurate advice.","options":["Ask a beneficiary to sign for the insured","Promptly notify the insurer and correct it through approved procedures","Quietly change a signed form without consent","Wait until after a claim"],"answer":1,"explanation":"Application corrections must be accurate and properly authorized.","conceptId":"C148","variant":4,"id":"E03Q08"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Before the primary beneficiary in all cases.\" Which answer most accurately corrects the misunderstanding?","options":["When a premium is late","When the primary beneficiary is not eligible or does not survive under policy terms","When the insured turns 65","Before the primary beneficiary in all cases"],"answer":1,"explanation":"Contingent beneficiaries are backups to the primary designation.","conceptId":"C060","variant":2,"id":"E03Q09"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"A federally insured bank deposit rate.\" Select the statement that should replace this inaccurate advice.","options":["A federally insured bank deposit rate","A guaranteed equal share of index dividends","A contractual formula referencing an external index rather than direct stock ownership","Direct ownership of individual index stocks by the owner"],"answer":2,"explanation":"Index crediting uses a formula, often with caps, spreads, or participation rates.","conceptId":"C100","variant":4,"id":"E03Q10"},{"category":"Provisions & Riders","stem":"What does a spendthrift clause or spendthrift trust arrangement seek to accomplish?","options":["Restrict a beneficiary's ability to assign or prematurely spend certain proceeds under the arrangement","Make every beneficiary irrevocable","Avoid insurer solvency requirements","Guarantee investment gains"],"answer":0,"explanation":"Spendthrift arrangements can control access to proceeds and may provide creditor protections subject to law.","conceptId":"C077","variant":1,"id":"E03Q11"},{"category":"Term & Whole Life","stem":"What is indexed universal life most directly linked to?","options":["An index-crediting formula subject to caps, participation rates, floors, and contract charges","Direct ownership of every stock in an index","A fixed government pension payment","A guaranteed stock-market rate of return"],"answer":0,"explanation":"Indexed UL uses a contractual crediting method, not direct ownership of index shares.","conceptId":"C039","variant":1,"id":"E03Q12"},{"category":"Underwriting & Claims","stem":"What is the purpose of a life insurance inspection report?","options":["To pay the agent's commissions","To replace all medical evidence","To inspect roof shingles for life claims","To gather permitted background information relevant to underwriting"],"answer":3,"explanation":"Inspection reports may assess finances, activities, and reputation consistent with law and consent.","conceptId":"C115","variant":1,"id":"E03Q13"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Reinsurance.\" Select the statement that should replace this inaccurate advice.","options":["Risk pooling","Conflict of interest and unsuitable recommendation","Appropriate needs analysis","Reinsurance"],"answer":1,"explanation":"Recommendations should be based on the client's legitimate objectives, not compensation alone.","conceptId":"C149","variant":4,"id":"E03Q14"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Accidental death rider.\" Which of the following would be the most accurate response?","options":["Waiver of cost of insurance rider","Guaranteed insurability rider","Payor benefit rider","Accidental death rider"],"answer":1,"explanation":"Guaranteed insurability options allow increases within contractual dates and limits.","conceptId":"C070","variant":3,"id":"E03Q15"},{"category":"Ethics & CA Law","stem":"What is the main purpose of an insurance regulatory examination of a company?","options":["To guarantee its stock appreciates","To appoint the policyholder's attorney","To set a consumer's beneficiary selection","To assess compliance and financial or market conduct condition"],"answer":3,"explanation":"Insurance departments supervise insurer solvency and market conduct.","conceptId":"C143","variant":1,"id":"E03Q16"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"Any minor spelling error.\" Which answer most accurately corrects the misunderstanding?","options":["Any minor spelling error","A producer's phone number change","An incorrect statement important to an insurer's underwriting decision","A beneficiary's new mailing address"],"answer":2,"explanation":"Materiality relates to whether accurate facts would have influenced acceptance, risk, or premium.","conceptId":"C020","variant":2,"id":"E03Q17"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Making a child the insured automatically.\" Which answer most accurately corrects the misunderstanding?","options":["Making a child the insured automatically","Converting a policy into health insurance","Eliminating the insurer's claim obligation","Pledging policy value or proceeds as security for a loan"],"answer":3,"explanation":"A lender can receive proceeds up to its secured interest before the remainder goes to beneficiaries.","conceptId":"C063","variant":2,"id":"E03Q18"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"Both parties promise equal performance.\" Select the statement that should replace this inaccurate advice.","options":["Both parties promise equal performance","Only the insurer makes a legally enforceable promise to perform if conditions are met","Both parties must pay claims","The insured can rewrite contract terms at will"],"answer":1,"explanation":"The policyowner promises no ongoing performance enforceable as a contract; premiums are needed to keep coverage in force.","conceptId":"C003","variant":4,"id":"E03Q19"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"Life with 20-year period certain.\" Which answer most accurately corrects the misunderstanding?","options":["Straight life income","Life with cash refund","Joint and survivor income","Life with 20-year period certain"],"answer":0,"explanation":"Straight life typically offers higher payments because it has no survivor or refund guarantee.","conceptId":"C090","variant":2,"id":"E03Q20"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"It always converts to an annuity.\" Which of the following would be the most accurate response?","options":["Coverage ends with no maturity cash value","Its face amount is automatically paid to the owner","It always converts to an annuity","All premiums are refunded"],"answer":0,"explanation":"Term coverage ends unless it is renewed or converted under the policy's options.","conceptId":"C026","variant":3,"id":"E03Q21"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"Disclosing a policy's exclusions.\" Which of the following would be the most accurate response?","options":["Explaining an insurer's financial rating with attribution","Making false malicious statements intended to injure an insurer's reputation or business","Comparing policy guarantees factually","Disclosing a policy's exclusions"],"answer":1,"explanation":"Unfair trade practices can prohibit knowingly false or malicious statements about competitors.","conceptId":"C139","variant":3,"id":"E03Q22"},{"category":"Fundamentals","stem":"What does a standard risk classification ordinarily mean?","options":["The applicant receives a guaranteed dividend","No premium will be charged","The applicant is uninsurable","The applicant meets the insurer's average underwriting guidelines"],"answer":3,"explanation":"Standard risks generally receive standard rates based on the carrier's underwriting rules.","conceptId":"C013","variant":1,"id":"E03Q23"},{"category":"Annuities & Retirement","stem":"What is the primary purpose of an annuity?","options":["To pay a death benefit only for accidental death","To insure a car","To provide a stream of income, often for retirement","To cover a homeowner's liability"],"answer":2,"explanation":"Annuities are contracts for accumulation and/or distribution of income.","conceptId":"C083","variant":1,"id":"E03Q24"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"Eliminate underwriting.\" Select the statement that should replace this inaccurate advice.","options":["Predict the exact death date of each insured","Guarantee no claims occur","Predict aggregate losses more reliably for a large group","Eliminate underwriting"],"answer":2,"explanation":"A large population makes actual mortality experience more predictable in aggregate.","conceptId":"C008","variant":4,"id":"E03Q25"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"Property deed.\" Which of the following would be the most accurate response?","options":["Attending physician statement (APS)","Property deed","Credit card reward statement","Vehicle title report"],"answer":0,"explanation":"An APS may help an insurer understand medical conditions and treatment history.","conceptId":"C109","variant":3,"id":"E03Q26"},{"category":"Term & Whole Life","stem":"What is the cash surrender value?","options":["The producer's commission","The amount owed to the contingent beneficiary","The amount payable to the owner upon surrender after applicable charges and loans","The guaranteed annual death benefit"],"answer":2,"explanation":"Net surrender value reflects contract cash values less surrender charges and outstanding debt.","conceptId":"C040","variant":1,"id":"E03Q27"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"Immediate payment of death proceeds to the living insured.\" Which of the following would be the most accurate response?","options":["Automatic change of insured person","Immediate payment of death proceeds to the living insured","Exchange into eligible permanent coverage without new evidence of insurability within the permitted period","Cancellation of premiums forever"],"answer":2,"explanation":"Conversion preserves a path to permanent life coverage subject to contract restrictions.","conceptId":"C028","variant":3,"id":"E03Q28"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"Life insurance payable at the first death only.\" Which answer most accurately corrects the misunderstanding?","options":["A single lump-sum payment only","Life insurance payable at the first death only","Income while either of two covered annuitants remains alive, as specified","No income after the first retirement"],"answer":2,"explanation":"Joint-and-survivor options continue all or part of income to a survivor based on the payout selection.","conceptId":"C092","variant":2,"id":"E03Q29"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"Conversion from life to car insurance.\" Select the statement that should replace this inaccurate advice.","options":["An automatic full refund of all employer premiums","Unlimited free coverage forever","Conversion from life to car insurance","Eligible departing members to change group life coverage to an individual policy within specified rules"],"answer":3,"explanation":"Group conversion may preserve some protection without medical underwriting if exercised promptly.","conceptId":"C180","variant":4,"id":"E03Q30"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Authorize an unlicensed agent.\" Select the statement that should replace this inaccurate advice.","options":["Replace any contract with free insurance","Authorize an unlicensed agent","Guarantee profit on a policy","Allow regulators to investigate potentially unfair or unlawful insurer or agent conduct"],"answer":3,"explanation":"CDI receives consumer complaints and oversees compliance with insurance rules.","conceptId":"C153","variant":4,"id":"E03Q31"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"A fluctuating face amount tied to inflation only.\" Select the statement that should replace this inaccurate advice.","options":["A permanent premium waiver from the start","Lower initial scheduled premiums that increase at a stated later point","No underwriting under any circumstances","A fluctuating face amount tied to inflation only"],"answer":1,"explanation":"Modified premium whole life changes premium levels according to the contract schedule.","conceptId":"C051","variant":4,"id":"E03Q32"},{"category":"Ethics & CA Law","stem":"What is an insurance fiduciary duty concerning premiums collected by a producer?","options":["Keep premiums regardless of policy status","Lend client premiums without permission","Handle entrusted premiums honestly and remit/account for them as required","Use premiums as personal funds temporarily"],"answer":2,"explanation":"Producers must properly safeguard and account for money received in their insurance capacity.","conceptId":"C138","variant":1,"id":"E03Q33"},{"category":"Business & Tax","stem":"An insured has a $300,000 income replacement need, $120,000 debt, and $70,000 in available assets. What is the estimated coverage gap?","options":["$230,000","$350,000","$490,000","$70,000"],"answer":1,"explanation":"Needs-based gap = $300,000 + $120,000 - $70,000 = $350,000.","conceptId":"C172","variant":1,"id":"E03Q34"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"Begin underwriting an entirely new insured.\" Which of the following would be the most accurate response?","options":["Pay every applicant a dividend","Transfer ownership to the agent","Verify coverage and claim facts, then determine benefits under policy and law","Begin underwriting an entirely new insured"],"answer":2,"explanation":"Claims adjudication confirms the policy and the claimant's entitlement.","conceptId":"C130","variant":3,"id":"E03Q35"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"The insurer's investment expense.\" Select the statement that should replace this inaccurate advice.","options":["A guarantee all estates owe federal estate tax","The insurer's investment expense","Cash required by an estate to pay obligations without forced asset sales","The insured's monthly disability benefit"],"answer":2,"explanation":"Life insurance can provide liquidity for taxes, debts and settlement costs if structured appropriately.","conceptId":"C170","variant":4,"id":"E03Q36"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"To determine the agent's tax return.\" Select the statement that should replace this inaccurate advice.","options":["To support financial underwriting and justify a large coverage amount","To guarantee a stock price","To transfer ownership automatically","To determine the agent's tax return"],"answer":0,"explanation":"Financial underwriting evaluates coverage need and potential overinsurance or anti-selection.","conceptId":"C118","variant":4,"id":"E03Q37"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"A policy with an increasing guaranteed face amount.\" Select the statement that should replace this inaccurate advice.","options":["Coverage that declines as a mortgage balance is expected to decrease","A policy with an increasing guaranteed face amount","A whole-life policy with rising cash value","A variable annuity"],"answer":0,"explanation":"Decreasing term is often designed to match a falling debt balance.","conceptId":"C030","variant":4,"id":"E03Q38"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Payments only after the beneficiary dies.\" Which of the following would be the most accurate response?","options":["Payments only after the beneficiary dies","A selected payment amount until proceeds and interest are exhausted","A lifelong guaranteed payment irrespective of amount","An automatic annual inflation increase"],"answer":1,"explanation":"Fixed amount fixes payment size rather than a guaranteed number of payments.","conceptId":"C081","variant":3,"id":"E03Q39"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"A guaranteed public tax deduction.\" Which answer most accurately corrects the misunderstanding?","options":["A mandatory investment advisory account","A guaranteed public tax deduction","An optional contractual feature that changes benefits or guarantees, often for a fee","The same as a death certificate"],"answer":2,"explanation":"Riders can add features such as living income benefits; their costs and limitations matter.","conceptId":"C106","variant":2,"id":"E03Q40"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"It uses only the insurer's advertising budget.\" Select the statement that should replace this inaccurate advice.","options":["It totals specific financial needs and subtracts available resources","It ignores outstanding debts","It insures everyone for exactly the same amount","It uses only the insurer's advertising budget"],"answer":0,"explanation":"The needs method estimates expenses and obligations, then offsets assets and existing insurance.","conceptId":"C167","variant":4,"id":"E03Q41"},{"category":"Business & Tax","stem":"Who commonly owns and is beneficiary of a key-person life insurance policy?","options":["The state insurance regulator","Every employee equally","The business, subject to consent and applicable rules","Always the employee's children"],"answer":2,"explanation":"The business often applies for, owns, and benefits from key-person protection.","conceptId":"C159","variant":1,"id":"E03Q42"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Making beneficiary changes.\" Which answer most accurately corrects the misunderstanding?","options":["Paying the policy's first dividend","Setting state insurance laws","Collecting health measurements and specimens for underwriting","Making beneficiary changes"],"answer":2,"explanation":"Paramedical exams assist an insurer's assessment of mortality risk.","conceptId":"C111","variant":2,"id":"E03Q43"},{"category":"Annuities & Retirement","stem":"What is a qualified retirement annuity commonly funded with?","options":["Only insurer dividends","Only after-tax funds that can never be deducted","Only life insurance death claims","Money in a tax-favored retirement plan or IRA"],"answer":3,"explanation":"Qualified annuities are held within qualified retirement arrangements and follow their tax rules.","conceptId":"C098","variant":1,"id":"E03Q44"},{"category":"Business & Tax","stem":"What is a certificate of insurance under group life coverage?","options":["Evidence and summary of a member's coverage under the group master contract","An insurer's annual income statement","A securities prospectus","Proof the employee owns the master contract"],"answer":0,"explanation":"Certificates describe individual group coverage, while the master contract controls.","conceptId":"C179","variant":1,"id":"E03Q45"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"A term life policy with one premium.\" Select the statement that should replace this inaccurate advice.","options":["An annuity that only holds stock shares","An annuity that cannot pay income","An annuity that generally begins income payments within about one year of purchase","A term life policy with one premium"],"answer":2,"explanation":"Immediate annuities begin payout relatively soon after the purchase payment.","conceptId":"C084","variant":4,"id":"E03Q46"},{"category":"Ethics & CA Law","stem":"A life agent is asked to promise that all life insurance proceeds avoid every possible tax. The best response is what?","options":["Ignore policy ownership","Promise that all policies have no taxes of any kind","Say only beneficiaries ever owe income tax","Explain that tax treatment varies by policy, ownership, and circumstances and avoid absolute claims"],"answer":3,"explanation":"Death benefits are generally income-tax-free to beneficiaries but estate, transfer, and other rules can apply.","conceptId":"C150","variant":1,"id":"E03Q47"},{"category":"Annuities & Retirement","stem":"What federal additional tax may generally apply to the taxable part of an early annuity distribution before age 59½ unless an exception applies?","options":["10% additional tax","25% mandatory federal fee","No potential additional tax","A 50% flat surcharge"],"answer":0,"explanation":"An early distribution can trigger an additional 10% federal tax on taxable amounts, subject to exceptions.","conceptId":"C096","variant":1,"id":"E03Q48"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"A beneficiary named only for one day.\" Which answer most accurately corrects the misunderstanding?","options":["A beneficiary always selected by the insurer","A beneficiary whose consent is generally required for changes affecting their protected interest","A beneficiary named only for one day","A beneficiary who receives no rights"],"answer":1,"explanation":"An irrevocable designation limits the owner's ability to change the beneficiary or impair their interest.","conceptId":"C059","variant":2,"id":"E03Q49"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"A company that guarantees claim payment.\" Select the statement that should replace this inaccurate advice.","options":["A regulator that issues agents' licenses","A company that guarantees claim payment","A federal insurer of life benefits","An information exchange used by member insurers in underwriting, subject to privacy rules"],"answer":3,"explanation":"MIB information can flag relevant application data; insurers must verify information as appropriate.","conceptId":"C110","variant":4,"id":"E03Q50"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Promise the insurer can never fail.\" Which answer most accurately corrects the misunderstanding?","options":["Quote an invented credit rating","Promise the insurer can never fail","Claim CDI guarantees all benefits in full","Use current credible financial information and avoid guarantees beyond policy terms"],"answer":3,"explanation":"Financial ratings are opinions, and policy guarantees depend on insurer claims-paying ability.","conceptId":"C152","variant":2,"id":"E03Q51"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"To eliminate every financial risk.\" Which of the following would be the most accurate response?","options":["To eliminate every financial risk","To guarantee investment profits","To provide financial protection against premature death","To insure a home against fire"],"answer":2,"explanation":"Life insurance transfers the financial risk of an insured person's death to the insurer.","conceptId":"C001","variant":3,"id":"E03Q52"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Promise dividends are guaranteed.\" Which answer most accurately corrects the misunderstanding?","options":["Hide replacement charges","Suggest incorrect answers on an application","Promise dividends are guaranteed","Present material benefits, exclusions, costs, and limitations accurately"],"answer":3,"explanation":"Accurate disclosures support informed consumer decisions and avoid misrepresentation.","conceptId":"C134","variant":2,"id":"E03Q53"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"To insure a charity's building against fire.\" Select the statement that should replace this inaccurate advice.","options":["To insure a charity's building against fire","To direct eligible policy proceeds to a named charitable organization","To cancel all premium charges","To force a policy to become an annuity"],"answer":1,"explanation":"A policy can name a charity as beneficiary subject to policy and tax considerations.","conceptId":"C168","variant":4,"id":"E03Q54"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"The insurer must waive all charges forever.\" Which answer most accurately corrects the misunderstanding?","options":["The policy can lapse unless additional funding or a guarantee prevents it","The beneficiary must pay premiums after death","The insurer must waive all charges forever","The death benefit doubles automatically"],"answer":0,"explanation":"Flexible premiums do not eliminate the requirement to fund mortality and expenses.","conceptId":"C036","variant":2,"id":"E03Q55"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"An agent's unwritten verbal promises.\" Which answer most accurately corrects the misunderstanding?","options":["Any insurer advertisement ever produced","A beneficiary's unrelated bank statements","An agent's unwritten verbal promises","The policy and attached application and endorsements as applicable"],"answer":3,"explanation":"The written contract is assembled from the policy and specified attached documents.","conceptId":"C057","variant":2,"id":"E03Q56"},{"category":"Provisions & Riders","stem":"Under an interest-only settlement option, what is generally paid to the beneficiary periodically?","options":["Interest on proceeds retained by the insurer","The entire principal each month","Only the insurer's commission","A fixed share of the insured's salary"],"answer":0,"explanation":"The insurer retains principal and pays interest as stipulated; principal is handled under the agreement.","conceptId":"C079","variant":1,"id":"E03Q57"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"90%.\" Which of the following would be the most accurate response?","options":["60%","100%","90%","80%"],"answer":0,"explanation":"The current PSI candidate bulletin states a 60% passing score for the Life exam; aim higher on practice tests.","conceptId":"C155","variant":3,"id":"E03Q58"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"The beneficiary's right to name an agent.\" Which answer most accurately corrects the misunderstanding?","options":["The beneficiary's right to name an agent","Underwriting risk classification","Whether the policy is a contract of adhesion","The insurer's state of domicile"],"answer":1,"explanation":"Insurers use relevant underwriting factors to classify expected mortality risk.","conceptId":"C012","variant":2,"id":"E03Q59"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"Fixed term life.\" Which answer most accurately corrects the misunderstanding?","options":["Credit life only","Variable universal life","Traditional whole life only","Fixed term life"],"answer":1,"explanation":"Variable universal life combines UL flexibility and market-linked separate-account investments.","conceptId":"C038","variant":2,"id":"E03Q60"},{"category":"Business & Tax","stem":"What is the purpose of a Social Security survivor benefit in life insurance planning?","options":["A guaranteed benefit for every unrelated person","A potential existing income source that may reduce some survivor income needs","A permanent private life policy replacement in every case","A guarantee all debt is forgiven"],"answer":1,"explanation":"Survivor benefits are subject to eligibility and may be included when assessing resources.","conceptId":"C183","variant":1,"id":"E03Q61"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"Whole life never has a surrender charge.\" Which of the following would be the most accurate response?","options":["Term always has investment subaccounts","Whole life never has a surrender charge","Whole life always has lower initial premiums","Whole life generally provides lifelong protection and guaranteed cash value if required premiums are paid"],"answer":3,"explanation":"Traditional whole life includes permanent protection and a cash value schedule.","conceptId":"C031","variant":3,"id":"E03Q62"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"The application has been approved for all amounts.\" Which of the following would be the most accurate response?","options":["The insurer cannot decline coverage","Coverage is guaranteed regardless of medical findings","Coverage may begin only if stated conditions are satisfied under the receipt","The application has been approved for all amounts"],"answer":2,"explanation":"Conditional receipts are not unconditional promises; read their effective-date and insurability conditions.","conceptId":"C113","variant":3,"id":"E03Q63"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"To set the owner's dividend rate.\" Which of the following would be the most accurate response?","options":["To guarantee any claim at any time without exception","To prohibit any death benefit payment forever","To set the owner's dividend rate","To specify how claims are handled if suicide occurs during the initial exclusion period"],"answer":3,"explanation":"Suicide clauses typically limit early suicide claims, often returning premiums, with rules varying by jurisdiction.","conceptId":"C125","variant":3,"id":"E03Q64"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"Single-premium whole life in every case.\" Which answer most accurately corrects the misunderstanding?","options":["A deferred variable annuity","20-year level term insurance","A lifetime immediate annuity","Single-premium whole life in every case"],"answer":1,"explanation":"Term commonly provides more initial death protection per premium dollar for a temporary need.","conceptId":"C041","variant":2,"id":"E03Q65"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"They are always taxed as ordinary wages.\" Which answer most accurately corrects the misunderstanding?","options":["They are taxable every year before death","They are always taxed as ordinary wages","They are generally excluded from gross income, with important exceptions","They are always capital gains"],"answer":2,"explanation":"IRC Section 101(a) generally excludes death proceeds from income, subject to exceptions such as transfer-for-value.","conceptId":"C160","variant":2,"id":"E03Q66"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"Income only for a fixed period and never for life.\" Which answer most accurately corrects the misunderstanding?","options":["Income for life, with payments for at least a stated minimum period","Every premium is refundable at any time","Income only for a fixed period and never for life","An account with unlimited liquidity"],"answer":0,"explanation":"If death occurs during the period certain, remaining payments generally continue to the beneficiary.","conceptId":"C091","variant":2,"id":"E03Q67"},{"category":"Term & Whole Life","stem":"What is limited-pay whole life?","options":["Term coverage that pays only a partial death benefit","A policy that cannot build cash value","Permanent life insurance with premiums scheduled for fewer years than coverage lasts","Coverage limited to exactly one year"],"answer":2,"explanation":"A 20-pay whole life policy may be fully paid after 20 years but continue for life.","conceptId":"C033","variant":1,"id":"E03Q68"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"To guarantee unlimited market growth.\" Which answer most accurately corrects the misunderstanding?","options":["To avoid any income taxation","To reduce the risk that all income stops immediately after an early death","To obtain auto insurance","To guarantee unlimited market growth"],"answer":1,"explanation":"Period-certain payments can continue to a beneficiary if death occurs during the guarantee period.","conceptId":"C102","variant":2,"id":"E03Q69"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"Always taxed as ordinary income from the first dollar.\" Which answer most accurately corrects the misunderstanding?","options":["Always capital gains","Always taxed as ordinary income from the first dollar","Generally treated as a return of premium rather than taxable income","Always subject to payroll tax"],"answer":2,"explanation":"Life policy dividends commonly reduce the owner's cost basis; interest earned on retained dividends is typically taxable.","conceptId":"C161","variant":2,"id":"E03Q70"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"Only when the insured dies.\" Which of the following would be the most accurate response?","options":["When the contract is made","Only when the insured dies","Only when the beneficiary files a claim","At every annual renewal"],"answer":0,"explanation":"Insurable interest is generally required at policy inception, not continuously throughout the policy.","conceptId":"C021","variant":3,"id":"E03Q71"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Guaranteed insurability rider.\" Which of the following would be the most accurate response?","options":["Cost of living rider","Accidental death benefit rider","Guaranteed insurability rider","Waiver of premium rider"],"answer":3,"explanation":"Waiver riders help keep the policy funded during a covered disability.","conceptId":"C069","variant":3,"id":"E03Q72"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"A policy whose cash value is always zero.\" Which of the following would be the most accurate response?","options":["A policy whose cash value is always zero","A policy with guaranteed annual dividends","A policy automatically without premiums","Coverage issued with an extra charge reflecting higher risk"],"answer":3,"explanation":"Insurers may use flat extras or table ratings for qualifying higher-risk applicants.","conceptId":"C128","variant":3,"id":"E03Q73"},{"category":"Provisions & Riders","stem":"What is an assignment of a life insurance policy?","options":["An automatic dividend election","A premium payment frequency","A change in the insured's age","A transfer of specified policy rights to another party"],"answer":3,"explanation":"Assignments transfer ownership rights or create security interests.","conceptId":"C062","variant":1,"id":"E03Q74"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Obtain a signature without explanation.\" Which answer most accurately corrects the misunderstanding?","options":["Obtain a signature without explanation","Tell the client reading is unnecessary","Hide the old policy values","Explain the changes and material risks in understandable terms before proceeding"],"answer":3,"explanation":"Informed consent requires understandable, accurate discussion of material changes.","conceptId":"C151","variant":2,"id":"E03Q75"}]},{"title":"Exam 4","questions":[{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"Every applicant deposits the full death benefit upfront.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer ignores probability","Many policyowners pay premiums to fund claims experienced by a smaller number","Every applicant deposits the full death benefit upfront","Every insured is promised identical lifespan"],"answer":1,"explanation":"Pooling spreads unpredictable individual loss across a broad group.","conceptId":"C023","variant":2,"id":"E04Q01"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"A guarantee all estates owe federal estate tax.\" Which answer most accurately corrects the misunderstanding?","options":["A guarantee all estates owe federal estate tax","Cash required by an estate to pay obligations without forced asset sales","The insured's monthly disability benefit","The insurer's investment expense"],"answer":1,"explanation":"Life insurance can provide liquidity for taxes, debts and settlement costs if structured appropriately.","conceptId":"C170","variant":2,"id":"E04Q02"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"$40,000.\" Select the statement that should replace this inaccurate advice.","options":["$500,000","$40,000","$458,000","$542,000"],"answer":2,"explanation":"Net death proceeds equal $500,000 minus $40,000 principal and $2,000 interest = $458,000.","conceptId":"C171","variant":4,"id":"E04Q03"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"The interest on policy loans.\" Which of the following would be the most accurate response?","options":["The amount of commission paid","The number of applications rejected","The interest on policy loans","The rate of death in a defined group"],"answer":3,"explanation":"Mortality assumptions help insurers estimate expected death claims.","conceptId":"C009","variant":3,"id":"E04Q04"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"All premiums are refunded.\" Select the statement that should replace this inaccurate advice.","options":["Its face amount is automatically paid to the owner","All premiums are refunded","It always converts to an annuity","Coverage ends with no maturity cash value"],"answer":3,"explanation":"Term coverage ends unless it is renewed or converted under the policy's options.","conceptId":"C026","variant":4,"id":"E04Q05"},{"category":"Underwriting & Claims","stem":"What is a contestable-period claim investigation primarily concerned with?","options":["Whether material application misrepresentations or other valid grounds affect coverage","Whether dividends were reinvested","Whether the beneficiary likes the policy","Whether the agent is still employed"],"answer":0,"explanation":"The insurer may investigate a death within the contestability period under applicable law.","conceptId":"C123","variant":1,"id":"E04Q06"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"Every premium is refundable at any time.\" Select the statement that should replace this inaccurate advice.","options":["Every premium is refundable at any time","Income for life, with payments for at least a stated minimum period","Income only for a fixed period and never for life","An account with unlimited liquidity"],"answer":1,"explanation":"If death occurs during the period certain, remaining payments generally continue to the beneficiary.","conceptId":"C091","variant":4,"id":"E04Q07"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"Life insurance that covers only children.\" Which of the following would be the most accurate response?","options":["A rider that pays premiums after retirement","Coverage on two lives that generally pays upon the second insured's death","Two policies that each pay on first death","Life insurance that covers only children"],"answer":1,"explanation":"Survivorship coverage is often considered in estate or legacy planning.","conceptId":"C048","variant":3,"id":"E04Q08"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"To buy an unrelated stock ETF directly.\" Select the statement that should replace this inaccurate advice.","options":["To cancel the base policy","To buy an unrelated stock ETF directly","To pay property taxes only","To buy small amounts of additional fully paid whole life insurance"],"answer":3,"explanation":"Paid-up additions increase cash value and death benefit without future premiums for the additions.","conceptId":"C044","variant":4,"id":"E04Q09"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"A business venture seeking profit.\" Select the statement that should replace this inaccurate advice.","options":["Pure risk involving possible loss but no opportunity for gain","A business venture seeking profit","A casino wager","A speculative bet on stock prices"],"answer":0,"explanation":"Pure risks involve loss or no loss, while speculative risks include a possibility of gain.","conceptId":"C007","variant":4,"id":"E04Q10"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"Cash value is always guaranteed.\" Which of the following would be the most accurate response?","options":["Cash value is always guaranteed","Coverage may be accessible with simplified enrollment at group rates","Coverage can never terminate when employment ends","Employees always own lifelong portable coverage"],"answer":1,"explanation":"Group term may be convenient but has portability and coverage-limit considerations.","conceptId":"C178","variant":3,"id":"E04Q11"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"When a premium is late.\" Which of the following would be the most accurate response?","options":["Before the primary beneficiary in all cases","When a premium is late","When the primary beneficiary is not eligible or does not survive under policy terms","When the insured turns 65"],"answer":2,"explanation":"Contingent beneficiaries are backups to the primary designation.","conceptId":"C060","variant":3,"id":"E04Q12"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"Both parties must pay claims.\" Which answer most accurately corrects the misunderstanding?","options":["Both parties must pay claims","Both parties promise equal performance","The insured can rewrite contract terms at will","Only the insurer makes a legally enforceable promise to perform if conditions are met"],"answer":3,"explanation":"The policyowner promises no ongoing performance enforceable as a contract; premiums are needed to keep coverage in force.","conceptId":"C003","variant":2,"id":"E04Q13"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"The applicant is uninsurable.\" Which answer most accurately corrects the misunderstanding?","options":["The applicant meets the insurer's average underwriting guidelines","The applicant receives a guaranteed dividend","The applicant is uninsurable","No premium will be charged"],"answer":0,"explanation":"Standard risks generally receive standard rates based on the carrier's underwriting rules.","conceptId":"C013","variant":2,"id":"E04Q14"},{"category":"Ethics & CA Law","stem":"If a producer does not understand a rider's exclusion, what should the producer do?","options":["Confirm its meaning from the insurer's policy materials before making a representation","Ignore the exclusion as minor","Invent an explanation to close the sale","Assure the customer all risks are covered"],"answer":0,"explanation":"Competence requires knowing policy limits and avoiding unsupported statements.","conceptId":"C144","variant":1,"id":"E04Q15"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"The death benefit becomes taxable annually.\" Select the statement that should replace this inaccurate advice.","options":["The insurer is a mutual fund","The death benefit becomes taxable annually","All index crediting is guaranteed at 15%","Index-linked crediting and policy values are not guaranteed at that illustrated rate"],"answer":3,"explanation":"Illustrated non-guaranteed values must not be described as guaranteed results.","conceptId":"C147","variant":4,"id":"E04Q16"},{"category":"Business & Tax","stem":"How are life insurance cash surrender proceeds generally taxed federally?","options":["The entire original face amount is taxed","The entire surrender value is always tax free","There is never a taxable surrender gain","Gain above the policyowner's adjusted basis is generally taxable, subject to applicable rules"],"answer":3,"explanation":"Surrender proceeds exceeding basis generally produce ordinary income rather than capital gain.","conceptId":"C164","variant":1,"id":"E04Q17"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"Taxes, inflation, and stock dividends only.\" Which answer most accurately corrects the misunderstanding?","options":["Deductible, coinsurance, and copayment","Marketing, age of producer, and commissions only","Taxes, inflation, and stock dividends only","Mortality, interest, and expenses"],"answer":3,"explanation":"Pricing reflects expected claims, investment earnings and operating costs.","conceptId":"C010","variant":2,"id":"E04Q18"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"An unrelated property casualty deductible.\" Select the statement that should replace this inaccurate advice.","options":["A guaranteed public share price","An unrelated property casualty deductible","Purchase of a deceased owner's business interest according to the agreement","Payment of the employee's disability income only"],"answer":2,"explanation":"Life insurance can provide funds for ownership transition on a business owner's death.","conceptId":"C158","variant":4,"id":"E04Q19"},{"category":"Fundamentals","stem":"What is a substandard risk?","options":["An applicant who always gets preferred rates","A beneficiary who is a minor","An applicant with higher-than-normal expected mortality who may be charged extra premium","A person with no insurable interest"],"answer":2,"explanation":"Higher risk can result in rating, exclusions if lawful, postponement, or decline.","conceptId":"C014","variant":1,"id":"E04Q20"},{"category":"Business & Tax","stem":"A $250,000 death benefit is divided 60% and 40% between two beneficiaries. What does the first receive before adjustments?","options":["$250,000","$150,000","$125,000","$100,000"],"answer":1,"explanation":"60% of $250,000 is $150,000.","conceptId":"C173","variant":1,"id":"E04Q21"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Guarantee profit on a policy.\" Which answer most accurately corrects the misunderstanding?","options":["Guarantee profit on a policy","Allow regulators to investigate potentially unfair or unlawful insurer or agent conduct","Authorize an unlicensed agent","Replace any contract with free insurance"],"answer":1,"explanation":"CDI receives consumer complaints and oversees compliance with insurance rules.","conceptId":"C153","variant":2,"id":"E04Q22"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"The amount owed to the contingent beneficiary.\" Select the statement that should replace this inaccurate advice.","options":["The amount owed to the contingent beneficiary","The amount payable to the owner upon surrender after applicable charges and loans","The producer's commission","The guaranteed annual death benefit"],"answer":1,"explanation":"Net surrender value reflects contract cash values less surrender charges and outstanding debt.","conceptId":"C040","variant":4,"id":"E04Q23"},{"category":"Business & Tax","stem":"A policy pays $620,000 upon death. The insurer deducts a $62,000 policy loan and $3,000 accrued interest. What is the approximate net death benefit?","options":["$685,000","$558,000","$620,000","$555,000"],"answer":3,"explanation":"Subtract both loan principal and accrued interest: 620,000 - 62,000 - 3,000 = 555,000.","conceptId":"X001","variant":1,"id":"E04Q24"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"A policy with guaranteed annual dividends.\" Select the statement that should replace this inaccurate advice.","options":["A policy automatically without premiums","Coverage issued with an extra charge reflecting higher risk","A policy with guaranteed annual dividends","A policy whose cash value is always zero"],"answer":1,"explanation":"Insurers may use flat extras or table ratings for qualifying higher-risk applicants.","conceptId":"C128","variant":4,"id":"E04Q25"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Misstatement of age clause.\" Which of the following would be the most accurate response?","options":["Grace period","Assignment clause","Insuring clause","Misstatement of age clause"],"answer":2,"explanation":"The insuring clause states the principal coverage promise.","conceptId":"C052","variant":3,"id":"E04Q26"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"At every annual renewal.\" Which answer most accurately corrects the misunderstanding?","options":["At every annual renewal","When the contract is made","Only when the insured dies","Only when the beneficiary files a claim"],"answer":1,"explanation":"Insurable interest is generally required at policy inception, not continuously throughout the policy.","conceptId":"C021","variant":2,"id":"E04Q27"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"To pay a death benefit only for accidental death.\" Which answer most accurately corrects the misunderstanding?","options":["To provide a stream of income, often for retirement","To pay a death benefit only for accidental death","To cover a homeowner's liability","To insure a car"],"answer":0,"explanation":"Annuities are contracts for accumulation and/or distribution of income.","conceptId":"C083","variant":2,"id":"E04Q28"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"Paying the policy's first dividend.\" Which of the following would be the most accurate response?","options":["Paying the policy's first dividend","Collecting health measurements and specimens for underwriting","Making beneficiary changes","Setting state insurance laws"],"answer":1,"explanation":"Paramedical exams assist an insurer's assessment of mortality risk.","conceptId":"C111","variant":3,"id":"E04Q29"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"Explaining an insurer's financial rating with attribution.\" Select the statement that should replace this inaccurate advice.","options":["Comparing policy guarantees factually","Making false malicious statements intended to injure an insurer's reputation or business","Disclosing a policy's exclusions","Explaining an insurer's financial rating with attribution"],"answer":1,"explanation":"Unfair trade practices can prohibit knowingly false or malicious statements about competitors.","conceptId":"C139","variant":4,"id":"E04Q30"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"To avoid any income taxation.\" Which of the following would be the most accurate response?","options":["To obtain auto insurance","To reduce the risk that all income stops immediately after an early death","To avoid any income taxation","To guarantee unlimited market growth"],"answer":1,"explanation":"Period-certain payments can continue to a beneficiary if death occurs during the guarantee period.","conceptId":"C102","variant":3,"id":"E04Q31"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Guaranteed stock dividends.\" Which answer most accurately corrects the misunderstanding?","options":["Guaranteed stock dividends","Non-guaranteed policy dividends","Mandatory annual cash withdrawals","Federal tax refunds"],"answer":1,"explanation":"Mutual or participating policy dividends depend on the insurer's divisible surplus and are not guaranteed.","conceptId":"C042","variant":2,"id":"E04Q32"},{"category":"Term & Whole Life","stem":"What is the basic purpose of credit life insurance?","options":["To insure a company's stock price","To pay a covered outstanding debt if the insured borrower dies","To replace disability income","To protect a lender's property against fire"],"answer":1,"explanation":"Credit life is tied to a debt obligation and commonly has a decreasing benefit.","conceptId":"C050","variant":1,"id":"E04Q33"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"The policyowner's retirement.\" Which answer most accurately corrects the misunderstanding?","options":["Any beneficiary birthday","The policyowner's retirement","The insured's death while qualifying coverage is in force","An agent changing employers"],"answer":2,"explanation":"Death benefits arise on covered death and appropriate claim documentation.","conceptId":"C082","variant":2,"id":"E04Q34"},{"category":"Annuities & Retirement","stem":"Which annuity typically guarantees a stated minimum interest crediting under its terms?","options":["Equity mutual fund","Fixed annuity","Exchange traded fund","Variable annuity"],"answer":1,"explanation":"Fixed annuities generally credit contractually specified or declared interest with applicable guarantees.","conceptId":"C086","variant":1,"id":"E04Q35"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"The policy is automatically approved.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer guarantees a low rate","The applicant is the primary beneficiary","The policy is automatically approved","The insurer will not issue coverage under the proposed terms"],"answer":3,"explanation":"A decline means the application was not accepted under the insurer's underwriting criteria.","conceptId":"C126","variant":2,"id":"E04Q36"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"To pay double benefits after every accidental injury.\" Which answer most accurately corrects the misunderstanding?","options":["To allow an eligible insured to receive part of the death benefit while alive under qualifying conditions","To pay double benefits after every accidental injury","To eliminate all underwriting","To pay a benefit only after policy surrender"],"answer":0,"explanation":"Accelerated benefits advance proceeds for defined qualifying illness or other triggers and can reduce the later death benefit.","conceptId":"C072","variant":2,"id":"E04Q37"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"To provide only liability insurance.\" Which answer most accurately corrects the misunderstanding?","options":["To pay the face amount at a specified maturity date or earlier covered death","To protect against earthquake damage","To insure only a mortgage lender","To provide only liability insurance"],"answer":0,"explanation":"An endowment combines a death benefit with a contractual maturity payment.","conceptId":"C046","variant":2,"id":"E04Q38"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"Paid only when death occurs.\" Which of the following would be the most accurate response?","options":["Paid only when death occurs","Fixed and payable under the chosen premium schedule","Required only in the first month","Always recalculated monthly based on stock returns"],"answer":1,"explanation":"Ordinary whole life generally uses scheduled level premiums.","conceptId":"C032","variant":3,"id":"E04Q39"},{"category":"Provisions & Riders","stem":"What does an accidental death benefit rider typically provide?","options":["An automatic retirement annuity","A guaranteed policy dividend","A refund whenever the insured gets sick","An additional benefit when death meets the rider's definition of accident"],"answer":3,"explanation":"Accidental death riders pay only under defined accidental-death conditions and exclusions.","conceptId":"C071","variant":1,"id":"E04Q40"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"Payor benefit rider.\" Which answer most accurately corrects the misunderstanding?","options":["Guaranteed insurability rider","Waiver of cost of insurance rider","Payor benefit rider","Accidental death rider"],"answer":0,"explanation":"Guaranteed insurability options allow increases within contractual dates and limits.","conceptId":"C070","variant":2,"id":"E04Q41"},{"category":"Underwriting & Claims","stem":"What is a binding receipt in insurance terminology?","options":["A beneficiary election form","A receipt that can provide specified temporary coverage immediately, subject to its terms and limits","A receipt that never creates any coverage","A permanent annuity"],"answer":1,"explanation":"Binding and conditional receipts differ in how temporary protection is triggered.","conceptId":"C114","variant":1,"id":"E04Q42"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"A premium due date.\" Which of the following would be the most accurate response?","options":["A premium due date","A policy dividend distribution","A specified circumstance or risk the contract does not cover","An additional guaranteed benefit"],"answer":2,"explanation":"Exclusions describe limits on the insurer's coverage obligation.","conceptId":"C121","variant":3,"id":"E04Q43"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"Proof the employee owns the master contract.\" Which answer most accurately corrects the misunderstanding?","options":["A securities prospectus","Evidence and summary of a member's coverage under the group master contract","Proof the employee owns the master contract","An insurer's annual income statement"],"answer":1,"explanation":"Certificates describe individual group coverage, while the master contract controls.","conceptId":"C179","variant":2,"id":"E04Q44"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"A single lump-sum payment only.\" Which of the following would be the most accurate response?","options":["Income while either of two covered annuitants remains alive, as specified","A single lump-sum payment only","No income after the first retirement","Life insurance payable at the first death only"],"answer":0,"explanation":"Joint-and-survivor options continue all or part of income to a survivor based on the payout selection.","conceptId":"C092","variant":3,"id":"E04Q45"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"A property inspection only.\" Which of the following would be the most accurate response?","options":["Proof of death plus the insurer's claim forms and supporting records as needed","A property inspection only","Proof of the beneficiary's salary only","A new application for the deceased"],"answer":0,"explanation":"A death certificate and claimant information are common components of a death claim.","conceptId":"C122","variant":3,"id":"E04Q46"},{"category":"Annuities & Retirement","stem":"What is a surrender charge on a deferred annuity?","options":["An automatic annual death benefit","A contractual charge that may apply to withdrawals or surrender during specified years","A tax imposed by a producer","A premium paid to a reinsurer"],"answer":1,"explanation":"Surrender schedules discourage early withdrawal and may decline over time.","conceptId":"C093","variant":1,"id":"E04Q47"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"No underwriting under any circumstances.\" Which of the following would be the most accurate response?","options":["A fluctuating face amount tied to inflation only","A permanent premium waiver from the start","Lower initial scheduled premiums that increase at a stated later point","No underwriting under any circumstances"],"answer":2,"explanation":"Modified premium whole life changes premium levels according to the contract schedule.","conceptId":"C051","variant":3,"id":"E04Q48"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"Coverage is guaranteed regardless of medical findings.\" Which answer most accurately corrects the misunderstanding?","options":["The application has been approved for all amounts","Coverage may begin only if stated conditions are satisfied under the receipt","Coverage is guaranteed regardless of medical findings","The insurer cannot decline coverage"],"answer":1,"explanation":"Conditional receipts are not unconditional promises; read their effective-date and insurability conditions.","conceptId":"C113","variant":2,"id":"E04Q49"},{"category":"Underwriting & Claims","stem":"An applicant applies for $300,000 life coverage but is approved for only $250,000. What is the difference between the requested and approved face amounts?","options":["$25,000","$250,000","$50,000","$550,000"],"answer":2,"explanation":"Subtract approved coverage from requested coverage: 300,000 - 250,000 = 50,000.","conceptId":"X008","variant":1,"id":"E04Q50"},{"category":"Ethics & CA Law","stem":"What is the ethical concern if a producer recommends unnecessary extra coverage solely to increase commissions?","options":["Risk pooling","Appropriate needs analysis","Reinsurance","Conflict of interest and unsuitable recommendation"],"answer":3,"explanation":"Recommendations should be based on the client's legitimate objectives, not compensation alone.","conceptId":"C149","variant":1,"id":"E04Q51"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Promise the condition cannot be discovered.\" Select the statement that should replace this inaccurate advice.","options":["Alter the physician's records","Omit it because the client requested it","Promise the condition cannot be discovered","Explain that answers must be truthful and submit complete information"],"answer":3,"explanation":"Concealing material facts can be fraud and threaten coverage.","conceptId":"C140","variant":4,"id":"E04Q52"},{"category":"Annuities & Retirement","stem":"What is an immediate annuity?","options":["A term life policy with one premium","An annuity that cannot pay income","An annuity that only holds stock shares","An annuity that generally begins income payments within about one year of purchase"],"answer":3,"explanation":"Immediate annuities begin payout relatively soon after the purchase payment.","conceptId":"C084","variant":1,"id":"E04Q53"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"100%.\" Select the statement that should replace this inaccurate advice.","options":["90%","60%","80%","100%"],"answer":1,"explanation":"The current PSI candidate bulletin states a 60% passing score for the Life exam; aim higher on practice tests.","conceptId":"C155","variant":4,"id":"E04Q54"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"The contingent beneficiary by law.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer's reinsurer","The contingent beneficiary by law","The policyowner","The Insurance Commissioner"],"answer":2,"explanation":"The owner is responsible for funding the policy unless another payer is arranged.","conceptId":"C169","variant":2,"id":"E04Q55"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"$490,000.\" Which answer most accurately corrects the misunderstanding?","options":["$70,000","$350,000","$490,000","$230,000"],"answer":1,"explanation":"Needs-based gap = $300,000 + $120,000 - $70,000 = $350,000.","conceptId":"C172","variant":2,"id":"E04Q56"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"To replace all medical evidence.\" Select the statement that should replace this inaccurate advice.","options":["To replace all medical evidence","To gather permitted background information relevant to underwriting","To inspect roof shingles for life claims","To pay the agent's commissions"],"answer":1,"explanation":"Inspection reports may assess finances, activities, and reputation consistent with law and consent.","conceptId":"C115","variant":4,"id":"E04Q57"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"A real estate license.\" Select the statement that should replace this inaccurate advice.","options":["A securities license in place of life authority for all policies","An appropriate active insurance license and any required insurer appointment/authorization","A real estate license","Only a business card"],"answer":1,"explanation":"Proper state licensing and insurer authority are essential to lawful solicitation and sale.","conceptId":"C136","variant":4,"id":"E04Q58"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"Subrogation.\" Which of the following would be the most accurate response?","options":["Indemnity","Insurable interest","Contribution","Subrogation"],"answer":1,"explanation":"Insurable interest discourages wagering on human life; it generally must exist when a life policy is purchased.","conceptId":"C002","variant":3,"id":"E04Q59"},{"category":"Provisions & Riders","stem":"What is the purpose of a grace period?","options":["To waive every future premium","To extend a policy after its maturity without conditions","To allow a beneficiary change after claim payment","To keep coverage in force for a specified time after a premium is due"],"answer":3,"explanation":"A grace period provides a window to pay overdue premiums while coverage generally continues.","conceptId":"C053","variant":1,"id":"E04Q60"},{"category":"Term & Whole Life","stem":"Single-premium whole life generally requires what?","options":["One large premium paid at issue","A zero-cost application","An annual adjustable premium","Monthly premiums for life"],"answer":0,"explanation":"A single premium funds the policy upfront; tax treatment may differ for heavily funded policies.","conceptId":"C034","variant":1,"id":"E04Q61"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"Earnings must be taxed every week.\" Which of the following would be the most accurate response?","options":["Earnings are always tax free forever","Earnings are generally tax deferred","There is no taxation at any time","Earnings must be taxed every week"],"answer":1,"explanation":"Tax deferral postpones income tax on earnings until taxable distributions occur.","conceptId":"C094","variant":3,"id":"E04Q62"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"To approve every policy loan.\" Which of the following would be the most accurate response?","options":["To receive the death benefit first when eligible under the designation","To be the policy's insured automatically","To approve every policy loan","To pay insurance premiums as a legal requirement"],"answer":0,"explanation":"A primary beneficiary has first priority to receive proceeds subject to designation and applicable law.","conceptId":"C076","variant":3,"id":"E04Q63"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"Always the employee's children.\" Select the statement that should replace this inaccurate advice.","options":["The business, subject to consent and applicable rules","Every employee equally","The state insurance regulator","Always the employee's children"],"answer":0,"explanation":"The business often applies for, owns, and benefits from key-person protection.","conceptId":"C159","variant":4,"id":"E04Q64"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"The beneficiary changes an address.\" Select the statement that should replace this inaccurate advice.","options":["An insurer invests too conservatively","The producer earns a low commission","People with higher-than-average risk are more inclined to seek or keep coverage","The beneficiary changes an address"],"answer":2,"explanation":"Underwriting helps control the tendency of high-risk applicants to disproportionately seek coverage.","conceptId":"C011","variant":4,"id":"E04Q65"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"Hide that a statement is an insurance solicitation.\" Which of the following would be the most accurate response?","options":["Claim authorization from CDI without basis","Avoid false or misleading claims about coverage, benefits, insurer identity, and guarantees","Hide that a statement is an insurance solicitation","Advertise hypothetical returns as guaranteed"],"answer":1,"explanation":"Insurance advertising must not mislead consumers.","conceptId":"C142","variant":3,"id":"E04Q66"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Ignore existing beneficiaries.\" Select the statement that should replace this inaccurate advice.","options":["Ignore existing beneficiaries","Focus only on the new policy's first-year premium","Assume the new contract is always better","Compare the existing and proposed contracts, including surrender charges and lost guarantees"],"answer":3,"explanation":"Replacement analysis should consider costs, timing, exclusions, taxes and lost rights.","conceptId":"C141","variant":4,"id":"E04Q67"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"Coverage with premiums split evenly by law.\" Which answer most accurately corrects the misunderstanding?","options":["Individual coverage purchased through an agent","Coverage that cannot have beneficiaries","Group coverage for which the sponsor pays the full premium","Coverage with premiums split evenly by law"],"answer":2,"explanation":"Noncontributory coverage is financed by the employer or group sponsor.","conceptId":"C182","variant":2,"id":"E04Q68"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"The time required to file a death certificate.\" Select the statement that should replace this inaccurate advice.","options":["The time required to file a death certificate","The period in which money is contributed and grows before systematic payout","The period after all payments are finished","The period during an insurer's bankruptcy"],"answer":1,"explanation":"Accumulation precedes payout or annuitization in a deferred contract.","conceptId":"C101","variant":4,"id":"E04Q69"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"A lifelong guaranteed payment irrespective of amount.\" Select the statement that should replace this inaccurate advice.","options":["A lifelong guaranteed payment irrespective of amount","An automatic annual inflation increase","A selected payment amount until proceeds and interest are exhausted","Payments only after the beneficiary dies"],"answer":2,"explanation":"Fixed amount fixes payment size rather than a guaranteed number of payments.","conceptId":"C081","variant":4,"id":"E04Q70"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"A whole-life policy with rising cash value.\" Which answer most accurately corrects the misunderstanding?","options":["A variable annuity","A whole-life policy with rising cash value","A policy with an increasing guaranteed face amount","Coverage that declines as a mortgage balance is expected to decrease"],"answer":3,"explanation":"Decreasing term is often designed to match a falling debt balance.","conceptId":"C030","variant":2,"id":"E04Q71"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"Payments until age 120 no matter what.\" Which answer most accurately corrects the misunderstanding?","options":["Payments until age 120 no matter what","Payments over a selected number of years","Only interest is payable","A single immediate payment only"],"answer":1,"explanation":"A fixed period establishes duration; payment size depends on proceeds and contract assumptions.","conceptId":"C080","variant":2,"id":"E04Q72"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"A change in the insured's age.\" Which answer most accurately corrects the misunderstanding?","options":["A transfer of specified policy rights to another party","A premium payment frequency","A change in the insured's age","An automatic dividend election"],"answer":0,"explanation":"Assignments transfer ownership rights or create security interests.","conceptId":"C062","variant":2,"id":"E04Q73"},{"category":"Provisions & Riders","stem":"A per stirpes beneficiary distribution usually means what?","options":["Only the oldest child receives proceeds","A deceased beneficiary's share passes down their family branch","Every surviving beneficiary receives an equal share regardless of branch","Proceeds must be donated to charity"],"answer":1,"explanation":"Per stirpes allocation follows family branches; per capita generally divides among surviving members of the stated class.","conceptId":"C061","variant":1,"id":"E04Q74"},{"category":"Annuities & Retirement","stem":"Which product more directly addresses longevity risk than a death-benefit-focused term life policy?","options":["Credit life insurance","Mortgage decreasing term","A one-year level term policy","A lifetime income annuity"],"answer":3,"explanation":"Lifetime annuity income can mitigate the risk of outliving retirement resources.","conceptId":"C104","variant":1,"id":"E04Q75"}]},{"title":"Exam 5","questions":[{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"When the insured turns 65.\" Select the statement that should replace this inaccurate advice.","options":["Before the primary beneficiary in all cases","When a premium is late","When the insured turns 65","When the primary beneficiary is not eligible or does not survive under policy terms"],"answer":3,"explanation":"Contingent beneficiaries are backups to the primary designation.","conceptId":"C060","variant":4,"id":"E05Q01"},{"category":"Annuities & Retirement","stem":"What does a life-with-period-certain annuity generally guarantee?","options":["An account with unlimited liquidity","Every premium is refundable at any time","Income for life, with payments for at least a stated minimum period","Income only for a fixed period and never for life"],"answer":2,"explanation":"If death occurs during the period certain, remaining payments generally continue to the beneficiary.","conceptId":"C091","variant":1,"id":"E05Q02"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"The investment return.\" Select the statement that should replace this inaccurate advice.","options":["The insured's attained age","The insurer's claim expenses","The investment return","The scheduled premium"],"answer":3,"explanation":"Level-premium term has stable premiums for a stated guaranteed period.","conceptId":"C029","variant":4,"id":"E05Q03"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Risk pooling.\" Which of the following would be the most accurate response?","options":["Risk pooling","Appropriate needs analysis","Conflict of interest and unsuitable recommendation","Reinsurance"],"answer":2,"explanation":"Recommendations should be based on the client's legitimate objectives, not compensation alone.","conceptId":"C149","variant":3,"id":"E05Q04"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"No income after the first retirement.\" Select the statement that should replace this inaccurate advice.","options":["Life insurance payable at the first death only","A single lump-sum payment only","Income while either of two covered annuitants remains alive, as specified","No income after the first retirement"],"answer":2,"explanation":"Joint-and-survivor options continue all or part of income to a survivor based on the payout selection.","conceptId":"C092","variant":4,"id":"E05Q05"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"The guaranteed annual death benefit.\" Which answer most accurately corrects the misunderstanding?","options":["The amount owed to the contingent beneficiary","The producer's commission","The guaranteed annual death benefit","The amount payable to the owner upon surrender after applicable charges and loans"],"answer":3,"explanation":"Net surrender value reflects contract cash values less surrender charges and outstanding debt.","conceptId":"C040","variant":2,"id":"E05Q06"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"Whether the agent is still employed.\" Select the statement that should replace this inaccurate advice.","options":["Whether the agent is still employed","Whether the beneficiary likes the policy","Whether dividends were reinvested","Whether material application misrepresentations or other valid grounds affect coverage"],"answer":3,"explanation":"The insurer may investigate a death within the contestability period under applicable law.","conceptId":"C123","variant":4,"id":"E05Q07"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"Mandatory annual cash withdrawals.\" Which of the following would be the most accurate response?","options":["Federal tax refunds","Mandatory annual cash withdrawals","Guaranteed stock dividends","Non-guaranteed policy dividends"],"answer":3,"explanation":"Mutual or participating policy dividends depend on the insurer's divisible surplus and are not guaranteed.","conceptId":"C042","variant":3,"id":"E05Q08"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"Always deductible interest.\" Which of the following would be the most accurate response?","options":["Always deductible interest","Always an immediate tax on the entire death benefit","Usually no current income tax on the loan, but lapse or surrender can trigger taxable gain","Automatically a tax-free gift to the producer"],"answer":2,"explanation":"Policy loans can be tax-efficient but create interest and potential taxable lapse risk.","conceptId":"C162","variant":3,"id":"E05Q09"},{"category":"Provisions & Riders","stem":"What is an absolute assignment?","options":["A short-term loan against cash value only","A transfer of all ownership rights in a policy","A term insurance conversion only","A temporary grace period"],"answer":1,"explanation":"Absolute assignment is broader than collateral assignment.","conceptId":"C064","variant":1,"id":"E05Q10"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"To eliminate all underwriting.\" Which of the following would be the most accurate response?","options":["To pay double benefits after every accidental injury","To pay a benefit only after policy surrender","To eliminate all underwriting","To allow an eligible insured to receive part of the death benefit while alive under qualifying conditions"],"answer":3,"explanation":"Accelerated benefits advance proceeds for defined qualifying illness or other triggers and can reduce the later death benefit.","conceptId":"C072","variant":3,"id":"E05Q11"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Coverage limited to exactly one year.\" Which answer most accurately corrects the misunderstanding?","options":["Coverage limited to exactly one year","Term coverage that pays only a partial death benefit","A policy that cannot build cash value","Permanent life insurance with premiums scheduled for fewer years than coverage lasts"],"answer":3,"explanation":"A 20-pay whole life policy may be fully paid after 20 years but continue for life.","conceptId":"C033","variant":2,"id":"E05Q12"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"$100,000.\" Which answer most accurately corrects the misunderstanding?","options":["$250,000","$125,000","$150,000","$100,000"],"answer":2,"explanation":"60% of $250,000 is $150,000.","conceptId":"C173","variant":2,"id":"E05Q13"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"A single immediate payment only.\" Select the statement that should replace this inaccurate advice.","options":["Payments over a selected number of years","A single immediate payment only","Only interest is payable","Payments until age 120 no matter what"],"answer":0,"explanation":"A fixed period establishes duration; payment size depends on proceeds and contract assumptions.","conceptId":"C080","variant":4,"id":"E05Q14"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"To waive every future premium.\" Which answer most accurately corrects the misunderstanding?","options":["To extend a policy after its maturity without conditions","To keep coverage in force for a specified time after a premium is due","To allow a beneficiary change after claim payment","To waive every future premium"],"answer":1,"explanation":"A grace period provides a window to pay overdue premiums while coverage generally continues.","conceptId":"C053","variant":2,"id":"E05Q15"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"A guarantee all debt is forgiven.\" Select the statement that should replace this inaccurate advice.","options":["A permanent private life policy replacement in every case","A guaranteed benefit for every unrelated person","A potential existing income source that may reduce some survivor income needs","A guarantee all debt is forgiven"],"answer":2,"explanation":"Survivor benefits are subject to eligibility and may be included when assessing resources.","conceptId":"C183","variant":4,"id":"E05Q16"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"A state examination proctor's review.\" Which of the following would be the most accurate response?","options":["The beneficiary's preparation of a tax return","A state examination proctor's review","The insurer's investment selection","The producer's initial collection and observation of risk information"],"answer":3,"explanation":"Producers help collect complete applications and identify relevant underwriting facts.","conceptId":"C116","variant":3,"id":"E05Q17"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"To inspect roof shingles for life claims.\" Which answer most accurately corrects the misunderstanding?","options":["To inspect roof shingles for life claims","To gather permitted background information relevant to underwriting","To pay the agent's commissions","To replace all medical evidence"],"answer":1,"explanation":"Inspection reports may assess finances, activities, and reputation consistent with law and consent.","conceptId":"C115","variant":2,"id":"E05Q18"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"Updating an insured's phone number.\" Which of the following would be the most accurate response?","options":["Adjusting a beneficiary address","Correcting a typographical mistake","Using values in an existing policy to fund another policy primarily to generate new compensation without consumer benefit","Updating an insured's phone number"],"answer":2,"explanation":"Churning can disadvantage consumers with new costs, surrender charges, or lost benefits.","conceptId":"C133","variant":3,"id":"E05Q19"},{"category":"Fundamentals","stem":"A life insurance contract is aleatory because what is exchanged?","options":["There is no uncertainty about when the claim occurs","The producer decides the benefit after death","Both parties exchange equal amounts on the issue date","Unequal values may be exchanged depending on an uncertain event"],"answer":3,"explanation":"Premiums paid may be much lower or higher than the death benefit because timing of death is uncertain.","conceptId":"C004","variant":1,"id":"E05Q20"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"Whether the policy is a contract of adhesion.\" Select the statement that should replace this inaccurate advice.","options":["The insurer's state of domicile","The beneficiary's right to name an agent","Underwriting risk classification","Whether the policy is a contract of adhesion"],"answer":2,"explanation":"Insurers use relevant underwriting factors to classify expected mortality risk.","conceptId":"C012","variant":4,"id":"E05Q21"},{"category":"Business & Tax","stem":"A term policy costs $45 monthly. How much is paid over 12 months if the rate does not change?","options":["$450","$495","$5,400","$540"],"answer":3,"explanation":"Annual premium at $45 monthly is 12 × $45 = $540.","conceptId":"C174","variant":1,"id":"E05Q22"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Pay dividends to the producer.\" Which of the following would be the most accurate response?","options":["Pay dividends to the producer","Increase the face amount every year","Use available cash value as a loan to pay overdue premiums when elected","Guarantee a policy never carries interest"],"answer":2,"explanation":"Automatic premium loans can prevent lapse but create policy debt and interest.","conceptId":"C067","variant":3,"id":"E05Q23"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Suggest concealing relevant medical history.\" Which answer most accurately corrects the misunderstanding?","options":["Suggest concealing relevant medical history","Guarantee approval without underwriting","Alter answers after the applicant signs","Record answers accurately and submit complete information to the insurer"],"answer":3,"explanation":"Agents must transmit accurate application information and should not misrepresent material facts.","conceptId":"C108","variant":2,"id":"E05Q24"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"Variable annuity.\" Which answer most accurately corrects the misunderstanding?","options":["Variable annuity","Equity mutual fund","Fixed annuity","Exchange traded fund"],"answer":2,"explanation":"Fixed annuities generally credit contractually specified or declared interest with applicable guarantees.","conceptId":"C086","variant":2,"id":"E05Q25"},{"category":"Provisions & Riders","stem":"What does a free-look period primarily permit?","options":["A beneficiary to set the premium","An owner to avoid all taxes forever","The policyowner to review the delivered policy and return it within the allowed period under applicable terms","The insurer to ignore the application"],"answer":2,"explanation":"Free look permits cancellation within a specified review window, with refund terms governed by law and policy.","conceptId":"C075","variant":1,"id":"E05Q26"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"Grace period.\" Which answer most accurately corrects the misunderstanding?","options":["Assignment clause","Insuring clause","Misstatement of age clause","Grace period"],"answer":1,"explanation":"The insuring clause states the principal coverage promise.","conceptId":"C052","variant":2,"id":"E05Q27"},{"category":"Ethics & CA Law","stem":"Who regulates insurers and insurance producers in California?","options":["California Department of Insurance under the Insurance Commissioner","Federal Reserve alone","Local city council alone","Department of Motor Vehicles alone"],"answer":0,"explanation":"CDI oversees insurance licensing and regulation in California.","conceptId":"C135","variant":1,"id":"E05Q28"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"Transfer ownership to the agent.\" Select the statement that should replace this inaccurate advice.","options":["Verify coverage and claim facts, then determine benefits under policy and law","Begin underwriting an entirely new insured","Transfer ownership to the agent","Pay every applicant a dividend"],"answer":0,"explanation":"Claims adjudication confirms the policy and the claimant's entitlement.","conceptId":"C130","variant":4,"id":"E05Q29"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Both insureds have died.\" Which answer most accurately corrects the misunderstanding?","options":["The policyowner retires","The policy reaches a stated cash value","The first insured in the covered pair dies","Both insureds have died"],"answer":2,"explanation":"First-to-die coverage protects against the first death among insureds.","conceptId":"C049","variant":2,"id":"E05Q30"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"Every insured is promised identical lifespan.\" Which of the following would be the most accurate response?","options":["The insurer ignores probability","Every insured is promised identical lifespan","Every applicant deposits the full death benefit upfront","Many policyowners pay premiums to fund claims experienced by a smaller number"],"answer":3,"explanation":"Pooling spreads unpredictable individual loss across a broad group.","conceptId":"C023","variant":3,"id":"E05Q31"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"Individual coverage purchased through an agent.\" Which of the following would be the most accurate response?","options":["Individual coverage purchased through an agent","Group coverage for which the sponsor pays the full premium","Coverage with premiums split evenly by law","Coverage that cannot have beneficiaries"],"answer":1,"explanation":"Noncontributory coverage is financed by the employer or group sponsor.","conceptId":"C182","variant":3,"id":"E05Q32"},{"category":"Annuities & Retirement","stem":"What is the general federal tax treatment of growth inside a nonqualified deferred annuity before distribution?","options":["Earnings are generally tax deferred","Earnings are always tax free forever","Earnings must be taxed every week","There is no taxation at any time"],"answer":0,"explanation":"Tax deferral postpones income tax on earnings until taxable distributions occur.","conceptId":"C094","variant":1,"id":"E05Q33"},{"category":"Term & Whole Life","stem":"What does a modified whole life premium design generally provide?","options":["Lower initial scheduled premiums that increase at a stated later point","A permanent premium waiver from the start","No underwriting under any circumstances","A fluctuating face amount tied to inflation only"],"answer":0,"explanation":"Modified premium whole life changes premium levels according to the contract schedule.","conceptId":"C051","variant":1,"id":"E05Q34"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"The entire surrender value is always tax free.\" Which answer most accurately corrects the misunderstanding?","options":["Gain above the policyowner's adjusted basis is generally taxable, subject to applicable rules","There is never a taxable surrender gain","The entire surrender value is always tax free","The entire original face amount is taxed"],"answer":0,"explanation":"Surrender proceeds exceeding basis generally produce ordinary income rather than capital gain.","conceptId":"C164","variant":2,"id":"E05Q35"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"The applicant is the primary beneficiary.\" Select the statement that should replace this inaccurate advice.","options":["The insurer will not issue coverage under the proposed terms","The applicant is the primary beneficiary","The policy is automatically approved","The insurer guarantees a low rate"],"answer":0,"explanation":"A decline means the application was not accepted under the insurer's underwriting criteria.","conceptId":"C126","variant":4,"id":"E05Q36"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"All index crediting is guaranteed at 15%.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer is a mutual fund","Index-linked crediting and policy values are not guaranteed at that illustrated rate","The death benefit becomes taxable annually","All index crediting is guaranteed at 15%"],"answer":1,"explanation":"Illustrated non-guaranteed values must not be described as guaranteed results.","conceptId":"C147","variant":2,"id":"E05Q37"},{"category":"Business & Tax","stem":"What is the main distinction between term life and an annuity?","options":["Both are property insurance","Neither is a contract","Term life addresses premature-death risk; an annuity can address long-life income risk","Both always pay identical amounts at death"],"answer":2,"explanation":"Life coverage and annuities address different financial risks.","conceptId":"C185","variant":1,"id":"E05Q38"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"Guarantee no claims occur.\" Which of the following would be the most accurate response?","options":["Predict aggregate losses more reliably for a large group","Guarantee no claims occur","Predict the exact death date of each insured","Eliminate underwriting"],"answer":0,"explanation":"A large population makes actual mortality experience more predictable in aggregate.","conceptId":"C008","variant":3,"id":"E05Q39"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"The insurer's claims manager.\" Which of the following would be the most accurate response?","options":["The person whose life is used to determine annuity payments under life-contingent options","The state insurance commissioner","The insurer's claims manager","Always the beneficiary and never the owner"],"answer":0,"explanation":"The annuitant's life may measure how long payments continue.","conceptId":"C089","variant":3,"id":"E05Q40"},{"category":"Ethics & CA Law","stem":"What is a producer's ethical obligation when discussing a policy?","options":["Present material benefits, exclusions, costs, and limitations accurately","Suggest incorrect answers on an application","Promise dividends are guaranteed","Hide replacement charges"],"answer":0,"explanation":"Accurate disclosures support informed consumer decisions and avoid misrepresentation.","conceptId":"C134","variant":1,"id":"E05Q41"},{"category":"Underwriting & Claims","stem":"Which source often provides a detailed history of an applicant's treatment and diagnosis?","options":["Vehicle title report","Credit card reward statement","Attending physician statement (APS)","Property deed"],"answer":2,"explanation":"An APS may help an insurer understand medical conditions and treatment history.","conceptId":"C109","variant":1,"id":"E05Q42"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"A premium paid to a reinsurer.\" Select the statement that should replace this inaccurate advice.","options":["A contractual charge that may apply to withdrawals or surrender during specified years","An automatic annual death benefit","A premium paid to a reinsurer","A tax imposed by a producer"],"answer":0,"explanation":"Surrender schedules discourage early withdrawal and may decline over time.","conceptId":"C093","variant":4,"id":"E05Q43"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Whole life always has lower initial premiums.\" Which answer most accurately corrects the misunderstanding?","options":["Whole life generally provides lifelong protection and guaranteed cash value if required premiums are paid","Whole life always has lower initial premiums","Term always has investment subaccounts","Whole life never has a surrender charge"],"answer":0,"explanation":"Traditional whole life includes permanent protection and a cash value schedule.","conceptId":"C031","variant":2,"id":"E05Q44"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"Always recalculated monthly based on stock returns.\" Which answer most accurately corrects the misunderstanding?","options":["Fixed and payable under the chosen premium schedule","Paid only when death occurs","Always recalculated monthly based on stock returns","Required only in the first month"],"answer":0,"explanation":"Ordinary whole life generally uses scheduled level premiums.","conceptId":"C032","variant":2,"id":"E05Q45"},{"category":"Fundamentals","stem":"What does the applicant's signature generally confirm on a life application?","options":["The beneficiary automatically owns the policy","The insurer guarantees policy issuance","All medical questions can be omitted","The applicant attests to the statements and authorizations provided"],"answer":3,"explanation":"Signing confirms information and consents, not a promise that underwriting will approve coverage.","conceptId":"C024","variant":1,"id":"E05Q46"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"A casual online follower insuring an influencer.\" Select the statement that should replace this inaccurate advice.","options":["A stranger insuring a celebrity without consent","A gambler betting on a neighbor's death","A business insuring a key employee whose death would cause a financial loss","A casual online follower insuring an influencer"],"answer":2,"explanation":"Employers may have an insurable interest in key employees subject to applicable rules.","conceptId":"C022","variant":4,"id":"E05Q47"},{"category":"Fundamentals","stem":"A life insurance contract is unilateral because which statement is true?","options":["Only the insurer makes a legally enforceable promise to perform if conditions are met","The insured can rewrite contract terms at will","Both parties promise equal performance","Both parties must pay claims"],"answer":0,"explanation":"The policyowner promises no ongoing performance enforceable as a contract; premiums are needed to keep coverage in force.","conceptId":"C003","variant":1,"id":"E05Q48"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"To guarantee investment profits.\" Which answer most accurately corrects the misunderstanding?","options":["To eliminate every financial risk","To guarantee investment profits","To provide financial protection against premature death","To insure a home against fire"],"answer":2,"explanation":"Life insurance transfers the financial risk of an insured person's death to the insurer.","conceptId":"C001","variant":2,"id":"E05Q49"},{"category":"Annuities & Retirement","stem":"An annuity pays a guaranteed $1,200 monthly for 10 years under a fixed-period settlement. How much is scheduled to be paid during the full period?","options":["$144,000","$120,000","$240,000","$12,000"],"answer":0,"explanation":"There are 120 months in 10 years: 120 × 1,200 = 144,000.","conceptId":"X007","variant":1,"id":"E05Q50"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Assume no insurance exists.\" Which answer most accurately corrects the misunderstanding?","options":["Assume no insurance exists","Purchase a replacement policy for the deceased","Wait for the state to send a check automatically","Contact the insurer with identifying information and proof of death"],"answer":3,"explanation":"Insurers can help locate policies and explain claims documentation.","conceptId":"C129","variant":2,"id":"E05Q51"},{"category":"Business & Tax","stem":"What is the primary purpose of a personal life insurance needs analysis?","options":["Guarantee future interest rates","Estimate the survivor's financial obligations and resources to choose an appropriate coverage amount","Predict the exact day of death","Select the insurer with the highest commission"],"answer":1,"explanation":"Needs analysis considers debts, income replacement, dependents, education, and existing assets.","conceptId":"C165","variant":1,"id":"E05Q52"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Claim CDI guarantees all benefits in full.\" Select the statement that should replace this inaccurate advice.","options":["Claim CDI guarantees all benefits in full","Quote an invented credit rating","Use current credible financial information and avoid guarantees beyond policy terms","Promise the insurer can never fail"],"answer":2,"explanation":"Financial ratings are opinions, and policy guarantees depend on insurer claims-paying ability.","conceptId":"C152","variant":4,"id":"E05Q53"},{"category":"Term & Whole Life","stem":"What does a nonparticipating life policy generally mean?","options":["It has no beneficiaries","All death benefits are excluded","It must be term insurance","Policyowners are not entitled to participate in insurer surplus through policy dividends"],"answer":3,"explanation":"Nonparticipating policies do not pay participating policy dividends.","conceptId":"C043","variant":1,"id":"E05Q54"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"The state must purchase all shares automatically.\" Which answer most accurately corrects the misunderstanding?","options":["The state must purchase all shares automatically","It guarantees the stock will appreciate","Each owner can insure other owners and use proceeds to buy a deceased owner's interest","It substitutes for a written agreement"],"answer":2,"explanation":"Cross-purchase plans have owners buy interests directly; entity-redemption plans differ.","conceptId":"C184","variant":2,"id":"E05Q55"},{"category":"Fundamentals","stem":"Why is a life insurance contract considered a contract of adhesion?","options":["Both parties negotiate every word equally","It is automatically renewed every month","It must be signed by every beneficiary","The insurer drafts the policy and the applicant usually accepts or rejects its terms"],"answer":3,"explanation":"Ambiguities in an adhesion contract are generally interpreted against the drafter.","conceptId":"C005","variant":1,"id":"E05Q56"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Any insurer advertisement ever produced.\" Which of the following would be the most accurate response?","options":["Any insurer advertisement ever produced","The policy and attached application and endorsements as applicable","An agent's unwritten verbal promises","A beneficiary's unrelated bank statements"],"answer":1,"explanation":"The written contract is assembled from the policy and specified attached documents.","conceptId":"C057","variant":3,"id":"E05Q57"},{"category":"Business & Tax","stem":"How does a needs-based approach differ from a human-life-value approach?","options":["It ignores outstanding debts","It uses only the insurer's advertising budget","It insures everyone for exactly the same amount","It totals specific financial needs and subtracts available resources"],"answer":3,"explanation":"The needs method estimates expenses and obligations, then offsets assets and existing insurance.","conceptId":"C167","variant":1,"id":"E05Q58"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Use premiums as personal funds temporarily.\" Which answer most accurately corrects the misunderstanding?","options":["Keep premiums regardless of policy status","Handle entrusted premiums honestly and remit/account for them as required","Use premiums as personal funds temporarily","Lend client premiums without permission"],"answer":1,"explanation":"Producers must properly safeguard and account for money received in their insurance capacity.","conceptId":"C138","variant":2,"id":"E05Q59"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"A securities prospectus.\" Which of the following would be the most accurate response?","options":["Proof the employee owns the master contract","A securities prospectus","Evidence and summary of a member's coverage under the group master contract","An insurer's annual income statement"],"answer":2,"explanation":"Certificates describe individual group coverage, while the master contract controls.","conceptId":"C179","variant":3,"id":"E05Q60"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"To handle only property claims.\" Select the statement that should replace this inaccurate advice.","options":["To handle only property claims","To determine who inherits the insured's estate","To guarantee every application is accepted","To evaluate applicants and decide whether and on what terms coverage will be offered"],"answer":3,"explanation":"Underwriting evaluates risk characteristics and assigns a classification or decision.","conceptId":"C107","variant":4,"id":"E05Q61"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"Life with cash refund.\" Select the statement that should replace this inaccurate advice.","options":["Life with 20-year period certain","Life with cash refund","Straight life income","Joint and survivor income"],"answer":2,"explanation":"Straight life typically offers higher payments because it has no survivor or refund guarantee.","conceptId":"C090","variant":4,"id":"E05Q62"},{"category":"Term & Whole Life","stem":"Which dividend option generally reduces the current premium owed?","options":["Premium reduction option","Accumulation at interest","One-year term option","Cash dividend option"],"answer":0,"explanation":"The premium-reduction option applies declared dividends toward scheduled premium.","conceptId":"C045","variant":1,"id":"E05Q63"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"An automatic retirement annuity.\" Which of the following would be the most accurate response?","options":["An additional benefit when death meets the rider's definition of accident","A refund whenever the insured gets sick","A guaranteed policy dividend","An automatic retirement annuity"],"answer":0,"explanation":"Accidental death riders pay only under defined accidental-death conditions and exclusions.","conceptId":"C071","variant":3,"id":"E05Q64"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Advertise hypothetical returns as guaranteed.\" Which answer most accurately corrects the misunderstanding?","options":["Claim authorization from CDI without basis","Avoid false or misleading claims about coverage, benefits, insurer identity, and guarantees","Hide that a statement is an insurance solicitation","Advertise hypothetical returns as guaranteed"],"answer":1,"explanation":"Insurance advertising must not mislead consumers.","conceptId":"C142","variant":2,"id":"E05Q65"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"Only when the beneficiary files a claim.\" Select the statement that should replace this inaccurate advice.","options":["When the contract is made","Only when the insured dies","Only when the beneficiary files a claim","At every annual renewal"],"answer":0,"explanation":"Insurable interest is generally required at policy inception, not continuously throughout the policy.","conceptId":"C021","variant":4,"id":"E05Q66"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"It contains 150 questions and must be completed in 30 minutes.\" Which of the following would be the most accurate response?","options":["It contains 25 questions with unlimited time","It contains 150 questions and must be completed in 30 minutes","It is automatically passed by completing this practice app","It contains 75 questions, with 105 minutes allowed"],"answer":3,"explanation":"The October 2026 PSI candidate bulletin lists 75 questions and 105 minutes for the Life license exam.","conceptId":"C154","variant":3,"id":"E05Q67"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"A cash account only for college tuition.\" Which answer most accurately corrects the misunderstanding?","options":["An increase in the adult's retirement income","Term life coverage on eligible children attached to an adult policy","A cash account only for college tuition","A medical plan for children"],"answer":1,"explanation":"Child riders provide limited death coverage on eligible children under the rider terms.","conceptId":"C073","variant":2,"id":"E05Q68"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"Preferred shirt color.\" Which of the following would be the most accurate response?","options":["A history of serious heart disease","Favorite television program","Preferred shirt color","The insured's favorite holiday"],"answer":0,"explanation":"Serious medical conditions commonly affect expected mortality and insurer decisions.","conceptId":"C112","variant":3,"id":"E05Q69"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Converting a policy into health insurance.\" Which of the following would be the most accurate response?","options":["Eliminating the insurer's claim obligation","Converting a policy into health insurance","Pledging policy value or proceeds as security for a loan","Making a child the insured automatically"],"answer":2,"explanation":"A lender can receive proceeds up to its secured interest before the remainder goes to beneficiaries.","conceptId":"C063","variant":3,"id":"E05Q70"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"It is protected by FDIC deposit insurance as a bank checking account.\" Which of the following would be the most accurate response?","options":["It always permits free instant withdrawals without charges","It is protected by FDIC deposit insurance as a bank checking account","Withdrawals may face surrender charges, taxes, or limited liquidity","It cannot earn any interest"],"answer":2,"explanation":"Annuity liquidity is contractual and can carry costs or taxes, making emergency access uncertain.","conceptId":"C103","variant":3,"id":"E05Q71"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"$70,000.\" Select the statement that should replace this inaccurate advice.","options":["$70,000","$350,000","$490,000","$230,000"],"answer":1,"explanation":"Needs-based gap = $300,000 + $120,000 - $70,000 = $350,000.","conceptId":"C172","variant":4,"id":"E05Q72"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"To pay property taxes only.\" Which answer most accurately corrects the misunderstanding?","options":["To cancel the base policy","To pay property taxes only","To buy small amounts of additional fully paid whole life insurance","To buy an unrelated stock ETF directly"],"answer":2,"explanation":"Paid-up additions increase cash value and death benefit without future premiums for the additions.","conceptId":"C044","variant":2,"id":"E05Q73"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Assume the new contract is always better.\" Which of the following would be the most accurate response?","options":["Ignore existing beneficiaries","Focus only on the new policy's first-year premium","Assume the new contract is always better","Compare the existing and proposed contracts, including surrender charges and lost guarantees"],"answer":3,"explanation":"Replacement analysis should consider costs, timing, exclusions, taxes and lost rights.","conceptId":"C141","variant":3,"id":"E05Q74"},{"category":"Annuities & Retirement","stem":"What is annuitization?","options":["Surrendering a life policy for a check","Adding an accidental death rider","Converting annuity value into a series of income payments under a payout option","Naming a beneficiary"],"answer":2,"explanation":"Annuitization starts a payout structure often based on life expectancy, rate, and options.","conceptId":"C088","variant":1,"id":"E05Q75"}]},{"title":"Exam 6","questions":[{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"The policy is automatically void for every age error.\" Which answer most accurately corrects the misunderstanding?","options":["The policy is automatically void for every age error","Benefits or premiums are adjusted to reflect the correct age","The producer pays the difference personally","The policy converts to disability insurance"],"answer":1,"explanation":"A wrong age typically leads to an actuarial adjustment rather than automatically voiding the contract.","conceptId":"C056","variant":2,"id":"E06Q01"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"An applicant who always gets preferred rates.\" Which answer most accurately corrects the misunderstanding?","options":["A person with no insurable interest","An applicant who always gets preferred rates","An applicant with higher-than-normal expected mortality who may be charged extra premium","A beneficiary who is a minor"],"answer":2,"explanation":"Higher risk can result in rating, exclusions if lawful, postponement, or decline.","conceptId":"C014","variant":2,"id":"E06Q02"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"A producer's phone number change.\" Select the statement that should replace this inaccurate advice.","options":["An incorrect statement important to an insurer's underwriting decision","Any minor spelling error","A beneficiary's new mailing address","A producer's phone number change"],"answer":0,"explanation":"Materiality relates to whether accurate facts would have influenced acceptance, risk, or premium.","conceptId":"C020","variant":4,"id":"E06Q03"},{"category":"Annuities & Retirement","stem":"For a nonqualified annuity withdrawal before annuitization, what is the usual federal ordering rule?","options":["Every withdrawal is a capital gain","Principal is always withdrawn first","Withdrawals are never taxable","Earnings are generally withdrawn first for tax purposes"],"answer":3,"explanation":"Nonqualified annuity distributions commonly follow last-in-first-out ordering before annuitization.","conceptId":"C095","variant":1,"id":"E06Q04"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"The insured's favorite holiday.\" Select the statement that should replace this inaccurate advice.","options":["Preferred shirt color","The insured's favorite holiday","A history of serious heart disease","Favorite television program"],"answer":2,"explanation":"Serious medical conditions commonly affect expected mortality and insurer decisions.","conceptId":"C112","variant":4,"id":"E06Q05"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"A policy cancelled during its free look.\" Select the statement that should replace this inaccurate advice.","options":["A guaranteed pension from Social Security","A contract with no life insurance death benefit","A policy cancelled during its free look","A life insurance contract that fails the federal seven-pay test and receives less favorable distribution tax treatment"],"answer":3,"explanation":"MEC distributions and loans commonly have earnings-first taxation and may face early-distribution penalties.","conceptId":"C163","variant":4,"id":"E06Q06"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"No premium will be charged.\" Select the statement that should replace this inaccurate advice.","options":["The applicant meets the insurer's average underwriting guidelines","The applicant is uninsurable","The applicant receives a guaranteed dividend","No premium will be charged"],"answer":0,"explanation":"Standard risks generally receive standard rates based on the carrier's underwriting rules.","conceptId":"C013","variant":4,"id":"E06Q07"},{"category":"Term & Whole Life","stem":"A participating life insurance policy may pay what?","options":["Mandatory annual cash withdrawals","Guaranteed stock dividends","Non-guaranteed policy dividends","Federal tax refunds"],"answer":2,"explanation":"Mutual or participating policy dividends depend on the insurer's divisible surplus and are not guaranteed.","conceptId":"C042","variant":1,"id":"E06Q08"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"Both parties exchange equal amounts on the issue date.\" Which answer most accurately corrects the misunderstanding?","options":["Unequal values may be exchanged depending on an uncertain event","The producer decides the benefit after death","Both parties exchange equal amounts on the issue date","There is no uncertainty about when the claim occurs"],"answer":0,"explanation":"Premiums paid may be much lower or higher than the death benefit because timing of death is uncertain.","conceptId":"C004","variant":2,"id":"E06Q09"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"The insured's heirs automatically owe the full face amount.\" Select the statement that should replace this inaccurate advice.","options":["The balance and accrued interest generally reduce benefits paid","The loan is paid by the state","The death benefit always doubles","The insured's heirs automatically owe the full face amount"],"answer":0,"explanation":"Policy loan debt generally offsets death proceeds and may create lapse or tax risks.","conceptId":"C068","variant":4,"id":"E06Q10"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"Claim authorization from CDI without basis.\" Select the statement that should replace this inaccurate advice.","options":["Avoid false or misleading claims about coverage, benefits, insurer identity, and guarantees","Claim authorization from CDI without basis","Advertise hypothetical returns as guaranteed","Hide that a statement is an insurance solicitation"],"answer":0,"explanation":"Insurance advertising must not mislead consumers.","conceptId":"C142","variant":4,"id":"E06Q11"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Hide replacement charges.\" Which of the following would be the most accurate response?","options":["Suggest incorrect answers on an application","Hide replacement charges","Present material benefits, exclusions, costs, and limitations accurately","Promise dividends are guaranteed"],"answer":2,"explanation":"Accurate disclosures support informed consumer decisions and avoid misrepresentation.","conceptId":"C134","variant":3,"id":"E06Q12"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"The insurer ignores probability.\" Select the statement that should replace this inaccurate advice.","options":["The insurer ignores probability","Every applicant deposits the full death benefit upfront","Every insured is promised identical lifespan","Many policyowners pay premiums to fund claims experienced by a smaller number"],"answer":3,"explanation":"Pooling spreads unpredictable individual loss across a broad group.","conceptId":"C023","variant":4,"id":"E06Q13"},{"category":"Underwriting & Claims","stem":"What is a primary purpose of a policy's suicide provision?","options":["To prohibit any death benefit payment forever","To set the owner's dividend rate","To specify how claims are handled if suicide occurs during the initial exclusion period","To guarantee any claim at any time without exception"],"answer":2,"explanation":"Suicide clauses typically limit early suicide claims, often returning premiums, with rules varying by jurisdiction.","conceptId":"C125","variant":1,"id":"E06Q14"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Assure the customer all risks are covered.\" Which of the following would be the most accurate response?","options":["Invent an explanation to close the sale","Ignore the exclusion as minor","Confirm its meaning from the insurer's policy materials before making a representation","Assure the customer all risks are covered"],"answer":2,"explanation":"Competence requires knowing policy limits and avoiding unsupported statements.","conceptId":"C144","variant":3,"id":"E06Q15"},{"category":"Fundamentals","stem":"Which insurance principle requires a legitimate financial interest in the insured at policy inception?","options":["Insurable interest","Indemnity","Contribution","Subrogation"],"answer":0,"explanation":"Insurable interest discourages wagering on human life; it generally must exist when a life policy is purchased.","conceptId":"C002","variant":1,"id":"E06Q16"},{"category":"Term & Whole Life","stem":"How are dividends commonly used under the paid-up additions option?","options":["To pay property taxes only","To cancel the base policy","To buy an unrelated stock ETF directly","To buy small amounts of additional fully paid whole life insurance"],"answer":3,"explanation":"Paid-up additions increase cash value and death benefit without future premiums for the additions.","conceptId":"C044","variant":1,"id":"E06Q17"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"It verifies the beneficiary's occupation.\" Which of the following would be the most accurate response?","options":["The state requires the applicant to own a car","It verifies the beneficiary's occupation","Driving history can indicate mortality-related risk","It replaces all application signatures"],"answer":2,"explanation":"Serious violations or risky driving can be relevant to life underwriting.","conceptId":"C124","variant":3,"id":"E06Q18"},{"category":"Provisions & Riders","stem":"Which nonforfeiture option uses cash value to purchase temporary coverage at the original face amount for as long as the value supports it?","options":["Automatic premium loan","Dividend accumulation","Extended term insurance","Reduced paid-up insurance"],"answer":2,"explanation":"Extended term preserves a face amount for a limited duration based on net cash value.","conceptId":"C066","variant":1,"id":"E06Q19"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"To calculate the agent's commission.\" Which answer most accurately corrects the misunderstanding?","options":["To determine a medical deductible","To determine the portion of each qualifying payment treated as return of investment versus taxable income","To set the beneficiary's age","To calculate the agent's commission"],"answer":1,"explanation":"The exclusion ratio allocates annuity payments between basis recovery and taxable income, when applicable.","conceptId":"C097","variant":2,"id":"E06Q20"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"The insurer's state of domicile.\" Which of the following would be the most accurate response?","options":["The beneficiary's right to name an agent","The insurer's state of domicile","Whether the policy is a contract of adhesion","Underwriting risk classification"],"answer":3,"explanation":"Insurers use relevant underwriting factors to classify expected mortality risk.","conceptId":"C012","variant":3,"id":"E06Q21"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"The entire principal each month.\" Which answer most accurately corrects the misunderstanding?","options":["Interest on proceeds retained by the insurer","The entire principal each month","Only the insurer's commission","A fixed share of the insured's salary"],"answer":0,"explanation":"The insurer retains principal and pays interest as stipulated; principal is handled under the agreement.","conceptId":"C079","variant":2,"id":"E06Q22"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"The entire original face amount is taxed.\" Which of the following would be the most accurate response?","options":["There is never a taxable surrender gain","The entire surrender value is always tax free","Gain above the policyowner's adjusted basis is generally taxable, subject to applicable rules","The entire original face amount is taxed"],"answer":2,"explanation":"Surrender proceeds exceeding basis generally produce ordinary income rather than capital gain.","conceptId":"C164","variant":3,"id":"E06Q23"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"Cash surrender.\" Which answer most accurately corrects the misunderstanding?","options":["Extended term insurance","Policy replacement","Reduced paid-up insurance","Cash surrender"],"answer":2,"explanation":"Reduced paid-up uses available value to buy a smaller fully paid permanent policy.","conceptId":"C065","variant":2,"id":"E06Q24"},{"category":"Ethics & CA Law","stem":"What is the general intent of California's insurance licensing requirement?","options":["To guarantee everyone a job as an agent","To ensure only qualified and authorized persons transact regulated insurance","To replace insurance contracts with bank loans","To eliminate all private insurers"],"answer":1,"explanation":"Licensing protects consumers through qualification and regulatory oversight.","conceptId":"C145","variant":1,"id":"E06Q25"},{"category":"Business & Tax","stem":"Why might business owners use cross-purchase buy-sell funding?","options":["It guarantees the stock will appreciate","Each owner can insure other owners and use proceeds to buy a deceased owner's interest","It substitutes for a written agreement","The state must purchase all shares automatically"],"answer":1,"explanation":"Cross-purchase plans have owners buy interests directly; entity-redemption plans differ.","conceptId":"C184","variant":1,"id":"E06Q26"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Monthly premiums for life.\" Which answer most accurately corrects the misunderstanding?","options":["One large premium paid at issue","An annual adjustable premium","Monthly premiums for life","A zero-cost application"],"answer":0,"explanation":"A single premium funds the policy upfront; tax treatment may differ for heavily funded policies.","conceptId":"C034","variant":2,"id":"E06Q27"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"An annuity that only holds stock shares.\" Which of the following would be the most accurate response?","options":["A term life policy with one premium","An annuity that cannot pay income","An annuity that generally begins income payments within about one year of purchase","An annuity that only holds stock shares"],"answer":2,"explanation":"Immediate annuities begin payout relatively soon after the purchase payment.","conceptId":"C084","variant":3,"id":"E06Q28"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"Always capital gains.\" Which of the following would be the most accurate response?","options":["Always capital gains","Always subject to payroll tax","Always taxed as ordinary income from the first dollar","Generally treated as a return of premium rather than taxable income"],"answer":3,"explanation":"Life policy dividends commonly reduce the owner's cost basis; interest earned on retained dividends is typically taxable.","conceptId":"C161","variant":3,"id":"E06Q29"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"A larger outstanding mortgage.\" Which answer most accurately corrects the misunderstanding?","options":["A larger outstanding mortgage","Higher income replacement needs","More liquid savings available to survivors","More dependent children"],"answer":2,"explanation":"Existing assets can offset some future survivor needs.","conceptId":"C175","variant":2,"id":"E06Q30"},{"category":"Annuities & Retirement","stem":"What is an annuity rider?","options":["A mandatory investment advisory account","An optional contractual feature that changes benefits or guarantees, often for a fee","The same as a death certificate","A guaranteed public tax deduction"],"answer":1,"explanation":"Riders can add features such as living income benefits; their costs and limitations matter.","conceptId":"C106","variant":1,"id":"E06Q31"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"A beneficiary affidavit for all applications.\" Select the statement that should replace this inaccurate advice.","options":["A beneficiary affidavit for all applications","Automatic payment of a death benefit","A current health statement or further underwriting as the insurer requires","A reduction of the insurer's license fee"],"answer":2,"explanation":"A material health change before effective coverage may affect eligibility and the insurer's requirements.","conceptId":"C120","variant":4,"id":"E06Q32"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"A guaranteed stock-market rate of return.\" Which of the following would be the most accurate response?","options":["An index-crediting formula subject to caps, participation rates, floors, and contract charges","A guaranteed stock-market rate of return","Direct ownership of every stock in an index","A fixed government pension payment"],"answer":0,"explanation":"Indexed UL uses a contractual crediting method, not direct ownership of index shares.","conceptId":"C039","variant":3,"id":"E06Q33"},{"category":"Underwriting & Claims","stem":"What is field underwriting?","options":["The producer's initial collection and observation of risk information","The insurer's investment selection","A state examination proctor's review","The beneficiary's preparation of a tax return"],"answer":0,"explanation":"Producers help collect complete applications and identify relevant underwriting facts.","conceptId":"C116","variant":1,"id":"E06Q34"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"An automatic waiver of premiums.\" Select the statement that should replace this inaccurate advice.","options":["A guaranteed dividend rate","A promise that every future event will occur","A statement made to the best of the applicant's knowledge and belief","An automatic waiver of premiums"],"answer":2,"explanation":"Application answers are generally representations, and material misrepresentations may affect coverage.","conceptId":"C019","variant":4,"id":"E06Q35"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"Wait for the state to send a check automatically.\" Which of the following would be the most accurate response?","options":["Purchase a replacement policy for the deceased","Assume no insurance exists","Contact the insurer with identifying information and proof of death","Wait for the state to send a check automatically"],"answer":2,"explanation":"Insurers can help locate policies and explain claims documentation.","conceptId":"C129","variant":3,"id":"E06Q36"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"An automatic annual death benefit.\" Which of the following would be the most accurate response?","options":["An automatic annual death benefit","A contractual charge that may apply to withdrawals or surrender during specified years","A tax imposed by a producer","A premium paid to a reinsurer"],"answer":1,"explanation":"Surrender schedules discourage early withdrawal and may decline over time.","conceptId":"C093","variant":3,"id":"E06Q37"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"Decreasing term.\" Select the statement that should replace this inaccurate advice.","options":["Traditional fixed whole life","Annually renewable term","Decreasing term","Variable life insurance"],"answer":3,"explanation":"Variable life values can rise or fall with selected investments; securities regulation applies.","conceptId":"C037","variant":4,"id":"E06Q38"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"Whether dividends were reinvested.\" Which of the following would be the most accurate response?","options":["Whether dividends were reinvested","Whether the beneficiary likes the policy","Whether the agent is still employed","Whether material application misrepresentations or other valid grounds affect coverage"],"answer":3,"explanation":"The insurer may investigate a death within the contestability period under applicable law.","conceptId":"C123","variant":3,"id":"E06Q39"},{"category":"Provisions & Riders","stem":"What does the incontestability clause generally restrict?","options":["A beneficiary's right to make a claim","The right of the owner to change premium mode","The insurer's ability to contest the policy after the specified contestable period, subject to exceptions","The insurer's right to pay claims promptly"],"answer":2,"explanation":"After the contractual/statutory period, an insurer's grounds to contest validity are limited, with exceptions such as nonpayment.","conceptId":"C055","variant":1,"id":"E06Q40"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"An automatic dividend election.\" Which of the following would be the most accurate response?","options":["A premium payment frequency","A transfer of specified policy rights to another party","An automatic dividend election","A change in the insured's age"],"answer":1,"explanation":"Assignments transfer ownership rights or create security interests.","conceptId":"C062","variant":3,"id":"E06Q41"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Only the oldest child receives proceeds.\" Which of the following would be the most accurate response?","options":["Proceeds must be donated to charity","Every surviving beneficiary receives an equal share regardless of branch","Only the oldest child receives proceeds","A deceased beneficiary's share passes down their family branch"],"answer":3,"explanation":"Per stirpes allocation follows family branches; per capita generally divides among surviving members of the stated class.","conceptId":"C061","variant":3,"id":"E06Q42"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"Assignment clause.\" Select the statement that should replace this inaccurate advice.","options":["Assignment clause","Insuring clause","Grace period","Misstatement of age clause"],"answer":1,"explanation":"The insuring clause states the principal coverage promise.","conceptId":"C052","variant":4,"id":"E06Q43"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"Term always has investment subaccounts.\" Select the statement that should replace this inaccurate advice.","options":["Whole life always has lower initial premiums","Whole life never has a surrender charge","Term always has investment subaccounts","Whole life generally provides lifelong protection and guaranteed cash value if required premiums are paid"],"answer":3,"explanation":"Traditional whole life includes permanent protection and a cash value schedule.","conceptId":"C031","variant":4,"id":"E06Q44"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Explaining a free-look right.\" Select the statement that should replace this inaccurate advice.","options":["Paying an approved policy dividend","Giving a standard premium quote","Explaining a free-look right","Offering an inducement not specified in the policy, where prohibited by applicable law"],"answer":3,"explanation":"Rebating rules restrict improper inducements to buy insurance; assess conduct under current California law.","conceptId":"C132","variant":4,"id":"E06Q45"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"An annuity that must pay tomorrow.\" Which answer most accurately corrects the misunderstanding?","options":["A rider for accidental death","A whole life policy dividend","An annuity that must pay tomorrow","An annuity with an accumulation period before income payments begin"],"answer":3,"explanation":"Deferred annuities allow assets to accumulate before annuitization or withdrawals.","conceptId":"C085","variant":2,"id":"E06Q46"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"A beneficiary with first priority.\" Select the statement that should replace this inaccurate advice.","options":["A mandatory class for every applicant","A favorable class generally offered a lower premium than standard","A policy that never lapses","A beneficiary with first priority"],"answer":1,"explanation":"Preferred applicants meet more favorable underwriting criteria.","conceptId":"C015","variant":4,"id":"E06Q47"},{"category":"Term & Whole Life","stem":"Which policy is designed to cover a specified period and typically builds no cash value?","options":["Whole life","Traditional endowment","Variable whole life","Level term life"],"answer":3,"explanation":"Term insurance generally provides a death benefit during its term without savings value.","conceptId":"C025","variant":1,"id":"E06Q48"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"The insurer cannot decline coverage.\" Select the statement that should replace this inaccurate advice.","options":["Coverage is guaranteed regardless of medical findings","The application has been approved for all amounts","The insurer cannot decline coverage","Coverage may begin only if stated conditions are satisfied under the receipt"],"answer":3,"explanation":"Conditional receipts are not unconditional promises; read their effective-date and insurability conditions.","conceptId":"C113","variant":4,"id":"E06Q49"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"$230,000.\" Which of the following would be the most accurate response?","options":["$230,000","$490,000","$350,000","$70,000"],"answer":2,"explanation":"Needs-based gap = $300,000 + $120,000 - $70,000 = $350,000.","conceptId":"C172","variant":3,"id":"E06Q50"},{"category":"Term & Whole Life","stem":"Which life product is typically most appropriate when the primary objective is inexpensive coverage for a fixed 20-year obligation?","options":["Single-premium whole life in every case","A lifetime immediate annuity","20-year level term insurance","A deferred variable annuity"],"answer":2,"explanation":"Term commonly provides more initial death protection per premium dollar for a temporary need.","conceptId":"C041","variant":1,"id":"E06Q51"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"80%.\" Which answer most accurately corrects the misunderstanding?","options":["80%","90%","60%","100%"],"answer":2,"explanation":"The current PSI candidate bulletin states a 60% passing score for the Life exam; aim higher on practice tests.","conceptId":"C155","variant":2,"id":"E06Q52"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"Coverage paid entirely by an employer only.\" Which answer most accurately corrects the misunderstanding?","options":["Coverage paid entirely by an employer only","Coverage in which members pay some or all of the premium cost","A policy without an insured","A policy owned by the federal government"],"answer":1,"explanation":"Contributory plans require employee contributions, unlike noncontributory plans funded by the sponsor.","conceptId":"C181","variant":2,"id":"E06Q53"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"$250,000.\" Select the statement that should replace this inaccurate advice.","options":["$125,000","$100,000","$150,000","$250,000"],"answer":2,"explanation":"60% of $250,000 is $150,000.","conceptId":"C173","variant":4,"id":"E06Q54"},{"category":"Provisions & Riders","stem":"What is a child term rider?","options":["Term life coverage on eligible children attached to an adult policy","A cash account only for college tuition","An increase in the adult's retirement income","A medical plan for children"],"answer":0,"explanation":"Child riders provide limited death coverage on eligible children under the rider terms.","conceptId":"C073","variant":1,"id":"E06Q55"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"A permanent private life policy replacement in every case.\" Which answer most accurately corrects the misunderstanding?","options":["A potential existing income source that may reduce some survivor income needs","A guarantee all debt is forgiven","A permanent private life policy replacement in every case","A guaranteed benefit for every unrelated person"],"answer":0,"explanation":"Survivor benefits are subject to eligibility and may be included when assessing resources.","conceptId":"C183","variant":2,"id":"E06Q56"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"To set a consumer's beneficiary selection.\" Select the statement that should replace this inaccurate advice.","options":["To set a consumer's beneficiary selection","To guarantee its stock appreciates","To appoint the policyholder's attorney","To assess compliance and financial or market conduct condition"],"answer":3,"explanation":"Insurance departments supervise insurer solvency and market conduct.","conceptId":"C143","variant":4,"id":"E06Q57"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Comparing policy guarantees factually.\" Which answer most accurately corrects the misunderstanding?","options":["Explaining an insurer's financial rating with attribution","Making false malicious statements intended to injure an insurer's reputation or business","Comparing policy guarantees factually","Disclosing a policy's exclusions"],"answer":1,"explanation":"Unfair trade practices can prohibit knowingly false or malicious statements about competitors.","conceptId":"C139","variant":2,"id":"E06Q58"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"A short-term loan against cash value only.\" Which answer most accurately corrects the misunderstanding?","options":["A transfer of all ownership rights in a policy","A short-term loan against cash value only","A term insurance conversion only","A temporary grace period"],"answer":0,"explanation":"Absolute assignment is broader than collateral assignment.","conceptId":"C064","variant":2,"id":"E06Q59"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"Earnings are always tax free forever.\" Which answer most accurately corrects the misunderstanding?","options":["There is no taxation at any time","Earnings must be taxed every week","Earnings are always tax free forever","Earnings are generally tax deferred"],"answer":3,"explanation":"Tax deferral postpones income tax on earnings until taxable distributions occur.","conceptId":"C094","variant":2,"id":"E06Q60"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"Returning the application to the insured without issuing a policy.\" Which answer most accurately corrects the misunderstanding?","options":["Returning the application to the insured without issuing a policy","Guaranteeing every rider is free","Forgoing any premium due","Providing the issued contract and explaining relevant terms and changes"],"answer":3,"explanation":"Delivery is when the policyowner receives and can review the contract.","conceptId":"C119","variant":2,"id":"E06Q61"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Following filed actuarial rules.\" Select the statement that should replace this inaccurate advice.","options":["Charging different premiums for justified risk classes","Using relevant mortality experience","Treating people with the same risk classification differently without a lawful underwriting basis","Following filed actuarial rules"],"answer":2,"explanation":"Risk distinctions must have a lawful actuarial or underwriting justification; unfair discrimination is prohibited.","conceptId":"C137","variant":4,"id":"E06Q62"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"It must be term insurance.\" Select the statement that should replace this inaccurate advice.","options":["All death benefits are excluded","It has no beneficiaries","Policyowners are not entitled to participate in insurer surplus through policy dividends","It must be term insurance"],"answer":2,"explanation":"Nonparticipating policies do not pay participating policy dividends.","conceptId":"C043","variant":4,"id":"E06Q63"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"Required only in the first month.\" Select the statement that should replace this inaccurate advice.","options":["Fixed and payable under the chosen premium schedule","Required only in the first month","Paid only when death occurs","Always recalculated monthly based on stock returns"],"answer":0,"explanation":"Ordinary whole life generally uses scheduled level premiums.","conceptId":"C032","variant":4,"id":"E06Q64"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"Always an immediate tax on the entire death benefit.\" Which answer most accurately corrects the misunderstanding?","options":["Always an immediate tax on the entire death benefit","Automatically a tax-free gift to the producer","Always deductible interest","Usually no current income tax on the loan, but lapse or surrender can trigger taxable gain"],"answer":3,"explanation":"Policy loans can be tax-efficient but create interest and potential taxable lapse risk.","conceptId":"C162","variant":2,"id":"E06Q65"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"Any beneficiary birthday.\" Which of the following would be the most accurate response?","options":["An agent changing employers","The policyowner's retirement","The insured's death while qualifying coverage is in force","Any beneficiary birthday"],"answer":2,"explanation":"Death benefits arise on covered death and appropriate claim documentation.","conceptId":"C082","variant":3,"id":"E06Q66"},{"category":"Annuities & Retirement","stem":"Which annuity payout offers the highest periodic payment among comparable lifetime options but generally no refund after early death?","options":["Joint and survivor income","Life with cash refund","Life with 20-year period certain","Straight life income"],"answer":3,"explanation":"Straight life typically offers higher payments because it has no survivor or refund guarantee.","conceptId":"C090","variant":1,"id":"E06Q67"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"The insurer guarantees policy issuance.\" Which answer most accurately corrects the misunderstanding?","options":["All medical questions can be omitted","The insurer guarantees policy issuance","The beneficiary automatically owns the policy","The applicant attests to the statements and authorizations provided"],"answer":3,"explanation":"Signing confirms information and consents, not a promise that underwriting will approve coverage.","conceptId":"C024","variant":2,"id":"E06Q68"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"Select the insurer with the highest commission.\" Which answer most accurately corrects the misunderstanding?","options":["Select the insurer with the highest commission","Predict the exact day of death","Estimate the survivor's financial obligations and resources to choose an appropriate coverage amount","Guarantee future interest rates"],"answer":2,"explanation":"Needs analysis considers debts, income replacement, dependents, education, and existing assets.","conceptId":"C165","variant":2,"id":"E06Q69"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"A separate full master policy issued to every worker.\" Which answer most accurately corrects the misunderstanding?","options":["The contract issued to the group policyholder, often an employer","A separate full master policy issued to every worker","A bank deposit statement","An individual auto coverage contract"],"answer":0,"explanation":"The group sponsor generally receives the master policy and insured members receive certificates.","conceptId":"C177","variant":2,"id":"E06Q70"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"Only after-tax funds that can never be deducted.\" Which of the following would be the most accurate response?","options":["Only life insurance death claims","Only after-tax funds that can never be deducted","Money in a tax-favored retirement plan or IRA","Only insurer dividends"],"answer":2,"explanation":"Qualified annuities are held within qualified retirement arrangements and follow their tax rules.","conceptId":"C098","variant":3,"id":"E06Q71"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"Correcting a typographical mistake.\" Select the statement that should replace this inaccurate advice.","options":["Using values in an existing policy to fund another policy primarily to generate new compensation without consumer benefit","Adjusting a beneficiary address","Updating an insured's phone number","Correcting a typographical mistake"],"answer":0,"explanation":"Churning can disadvantage consumers with new costs, surrender charges, or lost benefits.","conceptId":"C133","variant":4,"id":"E06Q72"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"To replace the insurer's financial statements.\" Select the statement that should replace this inaccurate advice.","options":["To require the beneficiary to pass a driving test","To replace the insurer's financial statements","To evaluate whether the insurer will restore lapsed coverage under the contract terms","To increase the death benefit without cost"],"answer":2,"explanation":"Reinstatement can require satisfactory evidence of insurability and overdue amounts.","conceptId":"C127","variant":4,"id":"E06Q73"},{"category":"Term & Whole Life","stem":"A first-to-die joint life policy generally pays when?","options":["The policy reaches a stated cash value","The first insured in the covered pair dies","The policyowner retires","Both insureds have died"],"answer":1,"explanation":"First-to-die coverage protects against the first death among insureds.","conceptId":"C049","variant":1,"id":"E06Q74"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. A trainee gives the following mistaken explanation: \"It always permits free instant withdrawals without charges.\" Which answer most accurately corrects the misunderstanding?","options":["Withdrawals may face surrender charges, taxes, or limited liquidity","It always permits free instant withdrawals without charges","It cannot earn any interest","It is protected by FDIC deposit insurance as a bank checking account"],"answer":0,"explanation":"Annuity liquidity is contractual and can carry costs or taxes, making emergency access uncertain.","conceptId":"C103","variant":2,"id":"E06Q75"}]},{"title":"Exam 7","questions":[{"category":"Provisions & Riders","stem":"How does a misstatement-of-age provision typically operate?","options":["The policy is automatically void for every age error","Benefits or premiums are adjusted to reflect the correct age","The producer pays the difference personally","The policy converts to disability insurance"],"answer":1,"explanation":"A wrong age typically leads to an actuarial adjustment rather than automatically voiding the contract.","conceptId":"C056","variant":1,"id":"E07Q01"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"It guarantees the stock will appreciate.\" Which of the following would be the most accurate response?","options":["The state must purchase all shares automatically","It guarantees the stock will appreciate","Each owner can insure other owners and use proceeds to buy a deceased owner's interest","It substitutes for a written agreement"],"answer":2,"explanation":"Cross-purchase plans have owners buy interests directly; entity-redemption plans differ.","conceptId":"C184","variant":3,"id":"E07Q02"},{"category":"Term & Whole Life","stem":"Which term policy feature allows continuation without proof of insurability?","options":["Settlement option","Assignment","Insuring clause","Renewability"],"answer":3,"explanation":"A renewable term feature permits renewal for another term without a new medical examination, usually at higher age-based rates.","conceptId":"C027","variant":1,"id":"E07Q03"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"Proof of the beneficiary's salary only.\" Which answer most accurately corrects the misunderstanding?","options":["Proof of the beneficiary's salary only","A new application for the deceased","A property inspection only","Proof of death plus the insurer's claim forms and supporting records as needed"],"answer":3,"explanation":"A death certificate and claimant information are common components of a death claim.","conceptId":"C122","variant":2,"id":"E07Q04"},{"category":"Fundamentals","stem":"What is the face amount of a life policy?","options":["The policy's guaranteed loan rate","The stated death benefit before adjustments under policy terms","The annual producer commission","The sum of all premiums already paid"],"answer":1,"explanation":"Face amount is the amount of coverage shown on the policy; loans or riders may adjust proceeds.","conceptId":"C017","variant":1,"id":"E07Q05"},{"category":"Provisions & Riders","stem":"What is a revocable beneficiary?","options":["A beneficiary the owner generally can change without that beneficiary's permission","A beneficiary who owns the insurer","A beneficiary who cannot receive money","A beneficiary who is always paid first during the insured's life"],"answer":0,"explanation":"Revocable beneficiary designations can normally be changed by the policyowner.","conceptId":"C058","variant":1,"id":"E07Q06"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Whole life.\" Which answer most accurately corrects the misunderstanding?","options":["Level term life","Traditional endowment","Variable whole life","Whole life"],"answer":0,"explanation":"Term insurance generally provides a death benefit during its term without savings value.","conceptId":"C025","variant":2,"id":"E07Q07"},{"category":"Business & Tax","stem":"Under a human life value approach, what is being estimated?","options":["The replacement cost of the insured's house only","The price of the producer's license","Economic value of the insured's future earnings available to dependents","The insurer's stock market capitalization"],"answer":2,"explanation":"Human life value estimates the present value of expected future income contributions.","conceptId":"C166","variant":1,"id":"E07Q08"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"Only interest is payable.\" Which of the following would be the most accurate response?","options":["A single immediate payment only","Payments over a selected number of years","Payments until age 120 no matter what","Only interest is payable"],"answer":1,"explanation":"A fixed period establishes duration; payment size depends on proceeds and contract assumptions.","conceptId":"C080","variant":3,"id":"E07Q09"},{"category":"Annuities & Retirement","stem":"Which annuity commonly invests through separate-account options whose values fluctuate?","options":["Fixed immediate annuity without investment choice","Variable annuity","Traditional fixed annuity","Straight term insurance"],"answer":1,"explanation":"Variable annuities expose account values to underlying investment performance.","conceptId":"C087","variant":1,"id":"E07Q10"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Reduced paid-up insurance.\" Which answer most accurately corrects the misunderstanding?","options":["Extended term insurance","Automatic premium loan","Reduced paid-up insurance","Dividend accumulation"],"answer":0,"explanation":"Extended term preserves a face amount for a limited duration based on net cash value.","conceptId":"C066","variant":2,"id":"E07Q11"},{"category":"Ethics & CA Law","stem":"What is the principal concern with churning?","options":["Updating an insured's phone number","Correcting a typographical mistake","Adjusting a beneficiary address","Using values in an existing policy to fund another policy primarily to generate new compensation without consumer benefit"],"answer":3,"explanation":"Churning can disadvantage consumers with new costs, surrender charges, or lost benefits.","conceptId":"C133","variant":1,"id":"E07Q12"},{"category":"Annuities & Retirement","stem":"What is a deferred annuity?","options":["A whole life policy dividend","An annuity that must pay tomorrow","A rider for accidental death","An annuity with an accumulation period before income payments begin"],"answer":3,"explanation":"Deferred annuities allow assets to accumulate before annuitization or withdrawals.","conceptId":"C085","variant":1,"id":"E07Q13"},{"category":"Fundamentals","stem":"Which arrangement best illustrates risk pooling?","options":["The insurer ignores probability","Many policyowners pay premiums to fund claims experienced by a smaller number","Every applicant deposits the full death benefit upfront","Every insured is promised identical lifespan"],"answer":1,"explanation":"Pooling spreads unpredictable individual loss across a broad group.","conceptId":"C023","variant":1,"id":"E07Q14"},{"category":"Fundamentals","stem":"Which risk is generally insurable?","options":["Pure risk involving possible loss but no opportunity for gain","A business venture seeking profit","A speculative bet on stock prices","A casino wager"],"answer":0,"explanation":"Pure risks involve loss or no loss, while speculative risks include a possibility of gain.","conceptId":"C007","variant":1,"id":"E07Q15"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"The producer decides the benefit after death.\" Which of the following would be the most accurate response?","options":["Unequal values may be exchanged depending on an uncertain event","Both parties exchange equal amounts on the issue date","There is no uncertainty about when the claim occurs","The producer decides the benefit after death"],"answer":0,"explanation":"Premiums paid may be much lower or higher than the death benefit because timing of death is uncertain.","conceptId":"C004","variant":3,"id":"E07Q16"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Ignore policy ownership.\" Select the statement that should replace this inaccurate advice.","options":["Explain that tax treatment varies by policy, ownership, and circumstances and avoid absolute claims","Say only beneficiaries ever owe income tax","Ignore policy ownership","Promise that all policies have no taxes of any kind"],"answer":0,"explanation":"Death benefits are generally income-tax-free to beneficiaries but estate, transfer, and other rules can apply.","conceptId":"C150","variant":4,"id":"E07Q17"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"A policy dividend distribution.\" Select the statement that should replace this inaccurate advice.","options":["A specified circumstance or risk the contract does not cover","An additional guaranteed benefit","A premium due date","A policy dividend distribution"],"answer":0,"explanation":"Exclusions describe limits on the insurer's coverage obligation.","conceptId":"C121","variant":4,"id":"E07Q18"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"No cost of insurance charges.\" Which of the following would be the most accurate response?","options":["A guaranteed constant investment return in all cases","No lapse risk ever","No cost of insurance charges","Flexible premium payments and adjustable death-benefit options subject to policy limits"],"answer":3,"explanation":"Universal life separates cash value accumulation from insurance charges and permits specified flexibility.","conceptId":"C035","variant":3,"id":"E07Q19"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Invent an explanation to close the sale.\" Which answer most accurately corrects the misunderstanding?","options":["Invent an explanation to close the sale","Assure the customer all risks are covered","Confirm its meaning from the insurer's policy materials before making a representation","Ignore the exclusion as minor"],"answer":2,"explanation":"Competence requires knowing policy limits and avoiding unsupported statements.","conceptId":"C144","variant":2,"id":"E07Q20"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"Naming a beneficiary.\" Which of the following would be the most accurate response?","options":["Surrendering a life policy for a check","Converting annuity value into a series of income payments under a payout option","Adding an accidental death rider","Naming a beneficiary"],"answer":1,"explanation":"Annuitization starts a payout structure often based on life expectancy, rate, and options.","conceptId":"C088","variant":3,"id":"E07Q21"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"$125,000.\" Which of the following would be the most accurate response?","options":["$100,000","$125,000","$150,000","$250,000"],"answer":2,"explanation":"60% of $250,000 is $150,000.","conceptId":"C173","variant":3,"id":"E07Q22"},{"category":"Term & Whole Life","stem":"Which coverage combines flexible premiums with investment subaccounts?","options":["Variable universal life","Traditional whole life only","Fixed term life","Credit life only"],"answer":0,"explanation":"Variable universal life combines UL flexibility and market-linked separate-account investments.","conceptId":"C038","variant":1,"id":"E07Q23"},{"category":"Underwriting & Claims","stem":"Which applicant statement would most likely be material to life underwriting?","options":["Preferred shirt color","A history of serious heart disease","Favorite television program","The insured's favorite holiday"],"answer":1,"explanation":"Serious medical conditions commonly affect expected mortality and insurer decisions.","conceptId":"C112","variant":1,"id":"E07Q24"},{"category":"Ethics & CA Law","stem":"Why should an agent document a customer's objectives and replacement discussion?","options":["To demonstrate the basis for a suitable recommendation and preserve accurate records","To substitute for the applicant's signature","To guarantee investment performance","To avoid providing disclosures"],"answer":0,"explanation":"Documenting needs, costs, and decisions helps support compliant recommendations.","conceptId":"C146","variant":1,"id":"E07Q25"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Alter the physician's records.\" Which of the following would be the most accurate response?","options":["Explain that answers must be truthful and submit complete information","Promise the condition cannot be discovered","Alter the physician's records","Omit it because the client requested it"],"answer":0,"explanation":"Concealing material facts can be fraud and threaten coverage.","conceptId":"C140","variant":3,"id":"E07Q26"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"$500,000.\" Which answer most accurately corrects the misunderstanding?","options":["$542,000","$40,000","$458,000","$500,000"],"answer":2,"explanation":"Net death proceeds equal $500,000 minus $40,000 principal and $2,000 interest = $458,000.","conceptId":"C171","variant":2,"id":"E07Q27"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. The proposed advice is: \"It replaces all application signatures.\" Select the statement that should replace this inaccurate advice.","options":["The state requires the applicant to own a car","It replaces all application signatures","It verifies the beneficiary's occupation","Driving history can indicate mortality-related risk"],"answer":3,"explanation":"Serious violations or risky driving can be relevant to life underwriting.","conceptId":"C124","variant":4,"id":"E07Q28"},{"category":"Ethics & CA Law","stem":"What is an unfair discrimination concern in life insurance?","options":["Using relevant mortality experience","Charging different premiums for justified risk classes","Following filed actuarial rules","Treating people with the same risk classification differently without a lawful underwriting basis"],"answer":3,"explanation":"Risk distinctions must have a lawful actuarial or underwriting justification; unfair discrimination is prohibited.","conceptId":"C137","variant":1,"id":"E07Q29"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Lump-sum option.\" Which answer most accurately corrects the misunderstanding?","options":["Fixed-period option","Interest-only option","Lump-sum option","Life income option"],"answer":3,"explanation":"Life income bases periodic payments on a payee's lifetime, often with optional guarantees.","conceptId":"C078","variant":2,"id":"E07Q30"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"The insurance producer personally.\" Which of the following would be the most accurate response?","options":["The state insurance department","The contractowner","The named beneficiary only","The insurance producer personally"],"answer":1,"explanation":"Variable annuity separate-account performance affects contract value, subject to any specific guarantees.","conceptId":"C105","variant":3,"id":"E07Q31"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"The period during an insurer's bankruptcy.\" Which of the following would be the most accurate response?","options":["The period after all payments are finished","The time required to file a death certificate","The period during an insurer's bankruptcy","The period in which money is contributed and grows before systematic payout"],"answer":3,"explanation":"Accumulation precedes payout or annuitization in a deferred contract.","conceptId":"C101","variant":3,"id":"E07Q32"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Only a business card.\" Which answer most accurately corrects the misunderstanding?","options":["Only a business card","A real estate license","An appropriate active insurance license and any required insurer appointment/authorization","A securities license in place of life authority for all policies"],"answer":2,"explanation":"Proper state licensing and insurer authority are essential to lawful solicitation and sale.","conceptId":"C136","variant":2,"id":"E07Q33"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"To guarantee annual returns.\" Which answer most accurately corrects the misunderstanding?","options":["To choose the insurer's chief executive","To eliminate income tax in all cases","To guarantee annual returns","To direct any payable death benefit or remaining contract value under contract terms"],"answer":3,"explanation":"A designation determines who receives amounts payable at death subject to the contract and law.","conceptId":"C099","variant":2,"id":"E07Q34"},{"category":"Ethics & CA Law","stem":"What is a typical purpose of an insurance consumer complaint process?","options":["Guarantee profit on a policy","Replace any contract with free insurance","Allow regulators to investigate potentially unfair or unlawful insurer or agent conduct","Authorize an unlicensed agent"],"answer":2,"explanation":"CDI receives consumer complaints and oversees compliance with insurance rules.","conceptId":"C153","variant":1,"id":"E07Q35"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"A gambler betting on a neighbor's death.\" Which of the following would be the most accurate response?","options":["A casual online follower insuring an influencer","A stranger insuring a celebrity without consent","A business insuring a key employee whose death would cause a financial loss","A gambler betting on a neighbor's death"],"answer":2,"explanation":"Employers may have an insurable interest in key employees subject to applicable rules.","conceptId":"C022","variant":3,"id":"E07Q36"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"A guaranteed benefit for every unrelated person.\" Which of the following would be the most accurate response?","options":["A guarantee all debt is forgiven","A permanent private life policy replacement in every case","A potential existing income source that may reduce some survivor income needs","A guaranteed benefit for every unrelated person"],"answer":2,"explanation":"Survivor benefits are subject to eligibility and may be included when assessing resources.","conceptId":"C183","variant":3,"id":"E07Q37"},{"category":"Provisions & Riders","stem":"What does the entire contract provision generally include?","options":["A beneficiary's unrelated bank statements","An agent's unwritten verbal promises","Any insurer advertisement ever produced","The policy and attached application and endorsements as applicable"],"answer":3,"explanation":"The written contract is assembled from the policy and specified attached documents.","conceptId":"C057","variant":1,"id":"E07Q38"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"To cancel the base policy.\" Which of the following would be the most accurate response?","options":["To buy small amounts of additional fully paid whole life insurance","To pay property taxes only","To buy an unrelated stock ETF directly","To cancel the base policy"],"answer":0,"explanation":"Paid-up additions increase cash value and death benefit without future premiums for the additions.","conceptId":"C044","variant":3,"id":"E07Q39"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"A lifetime immediate annuity.\" Select the statement that should replace this inaccurate advice.","options":["A lifetime immediate annuity","Single-premium whole life in every case","A deferred variable annuity","20-year level term insurance"],"answer":3,"explanation":"Term commonly provides more initial death protection per premium dollar for a temporary need.","conceptId":"C041","variant":4,"id":"E07Q40"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"Eliminating the insurer's claim obligation.\" Select the statement that should replace this inaccurate advice.","options":["Pledging policy value or proceeds as security for a loan","Converting a policy into health insurance","Eliminating the insurer's claim obligation","Making a child the insured automatically"],"answer":0,"explanation":"A lender can receive proceeds up to its secured interest before the remainder goes to beneficiaries.","conceptId":"C063","variant":4,"id":"E07Q41"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"Both parties negotiate every word equally.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer drafts the policy and the applicant usually accepts or rejects its terms","It is automatically renewed every month","Both parties negotiate every word equally","It must be signed by every beneficiary"],"answer":0,"explanation":"Ambiguities in an adhesion contract are generally interpreted against the drafter.","conceptId":"C005","variant":2,"id":"E07Q42"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"To eliminate the need for a trustee.\" Which of the following would be the most accurate response?","options":["To replace state insurance regulation","To manage policy ownership, beneficiary distributions, and possible estate planning objectives","To eliminate the need for a trustee","To guarantee unlimited tax exemption in all cases"],"answer":1,"explanation":"Trust structures can control ownership and distribution, but require legal and tax advice.","conceptId":"C176","variant":3,"id":"E07Q43"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"It insures everyone for exactly the same amount.\" Which of the following would be the most accurate response?","options":["It totals specific financial needs and subtracts available resources","It insures everyone for exactly the same amount","It uses only the insurer's advertising budget","It ignores outstanding debts"],"answer":0,"explanation":"The needs method estimates expenses and obligations, then offsets assets and existing insurance.","conceptId":"C167","variant":3,"id":"E07Q44"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"$495.\" Select the statement that should replace this inaccurate advice.","options":["$5,400","$495","$450","$540"],"answer":3,"explanation":"Annual premium at $45 monthly is 12 × $45 = $540.","conceptId":"C174","variant":4,"id":"E07Q45"},{"category":"Term & Whole Life","stem":"What normally happens at expiration of a nonrenewed term policy?","options":["All premiums are refunded","Its face amount is automatically paid to the owner","It always converts to an annuity","Coverage ends with no maturity cash value"],"answer":3,"explanation":"Term coverage ends unless it is renewed or converted under the policy's options.","conceptId":"C026","variant":1,"id":"E07Q46"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"A zero-cost application.\" Which of the following would be the most accurate response?","options":["A zero-cost application","An annual adjustable premium","Monthly premiums for life","One large premium paid at issue"],"answer":3,"explanation":"A single premium funds the policy upfront; tax treatment may differ for heavily funded policies.","conceptId":"C034","variant":3,"id":"E07Q47"},{"category":"Business & Tax","stem":"What is a group life insurance master policy?","options":["A bank deposit statement","An individual auto coverage contract","The contract issued to the group policyholder, often an employer","A separate full master policy issued to every worker"],"answer":2,"explanation":"The group sponsor generally receives the master policy and insured members receive certificates.","conceptId":"C177","variant":1,"id":"E07Q48"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"A beneficiary election form.\" Select the statement that should replace this inaccurate advice.","options":["A receipt that can provide specified temporary coverage immediately, subject to its terms and limits","A beneficiary election form","A receipt that never creates any coverage","A permanent annuity"],"answer":0,"explanation":"Binding and conditional receipts differ in how temporary protection is triggered.","conceptId":"C114","variant":4,"id":"E07Q49"},{"category":"Provisions & Riders","stem":"What is an automatic premium loan provision designed to do?","options":["Pay dividends to the producer","Increase the face amount every year","Use available cash value as a loan to pay overdue premiums when elected","Guarantee a policy never carries interest"],"answer":2,"explanation":"Automatic premium loans can prevent lapse but create policy debt and interest.","conceptId":"C067","variant":1,"id":"E07Q50"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"The applicant receives a guaranteed dividend.\" Which of the following would be the most accurate response?","options":["No premium will be charged","The applicant is uninsurable","The applicant receives a guaranteed dividend","The applicant meets the insurer's average underwriting guidelines"],"answer":3,"explanation":"Standard risks generally receive standard rates based on the carrier's underwriting rules.","conceptId":"C013","variant":3,"id":"E07Q51"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. Someone insists: \"To guarantee every application is accepted.\" Which of the following would be the most accurate response?","options":["To handle only property claims","To evaluate applicants and decide whether and on what terms coverage will be offered","To determine who inherits the insured's estate","To guarantee every application is accepted"],"answer":1,"explanation":"Underwriting evaluates risk characteristics and assigns a classification or decision.","conceptId":"C107","variant":3,"id":"E07Q52"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Assignment.\" Which answer most accurately corrects the misunderstanding?","options":["Reinstatement","Entire contract","Assignment","Free look only"],"answer":0,"explanation":"Reinstatement generally requires overdue payments and evidence of insurability as specified.","conceptId":"C054","variant":2,"id":"E07Q53"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"A 50% flat surcharge.\" Select the statement that should replace this inaccurate advice.","options":["No potential additional tax","25% mandatory federal fee","10% additional tax","A 50% flat surcharge"],"answer":2,"explanation":"An early distribution can trigger an additional 10% federal tax on taxable amounts, subject to exceptions.","conceptId":"C096","variant":4,"id":"E07Q54"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Quote an invented credit rating.\" Which of the following would be the most accurate response?","options":["Promise the insurer can never fail","Quote an invented credit rating","Use current credible financial information and avoid guarantees beyond policy terms","Claim CDI guarantees all benefits in full"],"answer":2,"explanation":"Financial ratings are opinions, and policy guarantees depend on insurer claims-paying ability.","conceptId":"C152","variant":3,"id":"E07Q55"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"Both always pay identical amounts at death.\" Which answer most accurately corrects the misunderstanding?","options":["Both are property insurance","Both always pay identical amounts at death","Term life addresses premature-death risk; an annuity can address long-life income risk","Neither is a contract"],"answer":2,"explanation":"Life coverage and annuities address different financial risks.","conceptId":"C185","variant":2,"id":"E07Q56"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"A policy that cannot build cash value.\" Which of the following would be the most accurate response?","options":["Permanent life insurance with premiums scheduled for fewer years than coverage lasts","Term coverage that pays only a partial death benefit","Coverage limited to exactly one year","A policy that cannot build cash value"],"answer":0,"explanation":"A 20-pay whole life policy may be fully paid after 20 years but continue for life.","conceptId":"C033","variant":3,"id":"E07Q57"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"A mandatory class for every applicant.\" Which answer most accurately corrects the misunderstanding?","options":["A mandatory class for every applicant","A favorable class generally offered a lower premium than standard","A policy that never lapses","A beneficiary with first priority"],"answer":1,"explanation":"Preferred applicants meet more favorable underwriting criteria.","conceptId":"C015","variant":2,"id":"E07Q58"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. A trainee gives the following mistaken explanation: \"Claims are paid whether or not coverage exists.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer's obligation depends on contractual conditions being satisfied","Every claim is automatically disputed","The applicant sets premium after a claim","Claims are paid whether or not coverage exists"],"answer":0,"explanation":"Payment of benefits depends on conditions such as policy being in force and proof of covered death.","conceptId":"C006","variant":2,"id":"E07Q59"},{"category":"Business & Tax","stem":"What is key-person life insurance designed to protect?","options":["A business from financial loss caused by death of an important employee or owner","The company's group health deductible","Every shareholder from stock-price declines","An employee's car against theft"],"answer":0,"explanation":"Key-person insurance can provide liquidity while the company recruits or replaces key talent.","conceptId":"C157","variant":1,"id":"E07Q60"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"To extend a policy after its maturity without conditions.\" Select the statement that should replace this inaccurate advice.","options":["To keep coverage in force for a specified time after a premium is due","To extend a policy after its maturity without conditions","To allow a beneficiary change after claim payment","To waive every future premium"],"answer":0,"explanation":"A grace period provides a window to pay overdue premiums while coverage generally continues.","conceptId":"C053","variant":4,"id":"E07Q61"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"Policy replacement.\" Select the statement that should replace this inaccurate advice.","options":["Cash surrender","Extended term insurance","Policy replacement","Reduced paid-up insurance"],"answer":3,"explanation":"Reduced paid-up uses available value to buy a smaller fully paid permanent policy.","conceptId":"C065","variant":4,"id":"E07Q62"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Lend client premiums without permission.\" Select the statement that should replace this inaccurate advice.","options":["Lend client premiums without permission","Keep premiums regardless of policy status","Handle entrusted premiums honestly and remit/account for them as required","Use premiums as personal funds temporarily"],"answer":2,"explanation":"Producers must properly safeguard and account for money received in their insurance capacity.","conceptId":"C138","variant":4,"id":"E07Q63"},{"category":"Term & Whole Life","stem":"A 35-year-old buys a 20-year level-term policy, keeping coverage in force throughout. At what age is the level term scheduled to end?","options":["65","45","55","75"],"answer":2,"explanation":"35 + 20 = age 55; any renewability or conversion rights depend on the policy.","conceptId":"X005","variant":1,"id":"E07Q64"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"The beneficiary's preparation of a tax return.\" Which answer most accurately corrects the misunderstanding?","options":["The producer's initial collection and observation of risk information","A state examination proctor's review","The beneficiary's preparation of a tax return","The insurer's investment selection"],"answer":0,"explanation":"Producers help collect complete applications and identify relevant underwriting facts.","conceptId":"C116","variant":2,"id":"E07Q65"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"All death benefits are excluded.\" Which answer most accurately corrects the misunderstanding?","options":["All death benefits are excluded","Policyowners are not entitled to participate in insurer surplus through policy dividends","It must be term insurance","It has no beneficiaries"],"answer":1,"explanation":"Nonparticipating policies do not pay participating policy dividends.","conceptId":"C043","variant":2,"id":"E07Q66"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"To cover a homeowner's liability.\" Select the statement that should replace this inaccurate advice.","options":["To cover a homeowner's liability","To provide a stream of income, often for retirement","To insure a car","To pay a death benefit only for accidental death"],"answer":1,"explanation":"Annuities are contracts for accumulation and/or distribution of income.","conceptId":"C083","variant":4,"id":"E07Q67"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"Higher income replacement needs.\" Select the statement that should replace this inaccurate advice.","options":["Higher income replacement needs","More liquid savings available to survivors","More dependent children","A larger outstanding mortgage"],"answer":1,"explanation":"Existing assets can offset some future survivor needs.","conceptId":"C175","variant":4,"id":"E07Q68"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"To pay a benefit only after policy surrender.\" Select the statement that should replace this inaccurate advice.","options":["To eliminate all underwriting","To allow an eligible insured to receive part of the death benefit while alive under qualifying conditions","To pay a benefit only after policy surrender","To pay double benefits after every accidental injury"],"answer":1,"explanation":"Accelerated benefits advance proceeds for defined qualifying illness or other triggers and can reduce the later death benefit.","conceptId":"C072","variant":4,"id":"E07Q69"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"A beneficiary who is a minor.\" Select the statement that should replace this inaccurate advice.","options":["An applicant who always gets preferred rates","An applicant with higher-than-normal expected mortality who may be charged extra premium","A beneficiary who is a minor","A person with no insurable interest"],"answer":1,"explanation":"Higher risk can result in rating, exclusions if lawful, postponement, or decline.","conceptId":"C014","variant":4,"id":"E07Q70"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"To set the beneficiary's age.\" Which of the following would be the most accurate response?","options":["To calculate the agent's commission","To set the beneficiary's age","To determine a medical deductible","To determine the portion of each qualifying payment treated as return of investment versus taxable income"],"answer":3,"explanation":"The exclusion ratio allocates annuity payments between basis recovery and taxable income, when applicable.","conceptId":"C097","variant":3,"id":"E07Q71"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"A one-year level term policy.\" Which answer most accurately corrects the misunderstanding?","options":["A lifetime income annuity","Mortgage decreasing term","Credit life insurance","A one-year level term policy"],"answer":0,"explanation":"Lifetime annuity income can mitigate the risk of outliving retirement resources.","conceptId":"C104","variant":2,"id":"E07Q72"},{"category":"Underwriting & Claims","stem":"What does underwriting classification 'declined' mean?","options":["The policy is automatically approved","The insurer will not issue coverage under the proposed terms","The insurer guarantees a low rate","The applicant is the primary beneficiary"],"answer":1,"explanation":"A decline means the application was not accepted under the insurer's underwriting criteria.","conceptId":"C126","variant":1,"id":"E07Q73"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"To require the beneficiary to pass a driving test.\" Which answer most accurately corrects the misunderstanding?","options":["To replace the insurer's financial statements","To evaluate whether the insurer will restore lapsed coverage under the contract terms","To increase the death benefit without cost","To require the beneficiary to pass a driving test"],"answer":1,"explanation":"Reinstatement can require satisfactory evidence of insurability and overdue amounts.","conceptId":"C127","variant":2,"id":"E07Q74"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"To eliminate all private insurers.\" Which of the following would be the most accurate response?","options":["To eliminate all private insurers","To guarantee everyone a job as an agent","To replace insurance contracts with bank loans","To ensure only qualified and authorized persons transact regulated insurance"],"answer":3,"explanation":"Licensing protects consumers through qualification and regulatory oversight.","conceptId":"C145","variant":3,"id":"E07Q75"}]},{"title":"Exam 8","questions":[{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Department of Motor Vehicles alone.\" Select the statement that should replace this inaccurate advice.","options":["Local city council alone","Department of Motor Vehicles alone","Federal Reserve alone","California Department of Insurance under the Insurance Commissioner"],"answer":3,"explanation":"CDI oversees insurance licensing and regulation in California.","conceptId":"C135","variant":4,"id":"E08Q01"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Assignment.\" Which answer most accurately corrects the misunderstanding?","options":["Assignment","Settlement option","Renewability","Insuring clause"],"answer":2,"explanation":"A renewable term feature permits renewal for another term without a new medical examination, usually at higher age-based rates.","conceptId":"C027","variant":2,"id":"E08Q02"},{"category":"Term & Whole Life","stem":"What is the main feature of universal life insurance?","options":["Flexible premium payments and adjustable death-benefit options subject to policy limits","No cost of insurance charges","A guaranteed constant investment return in all cases","No lapse risk ever"],"answer":0,"explanation":"Universal life separates cash value accumulation from insurance charges and permits specified flexibility.","conceptId":"C035","variant":1,"id":"E08Q03"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"Indemnity.\" Which answer most accurately corrects the misunderstanding?","options":["Subrogation","Insurable interest","Contribution","Indemnity"],"answer":1,"explanation":"Insurable interest discourages wagering on human life; it generally must exist when a life policy is purchased.","conceptId":"C002","variant":2,"id":"E08Q04"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. Someone insists: \"A temporary grace period.\" Which of the following would be the most accurate response?","options":["A temporary grace period","A short-term loan against cash value only","A term insurance conversion only","A transfer of all ownership rights in a policy"],"answer":3,"explanation":"Absolute assignment is broader than collateral assignment.","conceptId":"C064","variant":3,"id":"E08Q05"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"The beneficiary automatically owns the policy.\" Select the statement that should replace this inaccurate advice.","options":["All medical questions can be omitted","The beneficiary automatically owns the policy","The applicant attests to the statements and authorizations provided","The insurer guarantees policy issuance"],"answer":2,"explanation":"Signing confirms information and consents, not a promise that underwriting will approve coverage.","conceptId":"C024","variant":4,"id":"E08Q06"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"Every withdrawal is a capital gain.\" Select the statement that should replace this inaccurate advice.","options":["Principal is always withdrawn first","Every withdrawal is a capital gain","Earnings are generally withdrawn first for tax purposes","Withdrawals are never taxable"],"answer":2,"explanation":"Nonqualified annuity distributions commonly follow last-in-first-out ordering before annuitization.","conceptId":"C095","variant":4,"id":"E08Q07"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"A deferred variable annuity.\" Which of the following would be the most accurate response?","options":["A lifetime immediate annuity","Single-premium whole life in every case","20-year level term insurance","A deferred variable annuity"],"answer":2,"explanation":"Term commonly provides more initial death protection per premium dollar for a temporary need.","conceptId":"C041","variant":3,"id":"E08Q08"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"A permanent annuity.\" Which of the following would be the most accurate response?","options":["A permanent annuity","A receipt that can provide specified temporary coverage immediately, subject to its terms and limits","A beneficiary election form","A receipt that never creates any coverage"],"answer":1,"explanation":"Binding and conditional receipts differ in how temporary protection is triggered.","conceptId":"C114","variant":3,"id":"E08Q09"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"Equity mutual fund.\" Which of the following would be the most accurate response?","options":["Variable annuity","Fixed annuity","Exchange traded fund","Equity mutual fund"],"answer":1,"explanation":"Fixed annuities generally credit contractually specified or declared interest with applicable guarantees.","conceptId":"C086","variant":3,"id":"E08Q10"},{"category":"Ethics & CA Law","stem":"A candidate practices 75 questions in 105 minutes. What is the average time available per question, assuming equal allocation?","options":["84 seconds","105 seconds","60 seconds","140 seconds"],"answer":0,"explanation":"105 × 60 / 75 = 84 seconds per question. The official time limit is a reference; this app is untimed.","conceptId":"X010","variant":1,"id":"E08Q11"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. The proposed advice is: \"It is automatically renewed every month.\" Select the statement that should replace this inaccurate advice.","options":["It must be signed by every beneficiary","It is automatically renewed every month","The insurer drafts the policy and the applicant usually accepts or rejects its terms","Both parties negotiate every word equally"],"answer":2,"explanation":"Ambiguities in an adhesion contract are generally interpreted against the drafter.","conceptId":"C005","variant":4,"id":"E08Q12"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"Joint and survivor income.\" Which of the following would be the most accurate response?","options":["Life with cash refund","Joint and survivor income","Life with 20-year period certain","Straight life income"],"answer":3,"explanation":"Straight life typically offers higher payments because it has no survivor or refund guarantee.","conceptId":"C090","variant":3,"id":"E08Q13"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"Variable whole life.\" Which of the following would be the most accurate response?","options":["Whole life","Variable whole life","Level term life","Traditional endowment"],"answer":2,"explanation":"Term insurance generally provides a death benefit during its term without savings value.","conceptId":"C025","variant":3,"id":"E08Q14"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"The right of the owner to change premium mode.\" Which answer most accurately corrects the misunderstanding?","options":["A beneficiary's right to make a claim","The insurer's ability to contest the policy after the specified contestable period, subject to exceptions","The insurer's right to pay claims promptly","The right of the owner to change premium mode"],"answer":1,"explanation":"After the contractual/statutory period, an insurer's grounds to contest validity are limited, with exceptions such as nonpayment.","conceptId":"C055","variant":2,"id":"E08Q15"},{"category":"Provisions & Riders","stem":"Which nonforfeiture option keeps a reduced amount of permanent coverage in force without further premiums?","options":["Policy replacement","Cash surrender","Extended term insurance","Reduced paid-up insurance"],"answer":3,"explanation":"Reduced paid-up uses available value to buy a smaller fully paid permanent policy.","conceptId":"C065","variant":1,"id":"E08Q16"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"Its face amount is automatically paid to the owner.\" Which answer most accurately corrects the misunderstanding?","options":["It always converts to an annuity","Its face amount is automatically paid to the owner","Coverage ends with no maturity cash value","All premiums are refunded"],"answer":2,"explanation":"Term coverage ends unless it is renewed or converted under the policy's options.","conceptId":"C026","variant":2,"id":"E08Q17"},{"category":"Term & Whole Life","stem":"Under level-premium term life insurance, what remains level for the guaranteed term?","options":["The insurer's claim expenses","The investment return","The insured's attained age","The scheduled premium"],"answer":3,"explanation":"Level-premium term has stable premiums for a stated guaranteed period.","conceptId":"C029","variant":1,"id":"E08Q18"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"$450.\" Which answer most accurately corrects the misunderstanding?","options":["$495","$540","$450","$5,400"],"answer":1,"explanation":"Annual premium at $45 monthly is 12 × $45 = $540.","conceptId":"C174","variant":2,"id":"E08Q19"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"No potential additional tax.\" Which of the following would be the most accurate response?","options":["A 50% flat surcharge","No potential additional tax","10% additional tax","25% mandatory federal fee"],"answer":2,"explanation":"An early distribution can trigger an additional 10% federal tax on taxable amounts, subject to exceptions.","conceptId":"C096","variant":3,"id":"E08Q20"},{"category":"Provisions & Riders","stem":"What is the effect of an outstanding policy loan on death proceeds?","options":["The death benefit always doubles","The insured's heirs automatically owe the full face amount","The loan is paid by the state","The balance and accrued interest generally reduce benefits paid"],"answer":3,"explanation":"Policy loan debt generally offsets death proceeds and may create lapse or tax risks.","conceptId":"C068","variant":1,"id":"E08Q21"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"Setting state insurance laws.\" Select the statement that should replace this inaccurate advice.","options":["Collecting health measurements and specimens for underwriting","Making beneficiary changes","Paying the policy's first dividend","Setting state insurance laws"],"answer":0,"explanation":"Paramedical exams assist an insurer's assessment of mortality risk.","conceptId":"C111","variant":4,"id":"E08Q22"},{"category":"Provisions & Riders","stem":"Which event generally triggers a life insurance death claim?","options":["Any beneficiary birthday","The insured's death while qualifying coverage is in force","The policyowner's retirement","An agent changing employers"],"answer":1,"explanation":"Death benefits arise on covered death and appropriate claim documentation.","conceptId":"C082","variant":1,"id":"E08Q23"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"A tax imposed by a producer.\" Which answer most accurately corrects the misunderstanding?","options":["An automatic annual death benefit","A tax imposed by a producer","A contractual charge that may apply to withdrawals or surrender during specified years","A premium paid to a reinsurer"],"answer":2,"explanation":"Surrender schedules discourage early withdrawal and may decline over time.","conceptId":"C093","variant":2,"id":"E08Q24"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"The period after all payments are finished.\" Which answer most accurately corrects the misunderstanding?","options":["The period in which money is contributed and grows before systematic payout","The period after all payments are finished","The time required to file a death certificate","The period during an insurer's bankruptcy"],"answer":0,"explanation":"Accumulation precedes payout or annuitization in a deferred contract.","conceptId":"C101","variant":2,"id":"E08Q25"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Occupation never matters.\" Which answer most accurately corrects the misunderstanding?","options":["Occupation never matters","Some occupations carry greater mortality hazards","A job title determines the insurer's solvency","Only beneficiaries' jobs matter"],"answer":1,"explanation":"Occupational hazards may influence risk assessment and rates.","conceptId":"C117","variant":2,"id":"E08Q26"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"Guarantee a policy never carries interest.\" Which answer most accurately corrects the misunderstanding?","options":["Increase the face amount every year","Pay dividends to the producer","Use available cash value as a loan to pay overdue premiums when elected","Guarantee a policy never carries interest"],"answer":2,"explanation":"Automatic premium loans can prevent lapse but create policy debt and interest.","conceptId":"C067","variant":2,"id":"E08Q27"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"To guarantee its stock appreciates.\" Which answer most accurately corrects the misunderstanding?","options":["To set a consumer's beneficiary selection","To guarantee its stock appreciates","To appoint the policyholder's attorney","To assess compliance and financial or market conduct condition"],"answer":3,"explanation":"Insurance departments supervise insurer solvency and market conduct.","conceptId":"C143","variant":2,"id":"E08Q28"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"No ethics study at all.\" Which of the following would be the most accurate response?","options":["100 hours of federal tax law","50 hours of auto insurance repair","No ethics study at all","12 hours of study on ethics and the California Insurance Code"],"answer":3,"explanation":"CDI requires the specified 12 hours of ethics and Insurance Code study for affected applicants.","conceptId":"C156","variant":3,"id":"E08Q29"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"To guarantee investment performance.\" Which of the following would be the most accurate response?","options":["To avoid providing disclosures","To demonstrate the basis for a suitable recommendation and preserve accurate records","To guarantee investment performance","To substitute for the applicant's signature"],"answer":1,"explanation":"Documenting needs, costs, and decisions helps support compliant recommendations.","conceptId":"C146","variant":3,"id":"E08Q30"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"The policyowner retires.\" Which of the following would be the most accurate response?","options":["The policyowner retires","Both insureds have died","The policy reaches a stated cash value","The first insured in the covered pair dies"],"answer":3,"explanation":"First-to-die coverage protects against the first death among insureds.","conceptId":"C049","variant":3,"id":"E08Q31"},{"category":"Annuities & Retirement","stem":"What does a joint-and-survivor annuity aim to provide?","options":["Income while either of two covered annuitants remains alive, as specified","A single lump-sum payment only","Life insurance payable at the first death only","No income after the first retirement"],"answer":0,"explanation":"Joint-and-survivor options continue all or part of income to a survivor based on the payout selection.","conceptId":"C092","variant":1,"id":"E08Q32"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"A beneficiary's medical deductible.\" Select the statement that should replace this inaccurate advice.","options":["A death benefit that may be restricted during an initial period under policy terms","A beneficiary's medical deductible","Coverage that doubles every month","A guaranteed annual premium refund"],"answer":0,"explanation":"Some simplified-issue products limit early nonaccidental death benefits; review policy details.","conceptId":"C047","variant":4,"id":"E08Q33"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"It ignores outstanding debts.\" Which answer most accurately corrects the misunderstanding?","options":["It ignores outstanding debts","It insures everyone for exactly the same amount","It totals specific financial needs and subtracts available resources","It uses only the insurer's advertising budget"],"answer":2,"explanation":"The needs method estimates expenses and obligations, then offsets assets and existing insurance.","conceptId":"C167","variant":2,"id":"E08Q34"},{"category":"Ethics & CA Law","stem":"A California life agent generally must hold what before transacting life insurance?","options":["Only a business card","A real estate license","A securities license in place of life authority for all policies","An appropriate active insurance license and any required insurer appointment/authorization"],"answer":3,"explanation":"Proper state licensing and insurer authority are essential to lawful solicitation and sale.","conceptId":"C136","variant":1,"id":"E08Q35"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"A permanent premium waiver from the start.\" Which answer most accurately corrects the misunderstanding?","options":["A fluctuating face amount tied to inflation only","A permanent premium waiver from the start","No underwriting under any circumstances","Lower initial scheduled premiums that increase at a stated later point"],"answer":3,"explanation":"Modified premium whole life changes premium levels according to the contract schedule.","conceptId":"C051","variant":2,"id":"E08Q36"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"They are always capital gains.\" Which of the following would be the most accurate response?","options":["They are generally excluded from gross income, with important exceptions","They are always capital gains","They are always taxed as ordinary wages","They are taxable every year before death"],"answer":0,"explanation":"IRC Section 101(a) generally excludes death proceeds from income, subject to exceptions such as transfer-for-value.","conceptId":"C160","variant":3,"id":"E08Q37"},{"category":"Underwriting & Claims","stem":"What does the insurer ordinarily do after receiving a completed life claim?","options":["Pay every applicant a dividend","Transfer ownership to the agent","Begin underwriting an entirely new insured","Verify coverage and claim facts, then determine benefits under policy and law"],"answer":3,"explanation":"Claims adjudication confirms the policy and the claimant's entitlement.","conceptId":"C130","variant":1,"id":"E08Q38"},{"category":"Fundamentals","stem":"What is reinsurance?","options":["An insurer transfers part of its insurance risk to another insurer","An agent renews their license","A beneficiary purchases a policy loan","The applicant changes insurers after death"],"answer":0,"explanation":"Reinsurance lets a ceding company share risk with a reinsurer.","conceptId":"C018","variant":1,"id":"E08Q39"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"A stranger insuring a celebrity without consent.\" Which answer most accurately corrects the misunderstanding?","options":["A stranger insuring a celebrity without consent","A gambler betting on a neighbor's death","A casual online follower insuring an influencer","A business insuring a key employee whose death would cause a financial loss"],"answer":3,"explanation":"Employers may have an insurable interest in key employees subject to applicable rules.","conceptId":"C022","variant":2,"id":"E08Q40"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"Always subject to payroll tax.\" Select the statement that should replace this inaccurate advice.","options":["Always taxed as ordinary income from the first dollar","Always subject to payroll tax","Generally treated as a return of premium rather than taxable income","Always capital gains"],"answer":2,"explanation":"Life policy dividends commonly reduce the owner's cost basis; interest earned on retained dividends is typically taxable.","conceptId":"C161","variant":4,"id":"E08Q41"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"Neither is a contract.\" Select the statement that should replace this inaccurate advice.","options":["Term life addresses premature-death risk; an annuity can address long-life income risk","Both are property insurance","Both always pay identical amounts at death","Neither is a contract"],"answer":0,"explanation":"Life coverage and annuities address different financial risks.","conceptId":"C185","variant":4,"id":"E08Q42"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"An increase in the adult's retirement income.\" Select the statement that should replace this inaccurate advice.","options":["A medical plan for children","Term life coverage on eligible children attached to an adult policy","A cash account only for college tuition","An increase in the adult's retirement income"],"answer":1,"explanation":"Child riders provide limited death coverage on eligible children under the rider terms.","conceptId":"C073","variant":4,"id":"E08Q43"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"A policy that never lapses.\" Which of the following would be the most accurate response?","options":["A beneficiary with first priority","A favorable class generally offered a lower premium than standard","A policy that never lapses","A mandatory class for every applicant"],"answer":1,"explanation":"Preferred applicants meet more favorable underwriting criteria.","conceptId":"C015","variant":3,"id":"E08Q44"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"Hide the old policy values.\" Which of the following would be the most accurate response?","options":["Hide the old policy values","Obtain a signature without explanation","Explain the changes and material risks in understandable terms before proceeding","Tell the client reading is unnecessary"],"answer":2,"explanation":"Informed consent requires understandable, accurate discussion of material changes.","conceptId":"C151","variant":3,"id":"E08Q45"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"An individual auto coverage contract.\" Which of the following would be the most accurate response?","options":["A separate full master policy issued to every worker","An individual auto coverage contract","A bank deposit statement","The contract issued to the group policyholder, often an employer"],"answer":3,"explanation":"The group sponsor generally receives the master policy and insured members receive certificates.","conceptId":"C177","variant":3,"id":"E08Q46"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Entire contract.\" Which of the following would be the most accurate response?","options":["Free look only","Entire contract","Reinstatement","Assignment"],"answer":2,"explanation":"Reinstatement generally requires overdue payments and evidence of insurability as specified.","conceptId":"C054","variant":3,"id":"E08Q47"},{"category":"Underwriting & Claims","stem":"What is the purpose of an insurability requirement when reinstating a policy?","options":["To evaluate whether the insurer will restore lapsed coverage under the contract terms","To require the beneficiary to pass a driving test","To increase the death benefit without cost","To replace the insurer's financial statements"],"answer":0,"explanation":"Reinstatement can require satisfactory evidence of insurability and overdue amounts.","conceptId":"C127","variant":1,"id":"E08Q48"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"To protect against earthquake damage.\" Which of the following would be the most accurate response?","options":["To insure only a mortgage lender","To provide only liability insurance","To protect against earthquake damage","To pay the face amount at a specified maturity date or earlier covered death"],"answer":3,"explanation":"An endowment combines a death benefit with a contractual maturity payment.","conceptId":"C046","variant":3,"id":"E08Q49"},{"category":"Underwriting & Claims","stem":"What does a conditional receipt generally mean?","options":["The application has been approved for all amounts","Coverage is guaranteed regardless of medical findings","The insurer cannot decline coverage","Coverage may begin only if stated conditions are satisfied under the receipt"],"answer":3,"explanation":"Conditional receipts are not unconditional promises; read their effective-date and insurability conditions.","conceptId":"C113","variant":1,"id":"E08Q50"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"$542,000.\" Which of the following would be the most accurate response?","options":["$542,000","$40,000","$500,000","$458,000"],"answer":3,"explanation":"Net death proceeds equal $500,000 minus $40,000 principal and $2,000 interest = $458,000.","conceptId":"C171","variant":3,"id":"E08Q51"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"The insured can rewrite contract terms at will.\" Which of the following would be the most accurate response?","options":["Only the insurer makes a legally enforceable promise to perform if conditions are met","Both parties must pay claims","The insured can rewrite contract terms at will","Both parties promise equal performance"],"answer":0,"explanation":"The policyowner promises no ongoing performance enforceable as a contract; premiums are needed to keep coverage in force.","conceptId":"C003","variant":3,"id":"E08Q52"},{"category":"Business & Tax","stem":"Which is a common advantage of group term life provided through employment?","options":["Coverage can never terminate when employment ends","Cash value is always guaranteed","Coverage may be accessible with simplified enrollment at group rates","Employees always own lifelong portable coverage"],"answer":2,"explanation":"Group term may be convenient but has portability and coverage-limit considerations.","conceptId":"C178","variant":1,"id":"E08Q53"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Interest-only option.\" Which of the following would be the most accurate response?","options":["Fixed-period option","Life income option","Interest-only option","Lump-sum option"],"answer":1,"explanation":"Life income bases periodic payments on a payee's lifetime, often with optional guarantees.","conceptId":"C078","variant":3,"id":"E08Q54"},{"category":"Business & Tax","stem":"What is the purpose of a charitable beneficiary designation?","options":["To cancel all premium charges","To direct eligible policy proceeds to a named charitable organization","To force a policy to become an annuity","To insure a charity's building against fire"],"answer":1,"explanation":"A policy can name a charity as beneficiary subject to policy and tax considerations.","conceptId":"C168","variant":1,"id":"E08Q55"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. Someone insists: \"Automatic premium loan.\" Which of the following would be the most accurate response?","options":["Reduced paid-up insurance","Dividend accumulation","Automatic premium loan","Extended term insurance"],"answer":3,"explanation":"Extended term preserves a face amount for a limited duration based on net cash value.","conceptId":"C066","variant":3,"id":"E08Q56"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"Term coverage that pays only a partial death benefit.\" Select the statement that should replace this inaccurate advice.","options":["Term coverage that pays only a partial death benefit","Coverage limited to exactly one year","A policy that cannot build cash value","Permanent life insurance with premiums scheduled for fewer years than coverage lasts"],"answer":3,"explanation":"A 20-pay whole life policy may be fully paid after 20 years but continue for life.","conceptId":"C033","variant":4,"id":"E08Q57"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. Someone insists: \"A rider for accidental death.\" Which of the following would be the most accurate response?","options":["An annuity with an accumulation period before income payments begin","A rider for accidental death","An annuity that must pay tomorrow","A whole life policy dividend"],"answer":0,"explanation":"Deferred annuities allow assets to accumulate before annuitization or withdrawals.","conceptId":"C085","variant":3,"id":"E08Q58"},{"category":"Provisions & Riders","stem":"What does a fixed-amount settlement option specify?","options":["A selected payment amount until proceeds and interest are exhausted","A lifelong guaranteed payment irrespective of amount","An automatic annual inflation increase","Payments only after the beneficiary dies"],"answer":0,"explanation":"Fixed amount fixes payment size rather than a guaranteed number of payments.","conceptId":"C081","variant":1,"id":"E08Q59"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"Cost of living rider.\" Select the statement that should replace this inaccurate advice.","options":["Accidental death benefit rider","Cost of living rider","Waiver of premium rider","Guaranteed insurability rider"],"answer":2,"explanation":"Waiver riders help keep the policy funded during a covered disability.","conceptId":"C069","variant":4,"id":"E08Q60"},{"category":"Underwriting & Claims","stem":"Why might an insurer request evidence of a proposed insured's finances?","options":["To determine the agent's tax return","To support financial underwriting and justify a large coverage amount","To guarantee a stock price","To transfer ownership automatically"],"answer":1,"explanation":"Financial underwriting evaluates coverage need and potential overinsurance or anti-selection.","conceptId":"C118","variant":1,"id":"E08Q61"},{"category":"Underwriting & Claims","stem":"What is the main purpose of underwriting?","options":["To determine who inherits the insured's estate","To handle only property claims","To guarantee every application is accepted","To evaluate applicants and decide whether and on what terms coverage will be offered"],"answer":3,"explanation":"Underwriting evaluates risk characteristics and assigns a classification or decision.","conceptId":"C107","variant":1,"id":"E08Q62"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"A premium payment frequency.\" Select the statement that should replace this inaccurate advice.","options":["A premium payment frequency","An automatic dividend election","A transfer of specified policy rights to another party","A change in the insured's age"],"answer":2,"explanation":"Assignments transfer ownership rights or create security interests.","conceptId":"C062","variant":4,"id":"E08Q63"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Suggest incorrect answers on an application.\" Select the statement that should replace this inaccurate advice.","options":["Suggest incorrect answers on an application","Hide replacement charges","Promise dividends are guaranteed","Present material benefits, exclusions, costs, and limitations accurately"],"answer":3,"explanation":"Accurate disclosures support informed consumer decisions and avoid misrepresentation.","conceptId":"C134","variant":4,"id":"E08Q64"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Focus only on the new policy's first-year premium.\" Which answer most accurately corrects the misunderstanding?","options":["Compare the existing and proposed contracts, including surrender charges and lost guarantees","Focus only on the new policy's first-year premium","Assume the new contract is always better","Ignore existing beneficiaries"],"answer":0,"explanation":"Replacement analysis should consider costs, timing, exclusions, taxes and lost rights.","conceptId":"C141","variant":2,"id":"E08Q65"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. Someone insists: \"Unlimited free coverage forever.\" Which of the following would be the most accurate response?","options":["An automatic full refund of all employer premiums","Eligible departing members to change group life coverage to an individual policy within specified rules","Conversion from life to car insurance","Unlimited free coverage forever"],"answer":1,"explanation":"Group conversion may preserve some protection without medical underwriting if exercised promptly.","conceptId":"C180","variant":3,"id":"E08Q66"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"Deductible, coinsurance, and copayment.\" Select the statement that should replace this inaccurate advice.","options":["Deductible, coinsurance, and copayment","Taxes, inflation, and stock dividends only","Mortality, interest, and expenses","Marketing, age of producer, and commissions only"],"answer":2,"explanation":"Pricing reflects expected claims, investment earnings and operating costs.","conceptId":"C010","variant":4,"id":"E08Q67"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"An annuity that cannot pay income.\" Which answer most accurately corrects the misunderstanding?","options":["An annuity that only holds stock shares","An annuity that cannot pay income","An annuity that generally begins income payments within about one year of purchase","A term life policy with one premium"],"answer":2,"explanation":"Immediate annuities begin payout relatively soon after the purchase payment.","conceptId":"C084","variant":2,"id":"E08Q68"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"The reinsurer.\" Select the statement that should replace this inaccurate advice.","options":["The policyowner","The reinsurer","The contingent beneficiary","The insured's physician"],"answer":0,"explanation":"The policyowner controls contractual rights such as beneficiary changes when permitted.","conceptId":"C016","variant":4,"id":"E08Q69"},{"category":"Business & Tax","stem":"Which factor usually decreases the additional life coverage needed in a needs analysis?","options":["A larger outstanding mortgage","Higher income replacement needs","More dependent children","More liquid savings available to survivors"],"answer":3,"explanation":"Existing assets can offset some future survivor needs.","conceptId":"C175","variant":1,"id":"E08Q70"},{"category":"Underwriting & Claims","stem":"Why might an insurer order a motor vehicle report for a life applicant?","options":["It verifies the beneficiary's occupation","It replaces all application signatures","The state requires the applicant to own a car","Driving history can indicate mortality-related risk"],"answer":3,"explanation":"Serious violations or risky driving can be relevant to life underwriting.","conceptId":"C124","variant":1,"id":"E08Q71"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"To replace insurance contracts with bank loans.\" Select the statement that should replace this inaccurate advice.","options":["To guarantee everyone a job as an agent","To ensure only qualified and authorized persons transact regulated insurance","To replace insurance contracts with bank loans","To eliminate all private insurers"],"answer":1,"explanation":"Licensing protects consumers through qualification and regulatory oversight.","conceptId":"C145","variant":4,"id":"E08Q72"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. The proposed advice is: \"There is no uncertainty about when the claim occurs.\" Select the statement that should replace this inaccurate advice.","options":["There is no uncertainty about when the claim occurs","Both parties exchange equal amounts on the issue date","The producer decides the benefit after death","Unequal values may be exchanged depending on an uncertain event"],"answer":3,"explanation":"Premiums paid may be much lower or higher than the death benefit because timing of death is uncertain.","conceptId":"C004","variant":4,"id":"E08Q73"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"The replacement cost of the insured's house only.\" Which answer most accurately corrects the misunderstanding?","options":["The price of the producer's license","The replacement cost of the insured's house only","The insurer's stock market capitalization","Economic value of the insured's future earnings available to dependents"],"answer":3,"explanation":"Human life value estimates the present value of expected future income contributions.","conceptId":"C166","variant":2,"id":"E08Q74"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. The proposed advice is: \"Notifying an insurer of an address change.\" Select the statement that should replace this inaccurate advice.","options":["Giving a client a copy of the policy","Using misleading comparisons or representations to induce an improper policy replacement","Explaining legitimate policy differences accurately","Notifying an insurer of an address change"],"answer":1,"explanation":"Twisting involves misrepresentation to persuade a customer to replace coverage.","conceptId":"C131","variant":4,"id":"E08Q75"}]},{"title":"Exam 9","questions":[{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. Someone insists: \"To increase the death benefit without cost.\" Which of the following would be the most accurate response?","options":["To replace the insurer's financial statements","To require the beneficiary to pass a driving test","To evaluate whether the insurer will restore lapsed coverage under the contract terms","To increase the death benefit without cost"],"answer":2,"explanation":"Reinstatement can require satisfactory evidence of insurability and overdue amounts.","conceptId":"C127","variant":3,"id":"E09Q01"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"It substitutes for a written agreement.\" Select the statement that should replace this inaccurate advice.","options":["It guarantees the stock will appreciate","It substitutes for a written agreement","Each owner can insure other owners and use proceeds to buy a deceased owner's interest","The state must purchase all shares automatically"],"answer":2,"explanation":"Cross-purchase plans have owners buy interests directly; entity-redemption plans differ.","conceptId":"C184","variant":4,"id":"E09Q02"},{"category":"Ethics & CA Law","stem":"What is an insurance producer's responsibility in advertising?","options":["Avoid false or misleading claims about coverage, benefits, insurer identity, and guarantees","Claim authorization from CDI without basis","Advertise hypothetical returns as guaranteed","Hide that a statement is an insurance solicitation"],"answer":0,"explanation":"Insurance advertising must not mislead consumers.","conceptId":"C142","variant":1,"id":"E09Q03"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"A guaranteed public share price.\" Which answer most accurately corrects the misunderstanding?","options":["Purchase of a deceased owner's business interest according to the agreement","Payment of the employee's disability income only","An unrelated property casualty deductible","A guaranteed public share price"],"answer":0,"explanation":"Life insurance can provide funds for ownership transition on a business owner's death.","conceptId":"C158","variant":2,"id":"E09Q04"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"The company's group health deductible.\" Which of the following would be the most accurate response?","options":["The company's group health deductible","Every shareholder from stock-price declines","A business from financial loss caused by death of an important employee or owner","An employee's car against theft"],"answer":2,"explanation":"Key-person insurance can provide liquidity while the company recruits or replaces key talent.","conceptId":"C157","variant":3,"id":"E09Q05"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"The producer earns a low commission.\" Which of the following would be the most accurate response?","options":["An insurer invests too conservatively","People with higher-than-average risk are more inclined to seek or keep coverage","The beneficiary changes an address","The producer earns a low commission"],"answer":1,"explanation":"Underwriting helps control the tendency of high-risk applicants to disproportionately seek coverage.","conceptId":"C011","variant":3,"id":"E09Q06"},{"category":"Provisions & Riders","stem":"What is collateral assignment commonly used for?","options":["Pledging policy value or proceeds as security for a loan","Making a child the insured automatically","Converting a policy into health insurance","Eliminating the insurer's claim obligation"],"answer":0,"explanation":"A lender can receive proceeds up to its secured interest before the remainder goes to beneficiaries.","conceptId":"C063","variant":1,"id":"E09Q07"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Giving a standard premium quote.\" Which of the following would be the most accurate response?","options":["Paying an approved policy dividend","Offering an inducement not specified in the policy, where prohibited by applicable law","Explaining a free-look right","Giving a standard premium quote"],"answer":1,"explanation":"Rebating rules restrict improper inducements to buy insurance; assess conduct under current California law.","conceptId":"C132","variant":3,"id":"E09Q08"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"The named beneficiary only.\" Select the statement that should replace this inaccurate advice.","options":["The state insurance department","The insurance producer personally","The named beneficiary only","The contractowner"],"answer":3,"explanation":"Variable annuity separate-account performance affects contract value, subject to any specific guarantees.","conceptId":"C105","variant":4,"id":"E09Q09"},{"category":"Ethics & CA Law","stem":"Which statement regarding the California Life exam is correct under CDI's October 2026 candidate bulletin?","options":["It contains 150 questions and must be completed in 30 minutes","It contains 25 questions with unlimited time","It is automatically passed by completing this practice app","It contains 75 questions, with 105 minutes allowed"],"answer":3,"explanation":"The October 2026 PSI candidate bulletin lists 75 questions and 105 minutes for the Life license exam.","conceptId":"C154","variant":1,"id":"E09Q10"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"Adding an accidental death rider.\" Select the statement that should replace this inaccurate advice.","options":["Surrendering a life policy for a check","Converting annuity value into a series of income payments under a payout option","Adding an accidental death rider","Naming a beneficiary"],"answer":1,"explanation":"Annuitization starts a payout structure often based on life expectancy, rate, and options.","conceptId":"C088","variant":4,"id":"E09Q11"},{"category":"Ethics & CA Law","stem":"What California-specific prelicensing study requirement is identified by CDI for new Life applicants?","options":["100 hours of federal tax law","No ethics study at all","12 hours of study on ethics and the California Insurance Code","50 hours of auto insurance repair"],"answer":2,"explanation":"CDI requires the specified 12 hours of ethics and Insurance Code study for affected applicants.","conceptId":"C156","variant":1,"id":"E09Q12"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"A variable annuity.\" Which of the following would be the most accurate response?","options":["Coverage that declines as a mortgage balance is expected to decrease","A variable annuity","A policy with an increasing guaranteed face amount","A whole-life policy with rising cash value"],"answer":0,"explanation":"Decreasing term is often designed to match a falling debt balance.","conceptId":"C030","variant":3,"id":"E09Q13"},{"category":"Fundamentals","stem":"A person's age, health, and occupation most directly affect what?","options":["The insurer's state of domicile","The beneficiary's right to name an agent","Whether the policy is a contract of adhesion","Underwriting risk classification"],"answer":3,"explanation":"Insurers use relevant underwriting factors to classify expected mortality risk.","conceptId":"C012","variant":1,"id":"E09Q14"},{"category":"Term & Whole Life","stem":"A conversion privilege on a term life policy allows what?","options":["Immediate payment of death proceeds to the living insured","Exchange into eligible permanent coverage without new evidence of insurability within the permitted period","Automatic change of insured person","Cancellation of premiums forever"],"answer":1,"explanation":"Conversion preserves a path to permanent life coverage subject to contract restrictions.","conceptId":"C028","variant":1,"id":"E09Q15"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"The policy's guaranteed loan rate.\" Which of the following would be the most accurate response?","options":["The stated death benefit before adjustments under policy terms","The sum of all premiums already paid","The annual producer commission","The policy's guaranteed loan rate"],"answer":0,"explanation":"Face amount is the amount of coverage shown on the policy; loans or riders may adjust proceeds.","conceptId":"C017","variant":3,"id":"E09Q16"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Local city council alone.\" Which of the following would be the most accurate response?","options":["Local city council alone","California Department of Insurance under the Insurance Commissioner","Federal Reserve alone","Department of Motor Vehicles alone"],"answer":1,"explanation":"CDI oversees insurance licensing and regulation in California.","conceptId":"C135","variant":3,"id":"E09Q17"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"The insurer's right to pay claims promptly.\" Select the statement that should replace this inaccurate advice.","options":["The right of the owner to change premium mode","A beneficiary's right to make a claim","The insurer's right to pay claims promptly","The insurer's ability to contest the policy after the specified contestable period, subject to exceptions"],"answer":3,"explanation":"After the contractual/statutory period, an insurer's grounds to contest validity are limited, with exceptions such as nonpayment.","conceptId":"C055","variant":4,"id":"E09Q18"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"Dividend accumulation.\" Select the statement that should replace this inaccurate advice.","options":["Extended term insurance","Reduced paid-up insurance","Dividend accumulation","Automatic premium loan"],"answer":0,"explanation":"Extended term preserves a face amount for a limited duration based on net cash value.","conceptId":"C066","variant":4,"id":"E09Q19"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. Someone insists: \"Straight term insurance.\" Which of the following would be the most accurate response?","options":["Fixed immediate annuity without investment choice","Variable annuity","Straight term insurance","Traditional fixed annuity"],"answer":1,"explanation":"Variable annuities expose account values to underlying investment performance.","conceptId":"C087","variant":3,"id":"E09Q20"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Two policies that each pay on first death.\" Which answer most accurately corrects the misunderstanding?","options":["Coverage on two lives that generally pays upon the second insured's death","Life insurance that covers only children","A rider that pays premiums after retirement","Two policies that each pay on first death"],"answer":0,"explanation":"Survivorship coverage is often considered in estate or legacy planning.","conceptId":"C048","variant":2,"id":"E09Q21"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"A policy owned by the federal government.\" Which of the following would be the most accurate response?","options":["Coverage paid entirely by an employer only","A policy owned by the federal government","A policy without an insured","Coverage in which members pay some or all of the premium cost"],"answer":3,"explanation":"Contributory plans require employee contributions, unlike noncontributory plans funded by the sponsor.","conceptId":"C181","variant":3,"id":"E09Q22"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. The proposed advice is: \"Purchase a replacement policy for the deceased.\" Select the statement that should replace this inaccurate advice.","options":["Contact the insurer with identifying information and proof of death","Wait for the state to send a check automatically","Assume no insurance exists","Purchase a replacement policy for the deceased"],"answer":0,"explanation":"Insurers can help locate policies and explain claims documentation.","conceptId":"C129","variant":4,"id":"E09Q23"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"Coverage that doubles every month.\" Which of the following would be the most accurate response?","options":["A beneficiary's medical deductible","A death benefit that may be restricted during an initial period under policy terms","A guaranteed annual premium refund","Coverage that doubles every month"],"answer":1,"explanation":"Some simplified-issue products limit early nonaccidental death benefits; review policy details.","conceptId":"C047","variant":3,"id":"E09Q24"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"A beneficiary who owns the insurer.\" Which answer most accurately corrects the misunderstanding?","options":["A beneficiary the owner generally can change without that beneficiary's permission","A beneficiary who owns the insurer","A beneficiary who cannot receive money","A beneficiary who is always paid first during the insured's life"],"answer":0,"explanation":"Revocable beneficiary designations can normally be changed by the policyowner.","conceptId":"C058","variant":2,"id":"E09Q25"},{"category":"Fundamentals","stem":"What is a preferred risk classification?","options":["A beneficiary with first priority","A favorable class generally offered a lower premium than standard","A mandatory class for every applicant","A policy that never lapses"],"answer":1,"explanation":"Preferred applicants meet more favorable underwriting criteria.","conceptId":"C015","variant":1,"id":"E09Q26"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. The proposed advice is: \"Every claim is automatically disputed.\" Select the statement that should replace this inaccurate advice.","options":["The insurer's obligation depends on contractual conditions being satisfied","The applicant sets premium after a claim","Claims are paid whether or not coverage exists","Every claim is automatically disputed"],"answer":0,"explanation":"Payment of benefits depends on conditions such as policy being in force and proof of covered death.","conceptId":"C006","variant":4,"id":"E09Q27"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Accumulation at interest.\" Which answer most accurately corrects the misunderstanding?","options":["Cash dividend option","Accumulation at interest","One-year term option","Premium reduction option"],"answer":3,"explanation":"The premium-reduction option applies declared dividends toward scheduled premium.","conceptId":"C045","variant":2,"id":"E09Q28"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"To insure only a mortgage lender.\" Select the statement that should replace this inaccurate advice.","options":["To pay the face amount at a specified maturity date or earlier covered death","To protect against earthquake damage","To provide only liability insurance","To insure only a mortgage lender"],"answer":0,"explanation":"An endowment combines a death benefit with a contractual maturity payment.","conceptId":"C046","variant":4,"id":"E09Q29"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. A trainee gives the following mistaken explanation: \"Adjusting a beneficiary address.\" Which answer most accurately corrects the misunderstanding?","options":["Adjusting a beneficiary address","Correcting a typographical mistake","Using values in an existing policy to fund another policy primarily to generate new compensation without consumer benefit","Updating an insured's phone number"],"answer":2,"explanation":"Churning can disadvantage consumers with new costs, surrender charges, or lost benefits.","conceptId":"C133","variant":2,"id":"E09Q30"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"Free look only.\" Select the statement that should replace this inaccurate advice.","options":["Assignment","Reinstatement","Free look only","Entire contract"],"answer":1,"explanation":"Reinstatement generally requires overdue payments and evidence of insurability as specified.","conceptId":"C054","variant":4,"id":"E09Q31"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"A securities license in place of life authority for all policies.\" Which of the following would be the most accurate response?","options":["A securities license in place of life authority for all policies","An appropriate active insurance license and any required insurer appointment/authorization","Only a business card","A real estate license"],"answer":1,"explanation":"Proper state licensing and insurer authority are essential to lawful solicitation and sale.","conceptId":"C136","variant":3,"id":"E09Q32"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"To force a policy to become an annuity.\" Which answer most accurately corrects the misunderstanding?","options":["To insure a charity's building against fire","To force a policy to become an annuity","To cancel all premium charges","To direct eligible policy proceeds to a named charitable organization"],"answer":3,"explanation":"A policy can name a charity as beneficiary subject to policy and tax considerations.","conceptId":"C168","variant":2,"id":"E09Q33"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"Favorite television program.\" Which answer most accurately corrects the misunderstanding?","options":["Favorite television program","The insured's favorite holiday","A history of serious heart disease","Preferred shirt color"],"answer":2,"explanation":"Serious medical conditions commonly affect expected mortality and insurer decisions.","conceptId":"C112","variant":2,"id":"E09Q34"},{"category":"Underwriting & Claims","stem":"What is a paramedical examination generally used for?","options":["Setting state insurance laws","Collecting health measurements and specimens for underwriting","Making beneficiary changes","Paying the policy's first dividend"],"answer":1,"explanation":"Paramedical exams assist an insurer's assessment of mortality risk.","conceptId":"C111","variant":1,"id":"E09Q35"},{"category":"Fundamentals","stem":"A household budgets $75 each month for life insurance premiums. What is the annual cash outlay if the price does not change?","options":["$9,000","$825","$750","$900"],"answer":3,"explanation":"12 monthly payments of $75 total $900 annually.","conceptId":"X009","variant":1,"id":"E09Q36"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. A trainee gives the following mistaken explanation: \"To guarantee unlimited tax exemption in all cases.\" Which answer most accurately corrects the misunderstanding?","options":["To eliminate the need for a trustee","To guarantee unlimited tax exemption in all cases","To manage policy ownership, beneficiary distributions, and possible estate planning objectives","To replace state insurance regulation"],"answer":2,"explanation":"Trust structures can control ownership and distribution, but require legal and tax advice.","conceptId":"C176","variant":2,"id":"E09Q37"},{"category":"Underwriting & Claims","stem":"What is a rated policy?","options":["A policy whose cash value is always zero","A policy with guaranteed annual dividends","A policy automatically without premiums","Coverage issued with an extra charge reflecting higher risk"],"answer":3,"explanation":"Insurers may use flat extras or table ratings for qualifying higher-risk applicants.","conceptId":"C128","variant":1,"id":"E09Q38"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"The same as a death certificate.\" Select the statement that should replace this inaccurate advice.","options":["An optional contractual feature that changes benefits or guarantees, often for a fee","A mandatory investment advisory account","A guaranteed public tax deduction","The same as a death certificate"],"answer":0,"explanation":"Riders can add features such as living income benefits; their costs and limitations matter.","conceptId":"C106","variant":4,"id":"E09Q39"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. The proposed advice is: \"An annual adjustable premium.\" Select the statement that should replace this inaccurate advice.","options":["A zero-cost application","One large premium paid at issue","Monthly premiums for life","An annual adjustable premium"],"answer":1,"explanation":"A single premium funds the policy upfront; tax treatment may differ for heavily funded policies.","conceptId":"C034","variant":4,"id":"E09Q40"},{"category":"Fundamentals","stem":"What is a representation on a life insurance application?","options":["An automatic waiver of premiums","A guaranteed dividend rate","A statement made to the best of the applicant's knowledge and belief","A promise that every future event will occur"],"answer":2,"explanation":"Application answers are generally representations, and material misrepresentations may affect coverage.","conceptId":"C019","variant":1,"id":"E09Q41"},{"category":"Provisions & Riders","stem":"Which rider generally waives policy premiums after a qualifying disability and waiting period?","options":["Guaranteed insurability rider","Cost of living rider","Accidental death benefit rider","Waiver of premium rider"],"answer":3,"explanation":"Waiver riders help keep the policy funded during a covered disability.","conceptId":"C069","variant":1,"id":"E09Q42"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"Both are property insurance.\" Which of the following would be the most accurate response?","options":["Both are property insurance","Term life addresses premature-death risk; an annuity can address long-life income risk","Both always pay identical amounts at death","Neither is a contract"],"answer":1,"explanation":"Life coverage and annuities address different financial risks.","conceptId":"C185","variant":3,"id":"E09Q43"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"A receipt that never creates any coverage.\" Which answer most accurately corrects the misunderstanding?","options":["A receipt that never creates any coverage","A beneficiary election form","A permanent annuity","A receipt that can provide specified temporary coverage immediately, subject to its terms and limits"],"answer":3,"explanation":"Binding and conditional receipts differ in how temporary protection is triggered.","conceptId":"C114","variant":2,"id":"E09Q44"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"Waiver of cost of insurance rider.\" Select the statement that should replace this inaccurate advice.","options":["Accidental death rider","Payor benefit rider","Waiver of cost of insurance rider","Guaranteed insurability rider"],"answer":3,"explanation":"Guaranteed insurability options allow increases within contractual dates and limits.","conceptId":"C070","variant":4,"id":"E09Q45"},{"category":"Provisions & Riders","stem":"What is a common settlement option that provides payments as long as a beneficiary lives?","options":["Interest-only option","Life income option","Lump-sum option","Fixed-period option"],"answer":1,"explanation":"Life income bases periodic payments on a payee's lifetime, often with optional guarantees.","conceptId":"C078","variant":1,"id":"E09Q46"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Charging different premiums for justified risk classes.\" Which answer most accurately corrects the misunderstanding?","options":["Following filed actuarial rules","Using relevant mortality experience","Charging different premiums for justified risk classes","Treating people with the same risk classification differently without a lawful underwriting basis"],"answer":3,"explanation":"Risk distinctions must have a lawful actuarial or underwriting justification; unfair discrimination is prohibited.","conceptId":"C137","variant":2,"id":"E09Q47"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"Principal is always withdrawn first.\" Which answer most accurately corrects the misunderstanding?","options":["Earnings are generally withdrawn first for tax purposes","Withdrawals are never taxable","Every withdrawal is a capital gain","Principal is always withdrawn first"],"answer":0,"explanation":"Nonqualified annuity distributions commonly follow last-in-first-out ordering before annuitization.","conceptId":"C095","variant":2,"id":"E09Q48"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. Someone insists: \"Marketing, age of producer, and commissions only.\" Which of the following would be the most accurate response?","options":["Mortality, interest, and expenses","Marketing, age of producer, and commissions only","Deductible, coinsurance, and copayment","Taxes, inflation, and stock dividends only"],"answer":0,"explanation":"Pricing reflects expected claims, investment earnings and operating costs.","conceptId":"C010","variant":3,"id":"E09Q49"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"Employees always own lifelong portable coverage.\" Which answer most accurately corrects the misunderstanding?","options":["Coverage can never terminate when employment ends","Employees always own lifelong portable coverage","Cash value is always guaranteed","Coverage may be accessible with simplified enrollment at group rates"],"answer":3,"explanation":"Group term may be convenient but has portability and coverage-limit considerations.","conceptId":"C178","variant":2,"id":"E09Q50"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"Forgoing any premium due.\" Select the statement that should replace this inaccurate advice.","options":["Providing the issued contract and explaining relevant terms and changes","Forgoing any premium due","Guaranteeing every rider is free","Returning the application to the insured without issuing a policy"],"answer":0,"explanation":"Delivery is when the policyowner receives and can review the contract.","conceptId":"C119","variant":4,"id":"E09Q51"},{"category":"Ethics & CA Law","stem":"What is the ethical issue with promising an IUL will earn a fixed high annual return indefinitely?","options":["All index crediting is guaranteed at 15%","The death benefit becomes taxable annually","Index-linked crediting and policy values are not guaranteed at that illustrated rate","The insurer is a mutual fund"],"answer":2,"explanation":"Illustrated non-guaranteed values must not be described as guaranteed results.","conceptId":"C147","variant":1,"id":"E09Q52"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"Extended term insurance.\" Which of the following would be the most accurate response?","options":["Cash surrender","Reduced paid-up insurance","Extended term insurance","Policy replacement"],"answer":1,"explanation":"Reduced paid-up uses available value to buy a smaller fully paid permanent policy.","conceptId":"C065","variant":3,"id":"E09Q53"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"A guaranteed constant investment return in all cases.\" Which answer most accurately corrects the misunderstanding?","options":["A guaranteed constant investment return in all cases","Flexible premium payments and adjustable death-benefit options subject to policy limits","No lapse risk ever","No cost of insurance charges"],"answer":1,"explanation":"Universal life separates cash value accumulation from insurance charges and permits specified flexibility.","conceptId":"C035","variant":2,"id":"E09Q54"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Giving a client a copy of the policy.\" Which of the following would be the most accurate response?","options":["Using misleading comparisons or representations to induce an improper policy replacement","Giving a client a copy of the policy","Explaining legitimate policy differences accurately","Notifying an insurer of an address change"],"answer":0,"explanation":"Twisting involves misrepresentation to persuade a customer to replace coverage.","conceptId":"C131","variant":3,"id":"E09Q55"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. Someone insists: \"The beneficiary must pay premiums after death.\" Which of the following would be the most accurate response?","options":["The death benefit doubles automatically","The insurer must waive all charges forever","The beneficiary must pay premiums after death","The policy can lapse unless additional funding or a guarantee prevents it"],"answer":3,"explanation":"Flexible premiums do not eliminate the requirement to fund mortality and expenses.","conceptId":"C036","variant":3,"id":"E09Q56"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"A person with no insurable interest.\" Which of the following would be the most accurate response?","options":["An applicant who always gets preferred rates","A beneficiary who is a minor","An applicant with higher-than-normal expected mortality who may be charged extra premium","A person with no insurable interest"],"answer":2,"explanation":"Higher risk can result in rating, exclusions if lawful, postponement, or decline.","conceptId":"C014","variant":3,"id":"E09Q57"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Traditional fixed whole life.\" Which answer most accurately corrects the misunderstanding?","options":["Decreasing term","Variable life insurance","Annually renewable term","Traditional fixed whole life"],"answer":1,"explanation":"Variable life values can rise or fall with selected investments; securities regulation applies.","conceptId":"C037","variant":2,"id":"E09Q58"},{"category":"Fundamentals","stem":"A client is comparing two insurance proposals. Someone insists: \"It must be signed by every beneficiary.\" Which of the following would be the most accurate response?","options":["Both parties negotiate every word equally","The insurer drafts the policy and the applicant usually accepts or rejects its terms","It is automatically renewed every month","It must be signed by every beneficiary"],"answer":1,"explanation":"Ambiguities in an adhesion contract are generally interpreted against the drafter.","conceptId":"C005","variant":3,"id":"E09Q59"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"The insurer's stock market capitalization.\" Select the statement that should replace this inaccurate advice.","options":["The replacement cost of the insured's house only","Economic value of the insured's future earnings available to dependents","The insurer's stock market capitalization","The price of the producer's license"],"answer":1,"explanation":"Human life value estimates the present value of expected future income contributions.","conceptId":"C166","variant":4,"id":"E09Q60"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. The proposed advice is: \"Make every beneficiary irrevocable.\" Select the statement that should replace this inaccurate advice.","options":["Avoid insurer solvency requirements","Restrict a beneficiary's ability to assign or prematurely spend certain proceeds under the arrangement","Guarantee investment gains","Make every beneficiary irrevocable"],"answer":1,"explanation":"Spendthrift arrangements can control access to proceeds and may provide creditor protections subject to law.","conceptId":"C077","variant":4,"id":"E09Q61"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"Proceeds must be donated to charity.\" Select the statement that should replace this inaccurate advice.","options":["Only the oldest child receives proceeds","Proceeds must be donated to charity","Every surviving beneficiary receives an equal share regardless of branch","A deceased beneficiary's share passes down their family branch"],"answer":3,"explanation":"Per stirpes allocation follows family branches; per capita generally divides among surviving members of the stated class.","conceptId":"C061","variant":4,"id":"E09Q62"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"The insurer's investment selection.\" Select the statement that should replace this inaccurate advice.","options":["A state examination proctor's review","The beneficiary's preparation of a tax return","The producer's initial collection and observation of risk information","The insurer's investment selection"],"answer":2,"explanation":"Producers help collect complete applications and identify relevant underwriting facts.","conceptId":"C116","variant":4,"id":"E09Q63"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. The proposed advice is: \"A new application for the deceased.\" Select the statement that should replace this inaccurate advice.","options":["A property inspection only","Proof of the beneficiary's salary only","Proof of death plus the insurer's claim forms and supporting records as needed","A new application for the deceased"],"answer":2,"explanation":"A death certificate and claimant information are common components of a death claim.","conceptId":"C122","variant":4,"id":"E09Q64"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"A whole life policy dividend.\" Select the statement that should replace this inaccurate advice.","options":["An annuity with an accumulation period before income payments begin","A whole life policy dividend","A rider for accidental death","An annuity that must pay tomorrow"],"answer":0,"explanation":"Deferred annuities allow assets to accumulate before annuitization or withdrawals.","conceptId":"C085","variant":4,"id":"E09Q65"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. A trainee gives the following mistaken explanation: \"Only life insurance death claims.\" Which answer most accurately corrects the misunderstanding?","options":["Money in a tax-favored retirement plan or IRA","Only after-tax funds that can never be deducted","Only life insurance death claims","Only insurer dividends"],"answer":0,"explanation":"Qualified annuities are held within qualified retirement arrangements and follow their tax rules.","conceptId":"C098","variant":2,"id":"E09Q66"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"Automatically a tax-free gift to the producer.\" Select the statement that should replace this inaccurate advice.","options":["Always deductible interest","Usually no current income tax on the loan, but lapse or surrender can trigger taxable gain","Always an immediate tax on the entire death benefit","Automatically a tax-free gift to the producer"],"answer":1,"explanation":"Policy loans can be tax-efficient but create interest and potential taxable lapse risk.","conceptId":"C162","variant":4,"id":"E09Q67"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"It cannot earn any interest.\" Select the statement that should replace this inaccurate advice.","options":["It is protected by FDIC deposit insurance as a bank checking account","Withdrawals may face surrender charges, taxes, or limited liquidity","It always permits free instant withdrawals without charges","It cannot earn any interest"],"answer":1,"explanation":"Annuity liquidity is contractual and can carry costs or taxes, making emergency access uncertain.","conceptId":"C103","variant":4,"id":"E09Q68"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"A guaranteed pension from Social Security.\" Which of the following would be the most accurate response?","options":["A contract with no life insurance death benefit","A guaranteed pension from Social Security","A life insurance contract that fails the federal seven-pay test and receives less favorable distribution tax treatment","A policy cancelled during its free look"],"answer":2,"explanation":"MEC distributions and loans commonly have earnings-first taxation and may face early-distribution penalties.","conceptId":"C163","variant":3,"id":"E09Q69"},{"category":"Business & Tax","stem":"Which party bears the cost of life insurance premiums on a personally owned policy in the usual arrangement?","options":["The insurer's reinsurer","The Insurance Commissioner","The policyowner","The contingent beneficiary by law"],"answer":2,"explanation":"The owner is responsible for funding the policy unless another payer is arranged.","conceptId":"C169","variant":1,"id":"E09Q70"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"Death benefits for the agent.\" Which answer most accurately corrects the misunderstanding?","options":["Premium payment if the person paying premiums dies or becomes disabled as defined","Stock market loss","Property loss at the child's school","Death benefits for the agent"],"answer":0,"explanation":"Payor riders protect juvenile policies when the paying adult suffers a covered event.","conceptId":"C074","variant":2,"id":"E09Q71"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"To allow a beneficiary change after claim payment.\" Which of the following would be the most accurate response?","options":["To extend a policy after its maturity without conditions","To keep coverage in force for a specified time after a premium is due","To allow a beneficiary change after claim payment","To waive every future premium"],"answer":1,"explanation":"A grace period provides a window to pay overdue premiums while coverage generally continues.","conceptId":"C053","variant":3,"id":"E09Q72"},{"category":"Annuities & Retirement","stem":"A retiree is assessing a proposed annuity. The proposed advice is: \"Always the beneficiary and never the owner.\" Select the statement that should replace this inaccurate advice.","options":["Always the beneficiary and never the owner","The insurer's claims manager","The person whose life is used to determine annuity payments under life-contingent options","The state insurance commissioner"],"answer":2,"explanation":"The annuitant's life may measure how long payments continue.","conceptId":"C089","variant":4,"id":"E09Q73"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"To guarantee a stock price.\" Which answer most accurately corrects the misunderstanding?","options":["To guarantee a stock price","To determine the agent's tax return","To transfer ownership automatically","To support financial underwriting and justify a large coverage amount"],"answer":3,"explanation":"Financial underwriting evaluates coverage need and potential overinsurance or anti-selection.","conceptId":"C118","variant":2,"id":"E09Q74"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"Mortgage decreasing term.\" Which of the following would be the most accurate response?","options":["A one-year level term policy","A lifetime income annuity","Mortgage decreasing term","Credit life insurance"],"answer":1,"explanation":"Lifetime annuity income can mitigate the risk of outliving retirement resources.","conceptId":"C104","variant":3,"id":"E09Q75"}]},{"title":"Exam 10","questions":[{"category":"Annuities & Retirement","stem":"An indexed fixed annuity generally credits interest according to what?","options":["Direct ownership of individual index stocks by the owner","A contractual formula referencing an external index rather than direct stock ownership","A guaranteed equal share of index dividends","A federally insured bank deposit rate"],"answer":1,"explanation":"Index crediting uses a formula, often with caps, spreads, or participation rates.","conceptId":"C100","variant":1,"id":"E10Q01"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"Property loss at the child's school.\" Which of the following would be the most accurate response?","options":["Premium payment if the person paying premiums dies or becomes disabled as defined","Death benefits for the agent","Stock market loss","Property loss at the child's school"],"answer":0,"explanation":"Payor riders protect juvenile policies when the paying adult suffers a covered event.","conceptId":"C074","variant":3,"id":"E10Q02"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. A trainee gives the following mistaken explanation: \"A contract with no life insurance death benefit.\" Which answer most accurately corrects the misunderstanding?","options":["A life insurance contract that fails the federal seven-pay test and receives less favorable distribution tax treatment","A policy cancelled during its free look","A guaranteed pension from Social Security","A contract with no life insurance death benefit"],"answer":0,"explanation":"MEC distributions and loans commonly have earnings-first taxation and may face early-distribution penalties.","conceptId":"C163","variant":2,"id":"E10Q03"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"The insured's attained age.\" Which answer most accurately corrects the misunderstanding?","options":["The scheduled premium","The insurer's claim expenses","The investment return","The insured's attained age"],"answer":0,"explanation":"Level-premium term has stable premiums for a stated guaranteed period.","conceptId":"C029","variant":2,"id":"E10Q04"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. A trainee gives the following mistaken explanation: \"Every employee equally.\" Which answer most accurately corrects the misunderstanding?","options":["The business, subject to consent and applicable rules","The state insurance regulator","Every employee equally","Always the employee's children"],"answer":0,"explanation":"The business often applies for, owns, and benefits from key-person protection.","conceptId":"C159","variant":2,"id":"E10Q05"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. Someone insists: \"A reduction of the insurer's license fee.\" Which of the following would be the most accurate response?","options":["Automatic payment of a death benefit","A beneficiary affidavit for all applications","A reduction of the insurer's license fee","A current health statement or further underwriting as the insurer requires"],"answer":3,"explanation":"A material health change before effective coverage may affect eligibility and the insurer's requirements.","conceptId":"C120","variant":3,"id":"E10Q06"},{"category":"Fundamentals","stem":"What is adverse selection?","options":["The producer earns a low commission","An insurer invests too conservatively","The beneficiary changes an address","People with higher-than-average risk are more inclined to seek or keep coverage"],"answer":3,"explanation":"Underwriting helps control the tendency of high-risk applicants to disproportionately seek coverage.","conceptId":"C011","variant":1,"id":"E10Q07"},{"category":"Underwriting & Claims","stem":"What is the producer's role when completing a life application?","options":["Alter answers after the applicant signs","Guarantee approval without underwriting","Record answers accurately and submit complete information to the insurer","Suggest concealing relevant medical history"],"answer":2,"explanation":"Agents must transmit accurate application information and should not misrepresent material facts.","conceptId":"C108","variant":1,"id":"E10Q08"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. Someone insists: \"The applicant changes insurers after death.\" Which of the following would be the most accurate response?","options":["The applicant changes insurers after death","A beneficiary purchases a policy loan","An insurer transfers part of its insurance risk to another insurer","An agent renews their license"],"answer":2,"explanation":"Reinsurance lets a ceding company share risk with a reinsurer.","conceptId":"C018","variant":3,"id":"E10Q09"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"No lapse risk ever.\" Select the statement that should replace this inaccurate advice.","options":["No cost of insurance charges","Flexible premium payments and adjustable death-benefit options subject to policy limits","No lapse risk ever","A guaranteed constant investment return in all cases"],"answer":1,"explanation":"Universal life separates cash value accumulation from insurance charges and permits specified flexibility.","conceptId":"C035","variant":4,"id":"E10Q10"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"The death benefit doubles automatically.\" Select the statement that should replace this inaccurate advice.","options":["The policy can lapse unless additional funding or a guarantee prevents it","The death benefit doubles automatically","The insurer must waive all charges forever","The beneficiary must pay premiums after death"],"answer":0,"explanation":"Flexible premiums do not eliminate the requirement to fund mortality and expenses.","conceptId":"C036","variant":4,"id":"E10Q11"},{"category":"Provisions & Riders","stem":"A policyowner is reading the policy contract. A trainee gives the following mistaken explanation: \"To pay insurance premiums as a legal requirement.\" Which answer most accurately corrects the misunderstanding?","options":["To approve every policy loan","To pay insurance premiums as a legal requirement","To be the policy's insured automatically","To receive the death benefit first when eligible under the designation"],"answer":3,"explanation":"A primary beneficiary has first priority to receive proceeds subject to designation and applicable law.","conceptId":"C076","variant":2,"id":"E10Q12"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. A trainee gives the following mistaken explanation: \"25% mandatory federal fee.\" Which answer most accurately corrects the misunderstanding?","options":["No potential additional tax","25% mandatory federal fee","10% additional tax","A 50% flat surcharge"],"answer":2,"explanation":"An early distribution can trigger an additional 10% federal tax on taxable amounts, subject to exceptions.","conceptId":"C096","variant":2,"id":"E10Q13"},{"category":"Annuities & Retirement","stem":"What is the exclusion ratio used for in a nonqualified annuity payout?","options":["To set the beneficiary's age","To calculate the agent's commission","To determine a medical deductible","To determine the portion of each qualifying payment treated as return of investment versus taxable income"],"answer":3,"explanation":"The exclusion ratio allocates annuity payments between basis recovery and taxable income, when applicable.","conceptId":"C097","variant":1,"id":"E10Q14"},{"category":"Business & Tax","stem":"Why may a policyowner establish a life insurance trust?","options":["To eliminate the need for a trustee","To replace state insurance regulation","To guarantee unlimited tax exemption in all cases","To manage policy ownership, beneficiary distributions, and possible estate planning objectives"],"answer":3,"explanation":"Trust structures can control ownership and distribution, but require legal and tax advice.","conceptId":"C176","variant":1,"id":"E10Q15"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. Someone insists: \"Annually renewable term.\" Which of the following would be the most accurate response?","options":["Variable life insurance","Decreasing term","Traditional fixed whole life","Annually renewable term"],"answer":0,"explanation":"Variable life values can rise or fall with selected investments; securities regulation applies.","conceptId":"C037","variant":3,"id":"E10Q16"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. Someone insists: \"More dependent children.\" Which of the following would be the most accurate response?","options":["More liquid savings available to survivors","Higher income replacement needs","More dependent children","A larger outstanding mortgage"],"answer":0,"explanation":"Existing assets can offset some future survivor needs.","conceptId":"C175","variant":3,"id":"E10Q17"},{"category":"Ethics & CA Law","stem":"What passing percentage does the October 2026 California PSI bulletin list for the Life license exam?","options":["90%","80%","100%","60%"],"answer":3,"explanation":"The current PSI candidate bulletin states a 60% passing score for the Life exam; aim higher on practice tests.","conceptId":"C155","variant":1,"id":"E10Q18"},{"category":"Provisions & Riders","stem":"Which rider usually permits the purchase of additional coverage at specified times without new medical underwriting?","options":["Guaranteed insurability rider","Payor benefit rider","Waiver of cost of insurance rider","Accidental death rider"],"answer":0,"explanation":"Guaranteed insurability options allow increases within contractual dates and limits.","conceptId":"C070","variant":1,"id":"E10Q19"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"Appropriate needs analysis.\" Which answer most accurately corrects the misunderstanding?","options":["Reinsurance","Conflict of interest and unsuitable recommendation","Appropriate needs analysis","Risk pooling"],"answer":1,"explanation":"Recommendations should be based on the client's legitimate objectives, not compensation alone.","conceptId":"C149","variant":2,"id":"E10Q20"},{"category":"Fundamentals","stem":"What is mortality in life insurance pricing?","options":["The number of applications rejected","The interest on policy loans","The amount of commission paid","The rate of death in a defined group"],"answer":3,"explanation":"Mortality assumptions help insurers estimate expected death claims.","conceptId":"C009","variant":1,"id":"E10Q21"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"Coverage that cannot have beneficiaries.\" Select the statement that should replace this inaccurate advice.","options":["Coverage that cannot have beneficiaries","Individual coverage purchased through an agent","Group coverage for which the sponsor pays the full premium","Coverage with premiums split evenly by law"],"answer":2,"explanation":"Noncontributory coverage is financed by the employer or group sponsor.","conceptId":"C182","variant":4,"id":"E10Q22"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"An agent changing employers.\" Select the statement that should replace this inaccurate advice.","options":["The policyowner's retirement","An agent changing employers","The insured's death while qualifying coverage is in force","Any beneficiary birthday"],"answer":2,"explanation":"Death benefits arise on covered death and appropriate claim documentation.","conceptId":"C082","variant":4,"id":"E10Q23"},{"category":"Fundamentals","stem":"The law of large numbers helps an insurer do what?","options":["Guarantee no claims occur","Predict the exact death date of each insured","Eliminate underwriting","Predict aggregate losses more reliably for a large group"],"answer":3,"explanation":"A large population makes actual mortality experience more predictable in aggregate.","conceptId":"C008","variant":1,"id":"E10Q24"},{"category":"Provisions & Riders","stem":"What is an irrevocable beneficiary?","options":["A beneficiary named only for one day","A beneficiary who receives no rights","A beneficiary whose consent is generally required for changes affecting their protected interest","A beneficiary always selected by the insurer"],"answer":2,"explanation":"An irrevocable designation limits the owner's ability to change the beneficiary or impair their interest.","conceptId":"C059","variant":1,"id":"E10Q25"},{"category":"Fundamentals","stem":"A household is purchasing its first life policy. A trainee gives the following mistaken explanation: \"A speculative bet on stock prices.\" Which answer most accurately corrects the misunderstanding?","options":["Pure risk involving possible loss but no opportunity for gain","A business venture seeking profit","A casino wager","A speculative bet on stock prices"],"answer":0,"explanation":"Pure risks involve loss or no loss, while speculative risks include a possibility of gain.","conceptId":"C007","variant":2,"id":"E10Q26"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. The proposed advice is: \"There is no taxation at any time.\" Select the statement that should replace this inaccurate advice.","options":["Earnings must be taxed every week","Earnings are always tax free forever","There is no taxation at any time","Earnings are generally tax deferred"],"answer":3,"explanation":"Tax deferral postpones income tax on earnings until taxable distributions occur.","conceptId":"C094","variant":4,"id":"E10Q27"},{"category":"Underwriting & Claims","stem":"If a beneficiary has not filed a claim because they lack a policy number, what is generally the best next step?","options":["Contact the insurer with identifying information and proof of death","Assume no insurance exists","Purchase a replacement policy for the deceased","Wait for the state to send a check automatically"],"answer":0,"explanation":"Insurers can help locate policies and explain claims documentation.","conceptId":"C129","variant":1,"id":"E10Q28"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"100 hours of federal tax law.\" Which answer most accurately corrects the misunderstanding?","options":["50 hours of auto insurance repair","100 hours of federal tax law","No ethics study at all","12 hours of study on ethics and the California Insurance Code"],"answer":3,"explanation":"CDI requires the specified 12 hours of ethics and Insurance Code study for affected applicants.","conceptId":"C156","variant":2,"id":"E10Q29"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. The proposed advice is: \"To insure a company's stock price.\" Select the statement that should replace this inaccurate advice.","options":["To protect a lender's property against fire","To pay a covered outstanding debt if the insured borrower dies","To insure a company's stock price","To replace disability income"],"answer":1,"explanation":"Credit life is tied to a debt obligation and commonly has a decreasing benefit.","conceptId":"C050","variant":4,"id":"E10Q30"},{"category":"Fundamentals","stem":"A new agent is preparing a consumer education leaflet. A trainee gives the following mistaken explanation: \"The sum of all premiums already paid.\" Which answer most accurately corrects the misunderstanding?","options":["The stated death benefit before adjustments under policy terms","The policy's guaranteed loan rate","The annual producer commission","The sum of all premiums already paid"],"answer":0,"explanation":"Face amount is the amount of coverage shown on the policy; loans or riders may adjust proceeds.","conceptId":"C017","variant":2,"id":"E10Q31"},{"category":"Fundamentals","stem":"What is material misrepresentation?","options":["A beneficiary's new mailing address","A producer's phone number change","An incorrect statement important to an insurer's underwriting decision","Any minor spelling error"],"answer":2,"explanation":"Materiality relates to whether accurate facts would have influenced acceptance, risk, or premium.","conceptId":"C020","variant":1,"id":"E10Q32"},{"category":"Ethics & CA Law","stem":"During a California agent training review. The proposed advice is: \"Ignore the exclusion as minor.\" Select the statement that should replace this inaccurate advice.","options":["Ignore the exclusion as minor","Confirm its meaning from the insurer's policy materials before making a representation","Assure the customer all risks are covered","Invent an explanation to close the sale"],"answer":1,"explanation":"Competence requires knowing policy limits and avoiding unsupported statements.","conceptId":"C144","variant":4,"id":"E10Q33"},{"category":"Provisions & Riders","stem":"What does a fixed-period settlement option specify?","options":["Only interest is payable","Payments over a selected number of years","Payments until age 120 no matter what","A single immediate payment only"],"answer":1,"explanation":"A fixed period establishes duration; payment size depends on proceeds and contract assumptions.","conceptId":"C080","variant":1,"id":"E10Q34"},{"category":"Annuities & Retirement","stem":"Why might a purchaser select an annuity with a period-certain payout?","options":["To guarantee unlimited market growth","To obtain auto insurance","To avoid any income taxation","To reduce the risk that all income stops immediately after an early death"],"answer":3,"explanation":"Period-certain payments can continue to a beneficiary if death occurs during the guarantee period.","conceptId":"C102","variant":1,"id":"E10Q35"},{"category":"Ethics & CA Law","stem":"During a California agent training review. Someone insists: \"Wait until after a claim.\" Which of the following would be the most accurate response?","options":["Quietly change a signed form without consent","Promptly notify the insurer and correct it through approved procedures","Ask a beneficiary to sign for the insured","Wait until after a claim"],"answer":1,"explanation":"Application corrections must be accurate and properly authorized.","conceptId":"C148","variant":3,"id":"E10Q36"},{"category":"Underwriting & Claims","stem":"What is the significance of the insured's occupation during underwriting?","options":["Occupation never matters","Only beneficiaries' jobs matter","A job title determines the insurer's solvency","Some occupations carry greater mortality hazards"],"answer":3,"explanation":"Occupational hazards may influence risk assessment and rates.","conceptId":"C117","variant":1,"id":"E10Q37"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. The proposed advice is: \"A beneficiary's unrelated bank statements.\" Select the statement that should replace this inaccurate advice.","options":["A beneficiary's unrelated bank statements","The policy and attached application and endorsements as applicable","An agent's unwritten verbal promises","Any insurer advertisement ever produced"],"answer":1,"explanation":"The written contract is assembled from the policy and specified attached documents.","conceptId":"C057","variant":4,"id":"E10Q38"},{"category":"Underwriting & Claims","stem":"The Medical Information Bureau (MIB) is best described as what?","options":["A company that guarantees claim payment","An information exchange used by member insurers in underwriting, subject to privacy rules","A federal insurer of life benefits","A regulator that issues agents' licenses"],"answer":1,"explanation":"MIB information can flag relevant application data; insurers must verify information as appropriate.","conceptId":"C110","variant":1,"id":"E10Q39"},{"category":"Annuities & Retirement","stem":"If a variable annuity subaccount loses value, who generally bears the investment performance risk?","options":["The state insurance department","The named beneficiary only","The contractowner","The insurance producer personally"],"answer":2,"explanation":"Variable annuity separate-account performance affects contract value, subject to any specific guarantees.","conceptId":"C105","variant":1,"id":"E10Q40"},{"category":"Underwriting & Claims","stem":"What is a life insurance policy delivery requirement?","options":["Returning the application to the insured without issuing a policy","Guaranteeing every rider is free","Providing the issued contract and explaining relevant terms and changes","Forgoing any premium due"],"answer":2,"explanation":"Delivery is when the policyowner receives and can review the contract.","conceptId":"C119","variant":1,"id":"E10Q41"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"Guarantee future interest rates.\" Select the statement that should replace this inaccurate advice.","options":["Select the insurer with the highest commission","Estimate the survivor's financial obligations and resources to choose an appropriate coverage amount","Guarantee future interest rates","Predict the exact day of death"],"answer":1,"explanation":"Needs analysis considers debts, income replacement, dependents, education, and existing assets.","conceptId":"C165","variant":4,"id":"E10Q42"},{"category":"Business & Tax","stem":"A policy has a monthly premium of $68 and no additional fees. What is the total premium paid for 18 months?","options":["$1,360","$1,224","$1,180","$816"],"answer":1,"explanation":"68 × 18 = 1,224.","conceptId":"X004","variant":1,"id":"E10Q43"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. A trainee gives the following mistaken explanation: \"Direct ownership of every stock in an index.\" Which answer most accurately corrects the misunderstanding?","options":["An index-crediting formula subject to caps, participation rates, floors, and contract charges","A fixed government pension payment","A guaranteed stock-market rate of return","Direct ownership of every stock in an index"],"answer":0,"explanation":"Indexed UL uses a contractual crediting method, not direct ownership of index shares.","conceptId":"C039","variant":2,"id":"E10Q44"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. The proposed advice is: \"Tell the client reading is unnecessary.\" Select the statement that should replace this inaccurate advice.","options":["Explain the changes and material risks in understandable terms before proceeding","Hide the old policy values","Tell the client reading is unnecessary","Obtain a signature without explanation"],"answer":0,"explanation":"Informed consent requires understandable, accurate discussion of material changes.","conceptId":"C151","variant":4,"id":"E10Q45"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"To insure a car.\" Which of the following would be the most accurate response?","options":["To provide a stream of income, often for retirement","To insure a car","To cover a homeowner's liability","To pay a death benefit only for accidental death"],"answer":0,"explanation":"Annuities are contracts for accumulation and/or distribution of income.","conceptId":"C083","variant":3,"id":"E10Q46"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. A trainee gives the following mistaken explanation: \"Federal Reserve alone.\" Which answer most accurately corrects the misunderstanding?","options":["Department of Motor Vehicles alone","Local city council alone","California Department of Insurance under the Insurance Commissioner","Federal Reserve alone"],"answer":2,"explanation":"CDI oversees insurance licensing and regulation in California.","conceptId":"C135","variant":2,"id":"E10Q47"},{"category":"Annuities & Retirement","stem":"A client is reviewing annuity distribution choices. Someone insists: \"Withdrawals are never taxable.\" Which of the following would be the most accurate response?","options":["Every withdrawal is a capital gain","Withdrawals are never taxable","Earnings are generally withdrawn first for tax purposes","Principal is always withdrawn first"],"answer":2,"explanation":"Nonqualified annuity distributions commonly follow last-in-first-out ordering before annuitization.","conceptId":"C095","variant":3,"id":"E10Q48"},{"category":"Fundamentals","stem":"Which three broad assumptions are used to price traditional life insurance premiums?","options":["Taxes, inflation, and stock dividends only","Marketing, age of producer, and commissions only","Mortality, interest, and expenses","Deductible, coinsurance, and copayment"],"answer":2,"explanation":"Pricing reflects expected claims, investment earnings and operating costs.","conceptId":"C010","variant":1,"id":"E10Q49"},{"category":"Ethics & CA Law","stem":"During a California agent training review. A trainee gives the following mistaken explanation: \"To avoid providing disclosures.\" Which answer most accurately corrects the misunderstanding?","options":["To demonstrate the basis for a suitable recommendation and preserve accurate records","To avoid providing disclosures","To substitute for the applicant's signature","To guarantee investment performance"],"answer":0,"explanation":"Documenting needs, costs, and decisions helps support compliant recommendations.","conceptId":"C146","variant":2,"id":"E10Q50"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"Vehicle title report.\" Which answer most accurately corrects the misunderstanding?","options":["Property deed","Credit card reward statement","Attending physician statement (APS)","Vehicle title report"],"answer":2,"explanation":"An APS may help an insurer understand medical conditions and treatment history.","conceptId":"C109","variant":2,"id":"E10Q51"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"Fixed immediate annuity without investment choice.\" Select the statement that should replace this inaccurate advice.","options":["Variable annuity","Fixed immediate annuity without investment choice","Traditional fixed annuity","Straight term insurance"],"answer":0,"explanation":"Variable annuities expose account values to underlying investment performance.","conceptId":"C087","variant":4,"id":"E10Q52"},{"category":"Business & Tax","stem":"A household is discussing financial protection and taxes. The proposed advice is: \"A bank deposit statement.\" Select the statement that should replace this inaccurate advice.","options":["The contract issued to the group policyholder, often an employer","An individual auto coverage contract","A separate full master policy issued to every worker","A bank deposit statement"],"answer":0,"explanation":"The group sponsor generally receives the master policy and insured members receive certificates.","conceptId":"C177","variant":4,"id":"E10Q53"},{"category":"Term & Whole Life","stem":"What is the purpose of an endowment policy?","options":["To protect against earthquake damage","To provide only liability insurance","To pay the face amount at a specified maturity date or earlier covered death","To insure only a mortgage lender"],"answer":2,"explanation":"An endowment combines a death benefit with a contractual maturity payment.","conceptId":"C046","variant":1,"id":"E10Q54"},{"category":"Ethics & CA Law","stem":"What is the safest response to an applicant asking an agent to omit a serious diagnosis?","options":["Explain that answers must be truthful and submit complete information","Omit it because the client requested it","Alter the physician's records","Promise the condition cannot be discovered"],"answer":0,"explanation":"Concealing material facts can be fraud and threaten coverage.","conceptId":"C140","variant":1,"id":"E10Q55"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. Someone insists: \"The producer pays the difference personally.\" Which of the following would be the most accurate response?","options":["The policy converts to disability insurance","The producer pays the difference personally","The policy is automatically void for every age error","Benefits or premiums are adjusted to reflect the correct age"],"answer":3,"explanation":"A wrong age typically leads to an actuarial adjustment rather than automatically voiding the contract.","conceptId":"C056","variant":3,"id":"E10Q56"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. The proposed advice is: \"A term insurance conversion only.\" Select the statement that should replace this inaccurate advice.","options":["A transfer of all ownership rights in a policy","A short-term loan against cash value only","A temporary grace period","A term insurance conversion only"],"answer":0,"explanation":"Absolute assignment is broader than collateral assignment.","conceptId":"C064","variant":4,"id":"E10Q57"},{"category":"Business & Tax","stem":"A small-business owner seeks life insurance planning advice. The proposed advice is: \"There is never a taxable surrender gain.\" Select the statement that should replace this inaccurate advice.","options":["There is never a taxable surrender gain","The entire original face amount is taxed","Gain above the policyowner's adjusted basis is generally taxable, subject to applicable rules","The entire surrender value is always tax free"],"answer":2,"explanation":"Surrender proceeds exceeding basis generally produce ordinary income rather than capital gain.","conceptId":"C164","variant":4,"id":"E10Q58"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"Accidental death benefit rider.\" Which answer most accurately corrects the misunderstanding?","options":["Cost of living rider","Guaranteed insurability rider","Accidental death benefit rider","Waiver of premium rider"],"answer":3,"explanation":"Waiver riders help keep the policy funded during a covered disability.","conceptId":"C069","variant":2,"id":"E10Q59"},{"category":"Underwriting & Claims","stem":"A beneficiary is preparing a claim. A trainee gives the following mistaken explanation: \"A policy automatically without premiums.\" Which answer most accurately corrects the misunderstanding?","options":["A policy whose cash value is always zero","A policy automatically without premiums","A policy with guaranteed annual dividends","Coverage issued with an extra charge reflecting higher risk"],"answer":3,"explanation":"Insurers may use flat extras or table ratings for qualifying higher-risk applicants.","conceptId":"C128","variant":2,"id":"E10Q60"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. A trainee gives the following mistaken explanation: \"A guaranteed annual premium refund.\" Which answer most accurately corrects the misunderstanding?","options":["A beneficiary's medical deductible","A death benefit that may be restricted during an initial period under policy terms","A guaranteed annual premium refund","Coverage that doubles every month"],"answer":1,"explanation":"Some simplified-issue products limit early nonaccidental death benefits; review policy details.","conceptId":"C047","variant":2,"id":"E10Q61"},{"category":"Business & Tax","stem":"Which statement generally describes life insurance death proceeds received by an individual beneficiary under federal income tax law?","options":["They are generally excluded from gross income, with important exceptions","They are always taxed as ordinary wages","They are always capital gains","They are taxable every year before death"],"answer":0,"explanation":"IRC Section 101(a) generally excludes death proceeds from income, subject to exceptions such as transfer-for-value.","conceptId":"C160","variant":1,"id":"E10Q62"},{"category":"Fundamentals","stem":"Which party normally owns the rights to a life insurance contract?","options":["The insured's physician","The reinsurer","The policyowner","The contingent beneficiary"],"answer":2,"explanation":"The policyowner controls contractual rights such as beneficiary changes when permitted.","conceptId":"C016","variant":1,"id":"E10Q63"},{"category":"Provisions & Riders","stem":"A beneficiary is reviewing policy features. A trainee gives the following mistaken explanation: \"A beneficiary to set the premium.\" Which answer most accurately corrects the misunderstanding?","options":["The insurer to ignore the application","An owner to avoid all taxes forever","A beneficiary to set the premium","The policyowner to review the delivered policy and return it within the allowed period under applicable terms"],"answer":3,"explanation":"Free look permits cancellation within a specified review window, with refund terms governed by law and policy.","conceptId":"C075","variant":2,"id":"E10Q64"},{"category":"Annuities & Retirement","stem":"An agent is explaining a retirement-income illustration. The proposed advice is: \"To choose the insurer's chief executive.\" Select the statement that should replace this inaccurate advice.","options":["To guarantee annual returns","To eliminate income tax in all cases","To direct any payable death benefit or remaining contract value under contract terms","To choose the insurer's chief executive"],"answer":2,"explanation":"A designation determines who receives amounts payable at death subject to the contract and law.","conceptId":"C099","variant":4,"id":"E10Q65"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. Someone insists: \"Payment of the employee's disability income only.\" Which of the following would be the most accurate response?","options":["Payment of the employee's disability income only","An unrelated property casualty deductible","A guaranteed public share price","Purchase of a deceased owner's business interest according to the agreement"],"answer":3,"explanation":"Life insurance can provide funds for ownership transition on a business owner's death.","conceptId":"C158","variant":3,"id":"E10Q66"},{"category":"Term & Whole Life","stem":"An adviser is comparing temporary and lifelong protection. The proposed advice is: \"Insuring clause.\" Select the statement that should replace this inaccurate advice.","options":["Insuring clause","Assignment","Renewability","Settlement option"],"answer":2,"explanation":"A renewable term feature permits renewal for another term without a new medical examination, usually at higher age-based rates.","conceptId":"C027","variant":4,"id":"E10Q67"},{"category":"Ethics & CA Law","stem":"A California producer is explaining the applicable compliance standard. Someone insists: \"Keep premiums regardless of policy status.\" Which of the following would be the most accurate response?","options":["Handle entrusted premiums honestly and remit/account for them as required","Keep premiums regardless of policy status","Use premiums as personal funds temporarily","Lend client premiums without permission"],"answer":0,"explanation":"Producers must properly safeguard and account for money received in their insurance capacity.","conceptId":"C138","variant":3,"id":"E10Q68"},{"category":"Underwriting & Claims","stem":"An underwriter is reviewing a life application. A trainee gives the following mistaken explanation: \"Pay every applicant a dividend.\" Which answer most accurately corrects the misunderstanding?","options":["Begin underwriting an entirely new insured","Pay every applicant a dividend","Verify coverage and claim facts, then determine benefits under policy and law","Transfer ownership to the agent"],"answer":2,"explanation":"Claims adjudication confirms the policy and the claimant's entitlement.","conceptId":"C130","variant":2,"id":"E10Q69"},{"category":"Term & Whole Life","stem":"A parent wants to protect dependents through working years. A trainee gives the following mistaken explanation: \"Cancellation of premiums forever.\" Which answer most accurately corrects the misunderstanding?","options":["Cancellation of premiums forever","Immediate payment of death proceeds to the living insured","Automatic change of insured person","Exchange into eligible permanent coverage without new evidence of insurability within the permitted period"],"answer":3,"explanation":"Conversion preserves a path to permanent life coverage subject to contract restrictions.","conceptId":"C028","variant":2,"id":"E10Q70"},{"category":"Term & Whole Life","stem":"A consumer reviews long-term premium commitments. Someone insists: \"Traditional whole life only.\" Which of the following would be the most accurate response?","options":["Variable universal life","Traditional whole life only","Credit life only","Fixed term life"],"answer":0,"explanation":"Variable universal life combines UL flexibility and market-linked separate-account investments.","conceptId":"C038","variant":3,"id":"E10Q71"},{"category":"Underwriting & Claims","stem":"An applicant is clarifying underwriting steps. A trainee gives the following mistaken explanation: \"Whether the beneficiary likes the policy.\" Which answer most accurately corrects the misunderstanding?","options":["Whether material application misrepresentations or other valid grounds affect coverage","Whether dividends were reinvested","Whether the agent is still employed","Whether the beneficiary likes the policy"],"answer":0,"explanation":"The insurer may investigate a death within the contestability period under applicable law.","conceptId":"C123","variant":2,"id":"E10Q72"},{"category":"Business & Tax","stem":"A producer is explaining business and estate planning. The proposed advice is: \"Every shareholder from stock-price declines.\" Select the statement that should replace this inaccurate advice.","options":["An employee's car against theft","Every shareholder from stock-price declines","The company's group health deductible","A business from financial loss caused by death of an important employee or owner"],"answer":3,"explanation":"Key-person insurance can provide liquidity while the company recruits or replaces key talent.","conceptId":"C157","variant":4,"id":"E10Q73"},{"category":"Provisions & Riders","stem":"An insured asks about a clause before paying the next premium. A trainee gives the following mistaken explanation: \"A refund whenever the insured gets sick.\" Which answer most accurately corrects the misunderstanding?","options":["A refund whenever the insured gets sick","A guaranteed policy dividend","An additional benefit when death meets the rider's definition of accident","An automatic retirement annuity"],"answer":2,"explanation":"Accidental death riders pay only under defined accidental-death conditions and exclusions.","conceptId":"C071","variant":2,"id":"E10Q74"},{"category":"Ethics & CA Law","stem":"A consumer raises a California insurance compliance question. Someone insists: \"Using relevant mortality experience.\" Which of the following would be the most accurate response?","options":["Following filed actuarial rules","Using relevant mortality experience","Charging different premiums for justified risk classes","Treating people with the same risk classification differently without a lawful underwriting basis"],"answer":3,"explanation":"Risk distinctions must have a lawful actuarial or underwriting justification; unfair discrimination is prohibited.","conceptId":"C137","variant":3,"id":"E10Q75"}]}];
